/* 統測電機與電子群專業科目歷屆真題（技專校院入學測驗中心公告試題）
   由 統測專業科目真題/build_exams.py 產生，不要手改。 */
var EXAM = [];
EXAM.push({"code": "115E2", "y": 115, "p": "E2", "sub": "電工機械、電工機械實習", "items": [{"n": 1, "img": "115E2_1.webp", "ans": "C", "sol": "由 B = μH 得 H = B/μ = 1/(4×10⁻³) = 250 安匝/公尺。再由 H = NI/l 得 N = H·l/I = 250 × 0.1 / 1 = 25 匝。截面積 0.5 m² 是用不到的誘餌。"}, {"n": 2, "img": "115E2_2.webp", "ans": "B", "sol": "感應電勢大小 E = B·l·v = 0.2 × 0.25 × 10 = 0.5 V。磁場進入紙面、導體向下移動，用右手定則（F = qv × B）可知正電荷被推向右端 a，所以 a 為正，Eab = +0.5 V。"}, {"n": 3, "img": "115E2_3.webp", "ans": "A", "sol": "導磁係數 μ = B/H，也就是曲線上各點與原點連線的斜率。α 是 S 形曲線：一開始斜率小、中段最大、飽和後又變小，所以 μα 先增加後減少。β 是通過原點的直線，μβ 固定不變，(B)(D) 都錯。"}, {"n": 4, "img": "115E2_4.webp", "ans": "C", "sol": "雙分疊繞的並聯路徑數 a = m×P = 2×6 = 12，IA = 60/12 = 5 A；雙分波繞 a = 2m = 2×2 = 4，IB = 60/4 = 15 A。所以 IB/IA = 3。疊繞路徑多、每條電流小，波繞剛好相反。"}, {"n": 5, "img": "115E2_5.webp", "ans": "D", "sol": "電刷偏移 α 機械角時，每極的去磁導體數 = Z × 2α/360 = 600 × (2×15)/360 = 50 根。順旋轉方向偏移的是去磁作用，交磁作用則是其餘的導體。"}, {"n": 6, "img": "115E2_6.webp", "ans": "D", "sol": "IL = 10000/200 = 50 A，分激場電流 Ish = 200/100 = 2 A，所以 Ia = 52 A。Eg = 200 + 52×0.05 + 2×0.7 = 204 V。電壓調整率 = (204-200)/200 = 2%。兩個電刷壓降要各算一次。"}, {"n": 7, "img": "115E2_7.webp", "ans": "B", "sol": "半載輸出 10 kW，效率 80% 表示輸入 12.5 kW，總損失 2500 W。扣掉固定損失 2000 W，半載的變動損失是 500 W。變動損失與負載平方成正比，滿載時 = 500 × 2² = 2000 W。"}, {"n": 8, "img": "115E2_8.webp", "ans": "D", "sol": "N 極在上、S 極在下，磁場方向向下；電流流入紙面。由 F = IL × B（左手開掌定則）可得受力方向向左。"}, {"n": 9, "img": "115E2_9.webp", "ans": "B", "sol": "串激機磁通未飽和時 T ∝ Ia²，轉矩變成 1/4 表示電樞電流減半成 10 A。原本 E = 200 - 20×1 = 180 V；轉速不變且 N ∝ E/Ia，所以 E' = 180 × (10/20) = 90 V。V' = 90 + 10×1 = 100 V。"}, {"n": 10, "img": "115E2_10.webp", "ans": "B", "sol": "原本 E1 = 200 - 40×0.5 = 180 V。他激機磁通固定，E ∝ N，降速到 800 rpm 時 E2 = 180 × 800/1200 = 120 V。此時電樞迴路總電阻為 0.5 + 3.5 = 4 Ω，Ia2 = (200-120)/4 = 20 A。"}, {"n": 11, "img": "115E2_11.webp", "ans": "C", "sol": "匝數比 a = 3300/1650 = 2。阻抗換算到另一側要乘以匝數比的平方：Z' = a²Z = 4 × 82.5 = 330 Ω。"}, {"n": 12, "img": "115E2_12.webp", "ans": "C", "sol": "內鐵式鐵心呈口字形、繞組包在鐵心柱外，漏磁較大但絕緣距離好做，適合高電壓小電流；外鐵式鐵心呈日字形、鐵心包住繞組，適合低電壓大電流。所以 (A)(B)(D) 都說反了。"}, {"n": 13, "img": "115E2_13.webp", "ans": "B", "sol": "換算到低壓側：I = 10000/200 = 50 A。電壓調整率 ≈ (I·R·cosθ + I·X·sinθ)/V = (50×0.03×0.8 + 50×0.04×0.6)/200 = 2.4/200 = 1.2%。"}, {"n": 14, "img": "115E2_14.webp", "ans": "A", "sol": "鐵損與負載無關，滿載仍是 160 W；銅損與負載平方成正比，滿載 = 50 × 2² = 200 W。滿載輸出 = 10 kVA × 0.8 = 8000 W，η = 8000/(8000+160+200) ≈ 95.7%，約 96%。"}, {"n": 15, "img": "115E2_15.webp", "ans": "C", "sol": "兩部變壓器的阻抗壓降百分比相同、阻抗角也相同，負載就會依額定容量比例分擔。75:150 = 1:2，總負載 75 kVA 時 A 分擔 25 kVA、B 分擔 50 kVA。"}, {"n": 16, "img": "115E2_16.webp", "ans": "B", "sol": "100 V/200 V 接成 100 V/300 V 自耦變壓器後，總容量 = 5 kVA × (300/200) = 7.5 kVA。其中感應（電磁）容量仍是原來的 5 kVA，剩下的 7.5 - 5 = 2.5 kVA 才是直接由導體傳導的容量。"}, {"n": 17, "img": "115E2_17.webp", "ans": "A", "sol": "氣隙越短磁阻越小，建立同樣磁通所需的激磁電流就越小，功率因數也會比較好。同步轉速只由極數與頻率決定，和氣隙無關。"}, {"n": 18, "img": "115E2_18.webp", "ans": "A", "sol": "同步轉速 Ns = 120×60/6 = 1200 rpm，轉子轉速 = (1-0.05)×1200 = 1140 rpm。轉子電流頻率 f2 = s·f = 0.05×60 = 3 Hz。"}, {"n": 19, "img": "115E2_19.webp", "ans": "B", "sol": "轉子轉速等於同步轉速時轉差率為 0，轉子不切割磁力線就沒有感應電流，電磁轉矩為 0，所以感應機永遠達不到同步轉速。無載時轉差率接近 0；負載增加轉差率會變大；同步轉速只由極數與頻率決定。"}, {"n": 20, "img": "115E2_20.webp", "ans": "B", "sol": "MC2 把 X、Y、Z 三端短接在一起形成中性點，是 Y 接；MC1 把 X、Y、Z 分別接到另外兩條電源線，是 Δ 接。Y-Δ 起動就是先閉合 MC2 用 Y 接起動，數秒後打開再閉合 MC1 轉成 Δ 接運轉。"}, {"n": 21, "img": "115E2_21.webp", "ans": "C", "sol": "同一個負載表示輸出功率與功率因數都一樣。由 P = √3·VL·IL·cosθ，電壓從 380 V 降到 220 V 時電流要等比例放大：IL = 3.5 × 380/220 ≈ 6 A。"}, {"n": 22, "img": "115E2_22.webp", "ans": "C", "sol": "A 點 S = 1 代表轉子靜止，對應的就是起動轉矩。B 點是最大（脫出）轉矩不是滿載轉矩；C 點 S = 0 對應同步轉速 1800 rpm 不是 1200；正常運轉區在 B 點與 C 點之間的低轉差率段。"}, {"n": 23, "img": "115E2_23.webp", "ans": "D", "sol": "開路線電壓 440 V 的每相電壓 = 440/√3 ≈ 254 V。每相同步阻抗 Zs = 開路相電壓 / 短路電樞電流 = 254/151 ≈ 1.7 Ω。Y 接要先把線電壓換成相電壓。"}, {"n": 24, "img": "115E2_24.webp", "ans": "A", "sol": "Y 接時線電流等於相電流，IL = S/(√3·VL) = 100000/(√3×380) ≈ 152 A。"}, {"n": 25, "img": "115E2_25.webp", "ans": "D", "sol": "輸出 = 500 kVA × 0.85 = 425 kW，輸入 = 425/0.9 ≈ 472.2 kW，損失 = 472.2 - 425 ≈ 47.2 kW。"}, {"n": 26, "img": "115E2_26.webp", "ans": "D", "sol": "同步電動機的轉速被電源頻率鎖住不會改變，負載增加時是靠負載角（轉矩角）變大來產生更大的轉矩。定子電壓由電源決定，轉子激磁是直流沒有頻率可言。"}, {"n": 27, "img": "115E2_27.webp", "ans": "B", "stem": "115E2_s27-28.webp", "sol": "J、K 是激磁場繞組的端子，同步機的轉子磁場必須是固定極性的直流磁場，才能被定子的旋轉磁場帶著同步轉動，所以要加直流電源。"}, {"n": 28, "img": "115E2_28.webp", "ans": "D", "stem": "115E2_s27-28.webp", "sol": "Y 接是把三個繞組的同一端接成中性點：R、S、T 分別接 U1、V1、W1，再把 U2、V2、W2 接在一起。Δ 接則是首尾相接（U2 接 V1、V2 接 W1、W2 接 U1）後再從三個接點引出電源。"}, {"n": 29, "img": "115E2_29.webp", "ans": "A", "sol": "同步轉速 Ns = 120×60/4 = 1800 rpm，轉子轉速 = (1-0.05)×1800 = 1710 rpm。順向磁場相對轉子 = 1800 - 1710 = 90 rpm；逆向磁場轉向相反，相對轉子 = 1800 + 1710 = 3510 rpm。"}, {"n": 30, "img": "115E2_30.webp", "ans": "B", "sol": "分相式靠主、輔繞組的阻抗差造成相位差：輔助繞組放在槽的上層、線徑細，電阻大而電感小；主繞組放下層，電阻小而電感大。電容起動式是輔助繞組的磁通越前；永久電容式沒有離心開關；蔽極式是蔽極線圈的磁通落後主磁通。"}, {"n": 31, "img": "115E2_31.webp", "ans": "D", "sol": "起動轉矩比由大到小是電容起動式（約 3～4.5 倍）＞分相式（約 1.5～2 倍）＞永久電容式（約 0.5～1 倍）＞蔽極式（約 0.3～0.5 倍）。蔽極式最簡單也最弱。"}, {"n": 32, "img": "115E2_32.webp", "ans": "B", "sol": "兩相伺服電動機靠控制繞組 A 的電壓相位決定轉向：A 的磁場越前 B 時往一邊轉，落後時往另一邊轉。A 與 B 在空間相差 90 度電機角；A 沒有激磁時只剩單相脈動磁場不會自轉；伺服轉子要用高電阻才能快速反應並避免單相運轉。"}, {"n": 33, "img": "115E2_33.webp", "ans": "D", "sol": "機械角每槽 = 360/24 = 15 度。電機角 = 機械角 × 極對數 = 15 × (8/2) = 60 度。"}, {"n": 34, "img": "115E2_34.webp", "ans": "A", "sol": "線性同步電動機的同步速度 v = 2·τ·f，其中 τ 為極距。v = 2 × 0.05 × 30 = 3 m/s。磁極數不影響速度。"}, {"n": 35, "img": "115E2_35.webp", "ans": "B", "sol": "可變磁阻式步進電動機每次激磁一相時，步進角 = 360 / (轉子齒數 × 相數) = 360 / (6 × 4) = 15 度。定子齒數不列入計算。"}, {"n": 36, "img": "115E2_36.webp", "ans": "A", "sol": "變壓器、配電盤這類帶電設備失火屬於 C 類（電氣）火災；可燃性金屬是 D 類；可燃性液體是 B 類（油類）；木材紙張是 A 類。"}, {"n": 37, "img": "115E2_37.webp", "ans": "B", "sol": "火力（汽輪機）發電機轉速高達 3600 rpm，採臥式、圓柱型（隱極）轉子的同步發電機。水力發電機轉速慢、極數多、轉子直徑大，採立式凸極式同步發電機。發電廠不會用直流發電機。"}, {"n": 38, "img": "115E2_38.webp", "ans": "B", "sol": "要看不同負載下的轉速變化，就要讓負載轉矩成為可以設定的自變數，所以動力計設成轉矩固定模式，逐一改變轉矩再量轉速。若設成轉速固定模式，轉速就被鎖住量不出變化。"}, {"n": 39, "img": "115E2_39.webp", "ans": "C", "sol": "串激機的磁通由電樞電流產生，無載時電流很小、磁通幾乎為零，而 N ∝ E/Φ，轉速會急速飆升到破壞性的程度，所以串激機必須用齒輪或皮帶直接連結負載，不可用皮帶打滑的方式。"}, {"n": 40, "img": "115E2_40.webp", "ans": "D", "sol": "分激發電機要靠剩磁建立電壓，場電阻必須小於臨界電阻，場電阻線才會與磁化曲線交在飽和區。若總場電阻大於臨界電阻，兩線只在原點附近相交，電壓就建立不起來。"}, {"n": 41, "img": "115E2_41.webp", "ans": "A", "sol": "線性區時 T ∝ Φ·Ia ∝ Ia²。負載由 100 公斤重變成 400 公斤重是 4 倍，電流要變成 √4 = 2 倍，所以約 40 A。"}, {"n": 42, "img": "115E2_42.webp", "ans": "C", "sol": "Δ-Y 接線的線電壓在兩側會有 30 度的相位差，這也是三相變壓器並聯時角位移必須相同的原因。Y 側線電壓是相電壓的 √3 倍、線電流等於相電流；Δ 側線電壓等於相電壓、線電流是相電流的 √3 倍。"}, {"n": 43, "img": "115E2_43.webp", "ans": "A", "sol": "開路實驗量的是激磁側：無載功率因數 = W/(V×I) = 22/(110×1) = 0.2。鐵損電流是激磁電流中與電壓同相的分量 = I × cosθ = 1 × 0.2 = 0.2 A。剩下的 0.98 A 是磁化電流。"}, {"n": 44, "img": "115E2_44.webp", "ans": "A", "sol": "離心開關串在輔助繞組上，靜止時應為閉路，轉速到達約 75% 同步轉速才跳開，所以 (D) 錯。輔助繞組或電容任一開路都失去起動轉矩，不能自行起動，但只要用外力把轉子撥動，主繞組的脈動磁場就能維持旋轉，所以 (A) 對、(B) 錯。主繞組斷路則完全不能運轉。"}, {"n": 45, "img": "115E2_45.webp", "ans": "D", "stem": "115E2_s45-46.webp", "sol": "銘牌右側 380 V 是把 ④⑤⑥ 接成中性點、電源接 ①②③，屬於 Y 接；左側 220 V 是把 ①與⑥、②與④、③與⑤ 分別併接後接電源，屬於 Δ 接。要讓這兩種接法都成立，三組繞組必須是 ①④、②⑤、③⑥。"}, {"n": 46, "img": "115E2_46.webp", "ans": "D", "stem": "115E2_s45-46.webp", "sol": "同一電壓下由 Δ 改成 Y，每相繞組電壓降為 1/√3，線電流會變成原來的 1/3，所以 33/3 = 11 A。起動瞬間轉子還沒轉動，轉差率為 1，也就是 100%。"}, {"n": 47, "img": "115E2_47.webp", "ans": "A", "sol": "電感性負載的電樞反應是去磁作用，會削弱主磁場使感應電勢下降，再加上繞組阻抗壓降，端電壓會隨負載電流增加而下降。電容性負載才會因增磁作用使端電壓上升。"}, {"n": 48, "img": "115E2_48.webp", "ans": "C", "sol": "三相輸入功率 P = √3 × VL × IL × cosθ = √3 × 220 × 1 × 0.6 ≈ 229 W。Δ 接或 Y 接都用線電壓與線電流代入同一個公式。"}, {"n": 49, "img": "115E2_49.webp", "ans": "D", "stem": "115E2_s49-50.webp", "sol": "霍爾 IC 輸出的是對地的數位信號，只有高、低兩種準位，不會有負電壓也不是弦波。每轉過一個電機週期，感測到 N 極半圈、S 極半圈，所以是工作週期 50%（高電位佔 T/2）的方波。T/3 是驅動電晶體 120 度導通的區間，不是霍爾信號本身。"}, {"n": 50, "img": "115E2_50.webp", "ans": "C", "stem": "115E2_s49-50.webp", "sol": "霍爾信號的週期就是電機角一週，T = 0.01 s 表示電氣頻率 f = 100 Hz。轉速 N = 120f/P = 120×100/8 = 1500 rpm。8 極機的機械轉速是電氣頻率的 1/4 圈。"}]});
EXAM.push({"code": "114E2", "y": 114, "p": "E2", "sub": "電工機械、電工機械實習", "items": [{"n": 1, "img": "114E2_1.webp", "ans": "C", "sol": "磁滯迴線與 B 軸的交點（H = 0 但 B 不為 0）是剩磁，也就是 ob 線段；與 H 軸的交點（要把 B 降到 0 所需的反向磁場）是矯頑磁力，也就是 oc 線段。迴線包圍的面積則代表每週期的磁滯損失。"}, {"n": 2, "img": "114E2_2.webp", "ans": "D", "sol": "同步電動機是把電能轉換成機械能，不會直接變成光能，所以 (D) 錯誤。發電機是機械能轉電能、感應電動機是電能轉機械能、變壓器是電能轉電能（只改變電壓電流）。"}, {"n": 3, "img": "114E2_3.webp", "ans": "A", "sol": "ω = 314 rad/s 換算轉速 N = 314 × 60/(2π) ≈ 3000 rpm；磁通 5×10⁵ 線 = 5×10⁻³ Wb。E = PΦZN/(60a) = (6 × 5×10⁻³ × 400 × 3000)/(60 × 4) = 150 V。"}, {"n": 4, "img": "114E2_4.webp", "ans": "A", "sol": "電壓調整率 = (無載電壓 - 滿載電壓)/滿載電壓 = (206.2 - 200)/200 = 3.1%。分母要用滿載（額定）電壓。"}, {"n": 5, "img": "114E2_5.webp", "ans": "B", "sol": "串激發電機的磁場由負載電流產生，無載時沒有電流就沒有磁通，電壓建立不起來。外激式需要額外電源、分激式自己供磁不需額外電源、差複激式的端電壓降幅最大，其餘三項都說反了。"}, {"n": 6, "img": "114E2_6.webp", "ans": "C", "sol": "外部特性為線性：G1 由 230 V 降到 200 V 時出 500 A，斜率 30/500 = 0.06 V/A。匯流排 215 V 時壓降 15 V，所以 G1 分擔 15/0.06 = 250 A（G2 的斜率 0.03，分擔 500 A）。"}, {"n": 7, "img": "114E2_7.webp", "ans": "A", "sol": "磁滯損失 Ph 與轉速成正比、渦流損失 Pe 與轉速平方成正比。300 rpm 時 Ph + Pe = 200；900 rpm 是 3 倍轉速，3Ph + 9Pe = 900。解聯立得 Pe = 50 W、Ph = 150 W。"}, {"n": 8, "img": "114E2_8.webp", "ans": "D", "sol": "串激機 Φ ∝ Ia，N ∝ E/Ia。Ia = 10 A 時 E1 = 260 - 10×1 = 250 V；Ia = 20 A 時 E2 = 260 - 20×1 = 240 V。N2 = 2500 × (240/250) × (10/20) = 1200 rpm。"}, {"n": 9, "img": "114E2_9.webp", "ans": "A", "sol": "場磁通控制法是把可變電阻「串聯」在分激場繞組上，調整場電流改變磁通，電樞仍直接跨接電源。串在電樞上的是電樞電阻控制法；並聯在場繞組上的接法無法有效控制場電流。"}, {"n": 10, "img": "114E2_10.webp", "ans": "C", "sol": "轉速特性曲線的定義是：固定端電壓與場電流，看轉速隨電樞電流（也就是隨負載）的變化。固定電樞電流看轉速對轉矩的是轉矩特性；轉速對場電流則是場控特性。"}, {"n": 11, "img": "114E2_11.webp", "ans": "A", "sol": "兩部變壓器的阻抗壓降百分比相同、阻抗角也相同，負載依額定容量比例分擔。50:100 = 1:2，總負載 75 kVA 時 A 分擔 25 kVA、B 分擔 50 kVA。"}, {"n": 12, "img": "114E2_12.webp", "ans": "B", "sol": "低壓側額定電流 = 5000/100 = 50 A，所以負載阻抗 = 100/50 = 2 Ω。換算到高壓側要乘匝數比平方：a = 5，Z' = 25 × 2 = 50 Ω。"}, {"n": 13, "img": "114E2_13.webp", "ans": "D", "sol": "低壓側額定電流 = 20000/500 = 40 A，cosθ = 0.6 時 sinθ = 0.8。電壓調整率 ≈ (40×0.3×0.6 + 40×0.4×0.8)/500 = 20/500 = 4.0%。"}, {"n": 14, "img": "114E2_14.webp", "ans": "C", "sol": "分接頭標示的是「該接頭對應的額定一次電壓」，二次匝數固定。接 2850 V 分接頭時量到 120 V，可反推實際電源電壓 = 120 × 2850/110 ≈ 3109 V。改接 3450 V 分接頭時，二次電壓 = 3109 × 110/3450 ≈ 99 V。分接頭電壓調高，輸出電壓反而降低。"}, {"n": 15, "img": "114E2_15.webp", "ans": "D", "stem": "114E2_s15-16.webp", "sol": "自耦變壓器容量 = 原兩繞組容量 × (輸出電壓/串聯繞組電壓)。用 220 V 繞組當串聯繞組（440 V 輸入、660 V 輸出）時 = 10 × 660/220 = 30 kVA；用 440 V 繞組當串聯繞組（220 V 輸入、660 V 輸出）時 = 10 × 660/440 = 15 kVA。所以最小 15 kVA、最大 30 kVA。"}, {"n": 16, "img": "114E2_16.webp", "ans": "C", "stem": "114E2_s15-16.webp", "sol": "440 V / 660 V 的接法總容量為 30 kVA。其中靠磁耦合傳遞的感應容量仍等於原來的兩繞組容量 10 kVA，剩下的 30 - 10 = 20 kVA 是由導體直接傳導的容量。"}, {"n": 17, "img": "114E2_17.webp", "ans": "D", "sol": "等效電路中 R2'/S 可拆成 R2'（轉子銅損）加上 ((1-S)/S)R2'，後者才是轉換成機械功率的等效電阻。go 與 bm 是激磁分路，代表鐵損與磁化電流。"}, {"n": 18, "img": "114E2_18.webp", "ans": "C", "sol": "轉差率為 0 表示轉子與旋轉磁場同速，轉子不切割磁力線、沒有感應電流，轉矩必為 0。1 > S > 0 是電動機區 T > 0；S > 1 是逆轉制動區；S < 0 是發電機區 T < 0。"}, {"n": 19, "img": "114E2_19.webp", "ans": "A", "sol": "變頻器正是改變電源頻率來控制感應電動機轉速的裝置，鼠籠式與繞線式都適用，也是目前業界的主流做法，所以 (A) 的敘述錯誤。"}, {"n": 20, "img": "114E2_20.webp", "ans": "B", "stem": "114E2_s20-21.webp", "sol": "同步轉速 ns = 120×60/4 = 1800 rpm，而且不會隨轉差率改變。轉子轉速 nr = (1-S)·ns，S 趨近 0 時 nr 趨近 1800 rpm；S 趨近 0.9 時 nr 只有 180 rpm。"}, {"n": 21, "img": "114E2_21.webp", "ans": "B", "stem": "114E2_s20-21.webp", "sol": "輸出 9 kW、效率 90%，所以定子輸入 = 9/0.9 = 10 kW。同步轉速 ns = 120×60/4 = 1800 rpm（1710 rpm 是轉子轉速不是同步轉速）。"}, {"n": 22, "img": "114E2_22.webp", "ans": "D", "sol": "分相式是單相感應電動機的一種，靠主、輔繞組的相位差起動。磁阻式、步進電動機屬於同步型；直流無刷電動機是用電子換相的永磁同步機。"}, {"n": 23, "img": "114E2_23.webp", "ans": "C", "sol": "兩繞組在空間相差 90 度、電流在時間上也相差 90 度，合成的是旋轉磁場不是脈動磁場。由波形可知 iA 越前 iM 90 度；iA 最大時合成磁場指向上方，再過 90 度 iM 最大時指向左方，由上轉到左就是逆時針方向。"}, {"n": 24, "img": "114E2_24.webp", "ans": "B", "sol": "雙值電容式有起動電容與運轉電容兩顆，起動時兩顆並聯得到大起動轉矩，運轉時只留運轉電容得到好的效率與功率因數。電容是串在輔助繞組不是主繞組；電容起動式的起動轉矩很大；電容切換法是用來改變轉向不是控制轉速。"}, {"n": 25, "img": "114E2_25.webp", "ans": "B", "sol": "同步發電機每相感應電勢 E = 4.44·f·N·Φm = 4.44 × 60 × 200 × 0.01 ≈ 533 V。這題給的是每相匝數，算出來就是相電壓。"}, {"n": 26, "img": "114E2_26.webp", "ans": "A", "sol": "電壓調整率 = (無載電壓 - 滿載電壓)/滿載電壓 = (220 - 250)/250 = -12%。負值代表滿載電壓比無載還高，常見於電容性負載造成增磁效應的情況。"}, {"n": 27, "img": "114E2_27.webp", "ans": "A", "sol": "同步發電機並聯的條件：電壓大小相等、頻率相等、相序相同、相位一致、波形相同，五個條件缺一不可。相序接錯會造成極大的環流。"}, {"n": 28, "img": "114E2_28.webp", "ans": "B", "sol": "同步電動機一定以同步轉速運轉，所以由銘牌的 1800 rpm 與 60 Hz 直接反推極數：P = 120f/N = 120×60/1800 = 4 極。"}, {"n": 29, "img": "114E2_29.webp", "ans": "A", "stem": "114E2_s29-30.webp", "sol": "每相電壓 = 380/√3 ≈ 219.4 V。每相功率 = (V·E/Xs)·sinδ = (219.4 × 210/5.5) × sin30° ≈ 4188 W，三相合計約 12.6 kW。同步轉速 1200 rpm = 125.7 rad/s，T = P/ω ≈ 100 N-m。"}, {"n": 30, "img": "114E2_30.webp", "ans": "A", "stem": "114E2_s29-30.webp", "sol": "同步電動機的轉速固定不變，輸出功率 P = (3VE/Xs)·sinδ 只能靠轉矩角 δ 變大來增加。所以 δ 由 30 度增加到 45 度，代表帶動的機械負載變大了。"}, {"n": 31, "img": "114E2_31.webp", "ans": "B", "sol": "可變磁阻式步進電動機單相激磁的步進角 = 360/(轉子齒數 × 相數) = 360/(24×3) = 5 度。要走 75 度就需要 75/5 = 15 個激磁脈波。"}, {"n": 32, "img": "114E2_32.webp", "ans": "C", "sol": "伺服系統都要靠位置或轉速回授做閉迴路控制，這是伺服與一般電動機最大的差別。交流伺服沒有電刷與換向片；伺服轉子要做成細長的低慣量才能快速反應；轉速是靠驅動器調整電壓或頻率不是改電樞電阻。"}, {"n": 33, "img": "114E2_33.webp", "ans": "A", "sol": "X1 為正會使 Q1 的基極得到順向偏壓而導通，電流流經定子繞組 W1 建立磁場，與轉子的 N 極互相作用推動轉子朝逆時針方向旋轉。X2 為負則 Q2 截止。"}, {"n": 34, "img": "114E2_34.webp", "ans": "D", "sol": "火災分類：甲類（A 類）是木材紙張等普通火災、乙類（B 類）是油類、丙類（C 類）是電氣、丁類（D 類）是可燃性金屬。只有 (D) 的對應正確。"}, {"n": 35, "img": "114E2_35.webp", "ans": "B", "sol": "火力電廠的汽輪機轉速高，配合的是臥式圓柱型轉子的交流同步發電機，直接併入電力系統供電。直流發電機無法直接供應交流電網。"}, {"n": 36, "img": "114E2_36.webp", "ans": "D", "sol": "額定電流 = 10000/250 = 40 A，起動電流限制在 2.5 倍即 100 A。起動瞬間反電勢為 0，所以電樞迴路總電阻 = 250/100 = 2.5 Ω，要外串 2.5 - 0.2 = 2.3 Ω。"}, {"n": 37, "img": "114E2_37.webp", "ans": "A", "sol": "分激場電流 2 A × 場電阻 125 Ω = 端電壓 250 V。負載電流 = 750/250 = 3 A，電樞電流 Ia = 3 + 2 = 5 A。E = V + Ia·Ra = 250 + 5×5 = 275 V。"}, {"n": 38, "img": "114E2_38.webp", "ans": "C", "stem": "114E2_s38-39.webp", "sol": "外加電壓 = 場電流 × 場電阻 = 0.5 × 460 = 230 V，輸入電流 = 0.5 + 1.5 = 2 A，輸入功率 = 460 W。輸出 = T·ω = 1.0 × (2π×3000/60) ≈ 314 W。效率 = 314/460 ≈ 68.3%。"}, {"n": 39, "img": "114E2_39.webp", "ans": "B", "stem": "114E2_s38-39.webp", "sol": "不計機械損與雜散損時，電樞產生的電磁功率就等於機械輸出：E·Ia = T·ω。所以 E = 314.16/1.5 ≈ 209.3 V。"}, {"n": 40, "img": "114E2_40.webp", "ans": "B", "sol": "開路實驗量到的 50 W 是鐵損（與負載無關）；短路實驗量到的 200 W 是滿載銅損。半載時銅損 = 200 × 0.5² = 50 W，輸出 = 10 kVA × 0.5 × 0.8 = 4000 W。效率 = 4000/(4000+50+50) ≈ 97.6%。"}, {"n": 41, "img": "114E2_41.webp", "ans": "C", "sol": "匝數與電壓成正比：N2 = N1 × V2/V1 = 1320 × 440/6600 = 88 匝。頻率在這題用不到。"}, {"n": 42, "img": "114E2_42.webp", "ans": "A", "sol": "低壓 Δ 側相電壓等於線電壓 250 V，所以每部變壓器高壓側繞組電壓 = 10 × 250 = 2500 V。高壓 Y 側線電壓 = 2500×√3 ≈ 4330 V。負載視在功率 = 30/0.8 = 37.5 kVA，高壓側線電流 = 37500/(√3 × 4330) = 5.0 A。"}, {"n": 43, "img": "114E2_43.webp", "ans": "D", "sol": "無載實驗時電動機幾乎空轉，轉速非常接近同步轉速，所以可以得知轉差率接近 0。滿載的轉差率與滿載銅損要靠負載實驗或堵轉實驗才量得到；無載轉速應接近 1800 rpm 而不是 1198 rpm。"}, {"n": 44, "img": "114E2_44.webp", "ans": "C", "sol": "三相感應電動機要反轉只需把任意「兩條」相序對調。(A) 對調 V、W，(B) 對調 U、W，(D) 對調 U、V，都會反轉；(C) 是 R→V、S→W、T→U 的三相輪調，相序其實沒有改變，轉向也不會變，所以是錯誤的接法。"}, {"n": 45, "img": "114E2_45.webp", "ans": "A", "sol": "感應電動機在輕載時激磁電流所佔的比例大，功率因數會比滿載時差。半載時輸入電流較小、輸出轉矩較小、轉差率也較小，其餘三個敘述都說反了。"}, {"n": 46, "img": "114E2_46.webp", "ans": "D", "sol": "磁路未飽和時開路電壓與激磁電流成正比。激磁電流由 5 A 降到 4 A，開路線電壓 = 380 × 4/5 = 304 V。"}, {"n": 47, "img": "114E2_47.webp", "ans": "B", "sol": "由表可見激磁電流從 500 mA 減到 50 mA 的過程中，電樞電流 1.30 → 0.41 → 0.65 是先減後增（V 形曲線的谷底在 200 mA 附近），功率因數 0.41 → 0.86 → 0.76 則是先增後減（谷底處功率因數最高接近 1）。"}, {"n": 48, "img": "114E2_48.webp", "ans": "D", "sol": "電容切換法的接法是：電源的 N 固定接 COM，L 經切換開關接到 TA 或 TB。接 TA 時繞組 A 直接跨接電源當主繞組、繞組 B 串聯電容當輔助繞組；接 TB 時兩者角色互換，轉向就相反。只有 (D) 是 N 直接接 COM、L 經開關分別接 TA 與 TB。"}, {"n": 49, "img": "114E2_49.webp", "ans": "C", "sol": "輪轂電動機的外轉子式直接帶動輪圈，轉速低、轉矩大，不需要減速機構；內轉子式轉速高，必須搭配減速機構，減速後可得到更大的轉矩，所以適用於負載較重的場合。"}, {"n": 50, "img": "114E2_50.webp", "ans": "A", "sol": "極距 τ = 12 m / 24 極 = 0.5 m，同步速度 v = 2τf = 2 × 0.5 × 60 = 60 m/s。轉差率 = (60 - 54)/60 = 0.1。"}]});
EXAM.push({"code": "113E2", "y": 113, "p": "E2", "sub": "電工機械、電工機械實習", "items": [{"n": 1, "img": "113E2_1.webp", "ans": "C", "sol": "弗萊明左手定則是電動機定則，右手定則是發電機定則，兩者都只用拇指、食指、中指三根手指。(A) 右手定則的中指代表感應電流不是運動方向。(B) 左手定則的食指代表磁場方向，中指才是電流。(D) 不會用到無名指。所以 (C) 正確。"}, {"n": 2, "img": "113E2_2.webp", "ans": "B", "sol": "磁阻 R = l/(μ A)。A 材料：長度 2 倍、截面積 2 倍、相對導磁係數 50，R(A) 正比於 2/(50 × 2) = 1/50。B 材料：R(B) 正比於 1/(100 × 1) = 1/100。兩者比值 (1/50) : (1/100) = 2 : 1。長度和截面積都放大 2 倍時剛好互相抵消，真正決定比值的是導磁係數。"}, {"n": 3, "img": "113E2_3.webp", "ans": "A", "sol": "鐵損包含磁滯損與渦流損。把鐵心切成一片一片的矽鋼片再疊起來，片與片之間有絕緣，可以切斷渦流的路徑大幅降低渦流損；矽鋼材料本身也能降低磁滯損。和繞組的銅損沒有關係。"}, {"n": 4, "img": "113E2_4.webp", "ans": "A", "sol": "感應電勢 E = P Z Φ n /(60 a)，其中 Z 是導體數。總匝數 250 匝代表導體數 Z = 2 × 250 = 500 根。代入：250 = (4 × 500 × 0.01 × n)/(60 × 4)，解得 n = 3000 rpm。題目選項是每秒轉數，3000/60 = 50 rps。"}, {"n": 5, "img": "113E2_5.webp", "ans": "C", "sol": "(A) 電樞反應是電樞電流產生的磁場造成的，無載時電樞幾乎沒有電流，不會發生。(B) 電樞反應有去磁作用，每極有效磁通量會減少。(C) 在主磁極面上加裝補償繞組，通以與電樞電流相反方向的電流，可以抵消電樞反應，正確。(D) 移動電刷會改變電樞磁動勢的位置，連帶影響有效磁通與感應電勢。"}, {"n": 6, "img": "113E2_6.webp", "ans": "B", "stem": "113E2_s6-7.webp", "sol": "分激式發電機的輸出端電壓就是額定 200 V。負載電流 IL = 10000/200 = 50 A，場電流 If = 200/100 = 2 A。電樞必須同時供應負載和激磁，Ia = IL + If = 50 + 2 = 52 A。"}, {"n": 7, "img": "113E2_7.webp", "ans": "A", "stem": "113E2_s6-7.webp", "sol": "發電機的電樞感應電勢要比端電壓高出電樞壓降：Ea = V + Ia Ra = 200 + 52 × 0.5 = 200 + 26 = 226 V。(如果是電動機就要改成相減，方向不要弄反。)"}, {"n": 8, "img": "113E2_8.webp", "ans": "C", "sol": "直流電動機的轉矩 T 正比於每極磁通量 Φ 與電樞電流 Ia 的乘積。題目說 Ia 維持不變、鐵心也沒有磁飽和，所以 T 只跟 Φ 成正比：T2 = 20 × (0.021/0.015) = 20 × 1.4 = 28 N-m。"}, {"n": 9, "img": "113E2_9.webp", "ans": "A", "sol": "先求反電勢：Ea = V - Ia Ra = 200 - 50 × 0.2 = 190 V。電磁(發展)功率 = Ea × Ia = 190 × 50 = 9500 W，題目說不計機械損失，所以這就是輸出功率。T = P/ω = 9500/250 = 38 N-m。"}, {"n": 10, "img": "113E2_10.webp", "ans": "A", "sol": "(A) 他激式的磁場繞組雖然電源和電樞分開，但繞組裡一樣有激磁電流流過，一樣會產生銅損，敘述錯誤。(B) 分激場跨接在固定端電壓上，場電流固定，損失與負載無關，正確。(C) 磁滯損與渦流損都隨頻率(轉速)上升而變大，正確。(D) 銅損 = I 平方乘 R，正確。"}, {"n": 11, "img": "113E2_11.webp", "ans": "B", "sol": "激磁電流可以分成兩個分量：磁化電流負責建立磁通，和磁通同相位、不消耗實功；鐵損電流負責供應磁滯與渦流損失，和外加電壓同相位。兩者相差 90 度，所以 (B) 說「與鐵損電流同相位」是錯的。"}, {"n": 12, "img": "113E2_12.webp", "ans": "A", "sol": "變壓器兩側的視在功率相同，而且負載只有 3.3 kVA 不是滿載。高壓側電流 = 負載視在功率 / 高壓側電壓 = 3300/220 = 15 A。(低壓側則是 3300/110 = 30 A，別選錯邊。)"}, {"n": 13, "img": "113E2_13.webp", "ans": "C", "sol": "(A) 標么值 = 實際值/基準值，0.5 = 100/基準值，基準值應該是 200 A 不是 50 A。(C) 用標么值表示後，變壓器兩側的標么阻抗相同，不必再換算匝比，計算確實簡化，正確。(D) 標么 1.05 表示實際值比基準值高 5%，不是低。"}, {"n": 14, "img": "113E2_14.webp", "ans": "C", "sol": "CT 變流比 20/5 = 4:1。(A) IR = 4 A，A1 讀 4/4 = 1 A，正確。(B) 讀值 2 A 代表一次側 8 A，正確。(C) A1 量的是 R 相，S 相斷不斷路和 A1 無關，R 相有載 A1 就有讀值，不會是 0，敘述錯誤。(D) 三相平衡時三個二次電流相量和為零，接在中性線上的 An 讀 0 A，正確。"}, {"n": 15, "img": "113E2_15.webp", "ans": "D", "stem": "113E2_s15-16.webp", "sol": "滿載、功率因數為 1 時輸出 = 200 kVA × 1 = 200000 W。總損失 = 鐵損 480 + 滿載銅損 1744 = 2224 W。效率 = 200000/(200000 + 2224) = 98.9%。"}, {"n": 16, "img": "113E2_16.webp", "ans": "A", "stem": "113E2_s15-16.webp", "sol": "(A) 標么值是和自己的額定比，三部接成三相後容量和電流同步放大三倍，無載電流的標么值仍然是 2%，不會變成 6%，敘述錯誤。(B) 銅損 3 × 1744 = 5232 W，正確。(C) 容量 3 × 200 = 600 kVA，正確。(D) 鐵損只看外加電壓、和負載無關，半載時仍是 3 × 480 = 1440 W，正確。"}, {"n": 17, "img": "113E2_17.webp", "ans": "C", "sol": "同步轉速 Ns = 120 f / P，和頻率成正比、和極數成反比。(C) 說和磁極數成正比是錯的。其餘三項都對：旋轉磁場切割轉子感應出電流、把三相任兩相對調即可改變相序與轉向。"}, {"n": 18, "img": "113E2_18.webp", "ans": "C", "sol": "定子鐵心必須用高導磁係數的矽鋼片疊製，才能導磁好又把渦流損壓低。(C) 說用「整塊低導磁材料」正好相反，是錯誤敘述。(A)(B)(D) 都是三相感應電動機的正確描述。"}, {"n": 19, "img": "113E2_19.webp", "ans": "B", "sol": "4 極 60 Hz 的同步轉速 Ns = 1800 rpm。原轉差率 s1 = (1800-1764)/1800 = 0.02，目標 s2 = (1800-1710)/1800 = 0.05。轉矩不變時 R2/s 要維持定值：R2/0.02 = (R2 + Rex)/0.05，得 R2 + Rex = 2.5 R2，所以 Rex = 1.5 R2。"}, {"n": 20, "img": "113E2_20.webp", "ans": "D", "sol": "6 極 60 Hz 的 Ns = 1200 rpm，滿載 1152 rpm，s = (1200-1152)/1200 = 0.04。轉子銅損 = s × 氣隙功率，所以氣隙功率 Pag = 200/0.04 = 5000 W。機械功率 = 5000 - 200 = 4800 W，再扣掉機械損 100 W，轉軸輸出 = 4700 W。"}, {"n": 21, "img": "113E2_21.webp", "ans": "A", "sol": "最大轉矩發生在 轉子電阻 = 轉子電抗(含定子阻抗)時。題目說定子阻抗可忽略，所以 s(maxT) = R2/X2 = 0.3/2 = 0.15。這個轉差率只和轉子的電阻電抗比有關，和外加電壓大小無關。"}, {"n": 22, "img": "113E2_22.webp", "ans": "D", "sol": "低於額定頻率時用定 V/f 控制，磁通固定可得定轉矩區；高於額定頻率時輸出電壓已經頂到額定不能再升，只能維持電壓固定讓磁通隨頻率下降，進入定功率(弱磁)區。(D) 說電壓要隨頻率增加而增加是錯的。"}, {"n": 23, "img": "113E2_23.webp", "ans": "B", "sol": "同步發電機的頻率 f = P N /120，極數固定時頻率和轉速成正比。N = 720 × (50/60) = 600 rpm。(順便可以反推極數：120 × 60/720 = 10 極。)"}, {"n": 24, "img": "113E2_24.webp", "ans": "B", "sol": "每極槽數 = 96/8 = 12 槽，一個極距等於 180 電機度，所以每槽 = 180/12 = 15 電機度。線圈跨距 10 槽 = 150 電機度。節距因數 Kp = sin(跨距角/2) = sin(150/2) = sin75 度。"}, {"n": 25, "img": "113E2_25.webp", "ans": "C", "sol": "時間函數的振幅是 400√2，所以每相(相電壓)有效值 = 400√2/√2 = 400 V。Y 接時線電壓 = √3 倍相電壓，有效值 = 400√3 V(約 692.8 V)。"}, {"n": 26, "img": "113E2_26.webp", "ans": "D", "sol": "由圖可知 If1 是短路特性曲線達到額定電流所需的激磁電流、If2 是開路特性曲線達到額定端電壓所需的激磁電流。短路比 SCR = If2/If1 = 4.5/3 = 1.5。意思也可以這樣看：用 4.5 A 激磁時短路電流是額定電流的 4.5/3 = 1.5 倍。"}, {"n": 27, "img": "113E2_27.webp", "ans": "C", "sol": "12 極 60 Hz 的同步轉速 Ns = 120 × 60/12 = 600 rpm，同步電動機一定跑在同步轉速。角速度 ω = 2π × 600/60 = 62.8 rad/s。輸出功率 P = T ω = 40 × 62.8 ≈ 2513 W，約 2500 W。"}, {"n": 28, "img": "113E2_28.webp", "ans": "C", "sol": "這就是同步電動機的 V 形曲線：激磁不足(欠激)時電樞電流大、功率因數滯後；激磁加大到正常激磁時電樞電流最小、功率因數為 1；再加大變成過激時功率因數轉為超前。所以激磁電流由小到大依序是 I1(滯後) < I2(為 1) < I3(超前)，也就是 I3 > I2 > I1。"}, {"n": 29, "img": "113E2_29.webp", "ans": "D", "sol": "單相感應電動機用雙旋轉磁場理論分析：對順向磁場的轉差率 s = 0.05，對逆向磁場的轉差率 sb = 2 - s = 2 - 0.05 = 1.95。直接推也可以：轉子轉速 = 0.95 Ns，逆向磁場轉速 = -Ns，sb = (-Ns - 0.95Ns)/(-Ns) = 1.95。"}, {"n": 30, "img": "113E2_30.webp", "ans": "D", "sol": "2 HP = 2 × 746 = 1492 W 輸出。輸入功率 = 1492/0.746 = 2000 W。視在功率 = 2000/0.8 = 2500 VA。額定電流 = 2500/220 ≈ 11.36 A。起動電流 = 6 × 11.36 ≈ 68 A。"}, {"n": 31, "img": "113E2_31.webp", "ans": "A", "sol": "可變磁阻型步進電動機的步進角 = 360 度 /(相數 × 轉子齒數) = 360/(3 × 8) = 15 度。注意分母用的是轉子齒數不是定子齒數。"}, {"n": 32, "img": "113E2_32.webp", "ans": "B", "sol": "全長 16 m、8 極，所以極距 τ = 16/8 = 2 m。線性感應電動機的同步速度 vs = 2 τ f = 2 × 2 × 60 = 240 m/s。轉差率 s = (240 - 228)/240 = 0.05 = 5%。"}, {"n": 33, "img": "113E2_33.webp", "ans": "B", "sol": "電容起動式的起動電容器要和起動繞組串聯，才能讓起動繞組的電流相位超前運轉繞組，產生起動轉矩。起動電容只在起動瞬間短時間通電，用的是體積小、容量大的乾式交流電解質電容器(直流電解電容接到交流上會壞)。"}, {"n": 34, "img": "113E2_34.webp", "ans": "C", "sol": "兩個繞組產生的旋轉磁場要合成最大的起動轉矩，起動繞組電流和運轉繞組電流的相位差要等於 90 電機角，而且兩繞組在空間上也剛好差 90 度，這時相當於標準的兩相旋轉磁場。相位差 0 度或 180 度就完全沒有旋轉磁場。"}, {"n": 35, "img": "113E2_35.webp", "ans": "A", "sol": "(A) 非帶電體的金屬外殼平常雖然不帶電，一旦絕緣破損就會變成帶電體，所以一定要接地讓漏電流經由接地線流走，正確。(B) 打赤腳等於人體直接接地，極度危險。(C) 檢修一定要先停電並掛標示。(D) 電線走火要先切斷電源再滅火，而且不能用水。"}, {"n": 36, "img": "113E2_36.webp", "ans": "B", "sol": "要把電壓從 69 kV 變成 22.8 kV 而頻率不變、同樣是三相交流，這就是變壓器的工作。同步發電機是把機械能變電能、整流器會把交流變直流、感應電動機是把電能變機械能，都不符合。"}, {"n": 37, "img": "113E2_37.webp", "ans": "D", "sol": "先把線圈兩邊落在哪一槽讀出來：線圈 A 占第 1 槽與第 6 槽，線圈 B 占第 2 槽與第 7 槽，兩個線圈在圖上是交叉的不是套在一起的。後節距(同一線圈兩邊的距離) = 6 - 1 = 5 槽；前節距是「一個線圈的線尾邊到下一個線圈的線頭邊」，也就是線圈 A 的第 6 槽到線圈 B 的第 2 槽 = 4 槽。合成節距 = 5 - 4 = 1 槽，正是單疊繞的特徵(換向節距也是 1，由換向片 1-2、2-3 可以驗證)。"}, {"n": 38, "img": "113E2_38.webp", "ans": "B", "sol": "無載時電樞電流可忽略，所以無載反電勢 = 端電壓 = 150 V，對應 3000 rpm。滿載時 Ea = 150 - 20 × 0.25 = 145 V。激磁不變時轉速正比於反電勢：N(滿載) = 3000 × 145/150 = 2900 rpm。速率調整率 = (3000 - 2900)/2900 = 3.4%。(分母要用滿載轉速。)"}, {"n": 39, "img": "113E2_39.webp", "ans": "D", "sol": "看轉矩：Ia 由 0.5 變 1.0(2 倍)時 T 由 0.095 變 0.382(約 4 倍)，由 1.0 變 2.0 時 T 又變 4 倍，表示 T 正比於 Ia 的平方。再看轉速：N 乘以 Ia 分別是 4975、4950、4900、4800、4698，幾乎是定值，表示 N 反比於 Ia。轉矩和電流平方成正比、轉速和電流成反比，正是串激式直流電動機的特性。分激式與他激式的 T 是正比於 Ia 的一次方、轉速幾乎不變。"}, {"n": 40, "img": "113E2_40.webp", "ans": "A", "sol": "兩筆數據在同一條直線上：斜率 = (252.5 - 259.0)/(1.5 - 0.2) = -5 V/A。無載(0 A)時 V = 259.0 + 0.2 × 5 = 260 V；額定 2 A 時 V = 260 - 2 × 5 = 250 V。電壓調整率 = (無載 - 滿載)/滿載 = (260 - 250)/250 = 4%。"}, {"n": 41, "img": "113E2_41.webp", "ans": "C", "sol": "開路試驗用電壓表、電流表、瓦特計就能量到鐵損與激磁電流；短路試驗同樣三個表就能量到銅損。但鐵心的磁阻要知道線圈匝數、磁路長度與截面積才算得出來，單靠這三個電表量不到，所以 (C) 錯誤。"}, {"n": 42, "img": "113E2_42.webp", "ans": "D", "sol": "(A) 相電流等於線電流是 Y 接的特徵，正確。(B) Δ-Δ 時三相容量 300 kVA、低壓側線電壓 220 V，線電流 = 300000/(√3 × 220) ≈ 787 A，相電流 = 787/√3 ≈ 455 A，正確。(C) Δ-Y 時低壓側線電壓 = 220 × √3 ≈ 380 V，正確。(D) 少一部變成 V-V(開 Δ)接線，低壓側線電壓仍然是 220 V，不會變成 380 V，只有容量降為原來的 57.7%，敘述錯誤。"}, {"n": 43, "img": "113E2_43.webp", "ans": "D", "sol": "220 V 繞組當共同繞組、110 V 繞組當串聯繞組，升壓成 220 + 110 = 330 V。串聯繞組的額定電流 = 20000/110 ≈ 182 A，所以自耦後的額定容量 = 330 × 182 ≈ 60 kVA，(A)(B) 都不對。至於實際負載，電壓表量到 330 V、電流表量到 2 A，負載容量 = 330 × 2 = 660 VA。"}, {"n": 44, "img": "113E2_44.webp", "ans": "A", "sol": "自耦變壓器降壓起動時，若二次側電壓降為原來的 a 倍，電動機端的起動電流也變 a 倍，而反映到電源側(一次側)的電流是 a 的平方倍。全壓起動電流 4.0 A、降壓後電源側量到 1.0 A，所以 a 平方 = 1.0/4.0 = 0.25，a = 0.5。二次側電壓 = 0.5 × 220 = 110 V。"}, {"n": 45, "img": "113E2_45.webp", "ans": "B", "stem": "113E2_s45-46.webp", "sol": "兩瓦特計法的總功率 = Wa + Wb = 88 + 32 = 120 W。堵轉時轉子不動，輸入功率幾乎全部消耗在定子與轉子的等效電阻上。定子是 Y 接，三相電流都是 1.4 A，所以每相等效電阻 = 120/(3 × 1.4 平方) = 120/5.88 ≈ 20.4 Ω，約 20 Ω。"}, {"n": 46, "img": "113E2_46.webp", "ans": "D", "stem": "113E2_s45-46.webp", "sol": "輸入功率 = Wa + Wb = 36 + 220 = 256 W。輸出功率 = 轉矩 × 角速度 = 1 × 182.42 = 182.42 W。效率 = 182.42/256 ≈ 71.2%。(兩瓦特計法只要把兩個讀值相加就是三相總功率，不必再乘 √3。)"}, {"n": 47, "img": "113E2_47.webp", "ans": "B", "sol": "電樞是 Y 接，直流電源跨接在兩條線端上，電流走的是「兩相繞組串聯」的路徑。量到的總電阻 = 12/5 = 2.4 Ω，那是兩相串聯的值，所以每相直流電阻 = 2.4/2 = 1.2 Ω。(實用上還要再乘有效電阻係數，但本題只問直流電阻。)"}, {"n": 48, "img": "113E2_48.webp", "ans": "D", "sol": "同步電動機只要不失步，轉速永遠鎖在同步轉速，不會隨負載下降。負載轉矩增加時，轉子磁極會再往後退一點以產生更大的轉矩，也就是負載角(功率角)的絕對值變大。負載角太大超過極限就會失步停轉。"}, {"n": 49, "img": "113E2_49.webp", "ans": "C", "sol": "(C) 線性電動機把旋轉電機展開成直線，直接產生直線推力，可以取代油壓氣壓缸、滾珠螺桿這些把旋轉轉成直線的機構，正確。(A) 無刷電動機本來就沒有電刷與換向片。(B) 伺服電動機轉子慣量做得很小才能快速響應，而且定位控制正是它的強項。(D) 步進電動機靠脈波個數控角度、靠脈波頻率控轉速，兩者都能控。"}, {"n": 50, "img": "113E2_50.webp", "ans": "D", "sol": "輪轂式直流無刷電動機的負載特性實驗，是在轉速固定下逐步改變負載，記錄電壓、電流、瓦特計讀值與轉速、輸出轉矩，再算出輸出功率與效率，畫成特性曲線。既然是「負載特性」實驗，輸出轉矩當然要隨負載改變，(D) 說保持不變是錯的。"}]});
EXAM.push({"code": "112E2", "y": 112, "p": "E2", "sub": "電工機械、電工機械實習", "items": [{"n": 1, "img": "112E2_1.webp", "ans": "B", "sol": "單相感應電動機依起動方式分成分相式、電容式(電容起動式、永久電容式、電容起動電容運轉式)、蔽極式、推斥式等。並沒有「電感式電動機」這個分類。"}, {"n": 2, "img": "112E2_2.webp", "ans": "D", "sol": "磁通密度 B 的單位是每單位面積的磁通量：韋伯/平方公尺，也就是特斯拉；CGS 制則用高斯(1 特斯拉 = 10000 高斯)。馬克士威爾是 CGS 制的「磁通量」單位(1 韋伯 = 10 的 8 次方馬克士威爾)，不是磁通密度。"}, {"n": 3, "img": "112E2_3.webp", "ans": "C", "sol": "輸出功率 = 14500 × 0.8 = 11600 W，負載電流 IL = 11600/200 = 58 A。分激場電流 If = 200/100 = 2 A，所以電樞電流 Ia = 58 + 2 = 60 A。電樞銅損 = 60 的平方 × 0.2 = 720 W、分激場銅損 = 2 的平方 × 100 = 400 W，合計 1120 W。(剩下的 2900 - 1120 = 1780 W 是鐵損與機械損，不要整個當成銅損。)"}, {"n": 4, "img": "112E2_4.webp", "ans": "A", "sol": "由圖上兩點求直線：斜率 = (300 - 305)/(120 - 100) = -0.25 V/A，無載端電壓 = 305 + 100 × 0.25 = 330 V，所以 Vt = 330 - 0.25 IL。外接 10.75 Ω 時 Vt 也等於 10.75 IL，令兩式相等：10.75 IL = 330 - 0.25 IL，11 IL = 330，IL = 30 A。"}, {"n": 5, "img": "112E2_5.webp", "ans": "C", "sol": "滿載電流 = 20000/200 = 100 A，Ea(滿載) = 200 + 100 × 0.5 = 250 V。半載電流 50 A，端電壓仍要 200 V，所以 Ea(半載) = 200 + 50 × 0.5 = 225 V。轉速不變且在線性區時 Ea 正比於激磁電流：If = 5 × 225/250 = 4.5 A。"}, {"n": 6, "img": "112E2_6.webp", "ans": "D", "sol": "(D) 差複激就是把串激場的磁通做成和分激場相反，互相削弱，正確。(A) 串激場是用「並聯」分流電阻(分流器)來調整。(B) 分激場是用「串聯」可變電阻來調整。(C) 欠複激在滿載時端電壓仍低於無載值，電壓調整率是正值；要做到負值得靠過複激。"}, {"n": 7, "img": "112E2_7.webp", "ans": "B", "sol": "(B) 在主磁極極面開槽嵌入補償繞組，通以和電樞電流反向的電流，可以抵消電樞磁動勢，是改善電樞反應最有效的方法。(A) 電樞反應由電樞電流造成，負載愈大影響愈大。(C) 鐵心疊片是為了降低渦流損，和電樞反應無關。(D) 2 極機的磁中性面偏移量遠小於 90 度，而且方向隨負載改變。"}, {"n": 8, "img": "112E2_8.webp", "ans": "ABCD", "note": "官方公告本題送分。", "sol": "本題官方公告送分。原因是題目給的參數互相矛盾：額定時 Ea = 300 - 100 × (0.3 + 0.2) = 250 V，內生機械功率 = 250 × 100 = 25000 W，但由轉矩算出的輸出功率 = 200 × (2π × 1500/60) = 31416 W，輸出竟然大於內生功率，不合物理。所以四個選項都給分。"}, {"n": 9, "img": "112E2_9.webp", "ans": "A", "sol": "起動瞬間轉速為零、反電勢 Ea = 0，電樞電流 = 外加電壓 / 電樞電阻，完全由電源電壓與電樞電阻決定，和軸上掛多少負載無關，所以 (A) 正確、(B)(D) 都錯。(C) 剛好相反，電樞電阻正是決定起動電流的關鍵，所以才要加起動電阻。"}, {"n": 10, "img": "112E2_10.webp", "ans": "B", "sol": "長並聯接法的分激場直接跨在電源 200 V 上：If = 200/20 = 10 A，電樞電流 Ia = 90 - 10 = 80 A(串激場和電樞串聯，流的也是 80 A)。反電勢 Ea = 200 - 80 × (0.2 + 0.3) = 160 V。電磁功率 = Ea × Ia = 160 × 80 = 12800 W，T = 12800/200 = 64 N-m。"}, {"n": 11, "img": "112E2_11.webp", "ans": "A", "sol": "變壓器的激磁導納分成兩個分量：G0 是電導，代表和外加電壓同相、會消耗實功的鐵損成分；B0 是電納，代表建立磁通的磁化成分、不消耗實功。R1、X1 是一次側繞組本身的電阻與漏抗(銅損與漏磁)。所以鐵損要看 G0。"}, {"n": 12, "img": "112E2_12.webp", "ans": "D", "sol": "基準阻抗 = 基準電壓的平方 / 基準容量 = 10000 的平方 / 100000 = 1000 Ω。等效阻抗 = 0.04 × 1000 = 40 Ω。至於標么值，題目就是以高壓側額定值為基準，所以仍然是 0.04 = 4%(標么值不會因為換到哪一側而改變)。"}, {"n": 13, "img": "112E2_13.webp", "ans": "A", "sol": "最大效率的條件是「銅損 = 鐵損」，題目說 0.75 載時達到最大效率，那是用來反推滿載銅損的條件。但本題只問鐵損：鐵損只跟外加電壓與頻率有關、和負載無關，所以不論滿載、0.75 載還是半載，鐵損都是 3 kW。"}, {"n": 14, "img": "112E2_14.webp", "ans": "D", "sol": "(A) 三部各 100 kVA，合計 300 kVA，正確。(B) Δ-Y 的低壓側是 Y 接，相電壓 110 V，線電壓 = 110√3 ≈ 190 V，正確。(C) 高壓側是 Δ 接、線電壓 220 V，線電流 = 300000/(√3 × 220) ≈ 787 A，正確。(D) 低壓側線電流 = 300000/(√3 × 190) ≈ 909 A，不是 1574 A，敘述錯誤。"}, {"n": 15, "img": "112E2_15.webp", "ans": "D", "sol": "開路實驗加在低壓側：(A) 開路時電流很小、銅損可忽略，瓦特表讀的 1100 W 就是鐵損，正確。(B) 等效電導 G0 = P/V 的平方 = 1100/220 的平方 ≈ 0.0227 西門子，正確。(C) 總導納 Y0 = 10/220 ≈ 0.04545 S，磁化電納 B0 = 根號(Y0 平方 - G0 平方) ≈ 0.0394 S，磁化電流 = 0.0394 × 220 ≈ 8.7 A，正確。(D) 無載功率因數 = 1100/(220 × 10) = 0.5，不是 0.3，敘述錯誤。"}, {"n": 16, "img": "112E2_16.webp", "ans": "A", "sol": "高壓側是 Δ 接、線電壓 22.8 kV，滿載線電流 = 1000000/(√3 × 22800) ≈ 25.3 A。CT 的一次額定要略大於實際最大電流才不會飽和，選 30 A/5 A 最合適；20 A/5 A 以下都會超載。"}, {"n": 17, "img": "112E2_17.webp", "ans": "C", "sol": "輸入功率 = 95/0.95 = 100 kW。原本 PF = 0.8 落後，無效功率 Q = 100 × (0.6/0.8) = 75 kVAR。裝了 42.1 kVAR 的電容後 Q 剩下 75 - 42.1 = 32.9 kVAR。新的功率因數 = 100/根號(100 的平方 + 32.9 的平方) ≈ 0.95，而且電容沒有補過頭(Q 仍為正)，所以還是落後。"}, {"n": 18, "img": "112E2_18.webp", "ans": "B", "sol": "4 極 60 Hz 的同步轉速 = 1800 rpm，s = (1800 - 1710)/1800 = 0.05 = 5%。機械損忽略，所以軸輸出 20 kW 就等於機械功率 Pm。氣隙功率 Pag = Pm/(1 - s) = 20/0.95 ≈ 21.05 kW，轉子銅損 = s × Pag = 0.05 × 21.05 ≈ 1.05 kW。"}, {"n": 19, "img": "112E2_19.webp", "ans": "C", "sol": "6 極 60 Hz 的 Ns = 1200 rpm，運轉時 s = (1200 - 1150)/1200 = 1/24。題目給的 10 V 與 0.5 Ω 是「運轉時」的值，要先換算回起動時(s = 1)：E2 = 10 ÷ (1/24) = 240 V、X2 = 0.5 ÷ (1/24) = 12 Ω。起動電流 = 240/根號(5 的平方 + 12 的平方) = 240/13 ≈ 18.5 A。"}, {"n": 20, "img": "112E2_20.webp", "ans": "A", "sol": "4 極 60 Hz 的 Ns = 1800 rpm，s = (1800 - 1710)/1800 = 0.05。題目給的 200 V 與 4 Ω 是「起動瞬間」的值，要乘上 s 才是額定負載時：感應電勢 = 0.05 × 200 = 10 V、電抗 = 0.05 × 4 = 0.2 Ω，電阻不隨轉差率改變仍是 2 Ω。I2 = 10/根號(2 的平方 + 0.2 的平方) ≈ 5 A。"}, {"n": 21, "img": "112E2_21.webp", "ans": "A", "stem": "112E2_s21-23.webp", "sol": "繞線式感應電動機在轉子外加電阻時，轉矩-轉差率曲線會往轉差率大的方向拉開。負載轉矩不變的話，工作點就移到轉差率較大的地方，也就是轉速降低、轉差率變大。這正是外加電阻控速法的原理，代價是外加電阻會多消耗電能。"}, {"n": 22, "img": "112E2_22.webp", "ans": "B", "stem": "112E2_s21-23.webp", "sol": "最大轉矩的大小只和電源電壓、定子阻抗與轉子電抗有關，和轉子電阻完全無關；轉子電阻只會改變「發生最大轉矩的轉差率」。所以外加 3 Ω 之後，最大轉矩仍是滿載轉矩的 250%。"}, {"n": 23, "img": "112E2_23.webp", "ans": "C", "stem": "112E2_s21-23.webp", "sol": "發生最大轉矩時的轉差率和轉子每相總電阻成正比。原本 R2 = 3 Ω 對應 s = 20%，外加 3 Ω 後總電阻變成 6 Ω(2 倍)，所以 s 也變成 2 倍 = 40%。"}, {"n": 24, "img": "112E2_24.webp", "ans": "B", "sol": "運轉繞組 4 + j3，電流落後電壓 36.9 度。要讓起動繞組電流超前運轉繞組電流 90 度，起動支路的電流要超前電壓 90 - 36.9 = 53.1 度，也就是起動支路的阻抗角是 -53.1 度。設容抗 Xc：tan(-53.1 度) = (2 - Xc)/6，-4/3 = (2 - Xc)/6，得 Xc = 10 Ω。C = 1/(2π × 60 × 10) ≈ 265 μF。"}, {"n": 25, "img": "112E2_25.webp", "ans": "D", "sol": "甲：三相繞組在空間上要互隔 120 電機角，不是 150 度。乙：4 極 60 Hz 的同步轉速正是 1800 rpm，用 1800 rpm 的汽輪式原動機帶動沒問題。丙：極數少、轉速高的機器要用隱極(圓柱)式轉子；凸極式適合極數多、轉速低的水輪發電機。丁：在磁極極面裝阻尼繞組可以抑制追逐(hunting)，正確。所以乙丁正確。"}, {"n": 26, "img": "112E2_26.webp", "ans": "B", "sol": "每極槽數 = 96/4 = 24，一個極距 180 電機角，所以每槽 180/24 = 7.5 電機角。線圈放在第 1 和第 19 槽，跨 18 槽 = 135 電機角，節距因數 Kp = sin(135/2) = sin67.5 度 ≈ 0.92(小於 1，表示感應電勢「變小」，所以甲說變成 1.12 倍是錯的)。每極每相槽數 q = 96/(4 × 3) = 8，分佈因數 Kd = sin(8 × 7.5/2)/(8 sin3.75 度) = 0.5/(8 × 0.065) ≈ 0.96，乙正確。每相導體 400 根等於 200 匝：E = 4.44 × 0.92 × 0.96 × 60 × 200 × 0.01 ≈ 470 V，丙正確。丁：要消除第三次諧波，跨距要做成極距的 2/3 = 24 × 2/3 = 16 槽，不是 12 槽。所以乙丙正確。"}, {"n": 27, "img": "112E2_27.webp", "ans": "A", "sol": "(A) 電樞反應就是負載電流產生的電樞磁通去干擾主磁極磁通，造成加磁、去磁或波形畸變，正確。(B) 功率因數落後時電樞反應是「去磁 + 正交磁」，感應電勢會減少不是增加。(C) 功率因數超前時是「加磁 + 正交磁」，感應電勢增加。(D) PF 為零落後時電樞磁通與主磁通「反相」，是純去磁，不含正交磁。"}, {"n": 28, "img": "112E2_28.webp", "ans": "D", "sol": "同步阻抗標么值 = 1/短路比。先算短路比：用 3.6 A 激磁可以得到額定電壓，而用 3 A 激磁就能讓短路電流達到額定值，所以若把激磁加到 3.6 A，短路電流會是額定的 3.6/3 = 1.2 倍，短路比 = 1.2。Zs(標么) = 1/1.2 ≈ 0.83。"}, {"n": 29, "img": "112E2_29.webp", "ans": "B", "sol": "這是同步電動機的 V 形曲線。激磁電流由小變大時：電樞電流先減小、到正常激磁(PF = 1)時「最小」，再增大；功率因數則先升高、在正常激磁時達到「最大」的 1，再下降。(B) 說電樞電流先增後減、正常激磁時最大而功率因數最小，整個反過來了，所以錯誤。(A)(C)(D) 的描述都符合 V 形曲線的行為。"}, {"n": 30, "img": "112E2_30.webp", "ans": "D", "sol": "4 極 60 Hz 的同步轉速 = 1800 rpm，角速度 = 2π × 1800/60 = 188.5 rad/s(同步電動機一定跑同步轉速)。輸入功率 = √3 × 線電壓 × 線電流 × PF = √3 × 220√3 × 10 × 0.8 = 5280 W。輸出 = 5280 × 0.9 = 4752 W。T = 4752/188.5 ≈ 25.2 N-m。"}, {"n": 31, "img": "112E2_31.webp", "ans": "B", "sol": "甲：靠轉子表面永久磁鐵和定子磁極吸引來產生轉矩的是「永久磁鐵型」，混合型是永磁加上齒形磁阻兩種效應並用。丙：靠定、轉子間磁阻變化產生轉矩的是「可變磁阻型」，不是永久磁鐵型。這兩項剛好說反了。乙：脈波頻率控轉速、激磁順序控轉向，正確。丁：四相 VR 型採 1-2 相激磁，步進角 = 360/(4 × 30 × 2) = 1.5 度；50 rpm 代表每秒轉 50/60 圈 = 300 度，除以 1.5 度/步 = 200 步/秒，也就是 200 Hz，正確。所以乙丁。"}, {"n": 32, "img": "112E2_32.webp", "ans": "C", "sol": "甲：伺服機要能快速起停並精準定位，所以需要起動轉矩大、轉子慣性小、轉矩-轉速線性、散熱好，正確。丙：同步型(永磁)伺服機要靠頻率可調的三相變頻器來驅動，正確。乙：永磁式直流伺服機的磁場是永久磁鐵，根本不能調整，只能用電樞電壓(電流)控制法。丁：伺服系統的定義就是要有回授，一定是閉迴路，開迴路的是步進電動機。所以甲丙。"}, {"n": 33, "img": "112E2_33.webp", "ans": "B", "sol": "電動汽車的主驅動馬達目前主流是三相永磁式同步電動機(PMSM)，功率密度高、效率好，配合變頻器(逆變器)做向量控制。直流電動機有電刷維護問題、單相感應電動機功率太小、步進電動機是定位用的，都不適合當動力來源。"}, {"n": 34, "img": "112E2_34.webp", "ans": "C", "sol": "2 極、12 槽代表極距 = 12/2 = 6 槽。全節距表示線圈兩邊剛好相隔一個極距，所以後節距 Yb = 6 槽。單分前進疊繞的合成節距是 1 槽，前節距 Yf = Yb - 1 = 5 槽。(若是後退疊繞則 Yf = Yb + 1 = 7 槽。)"}, {"n": 35, "img": "112E2_35.webp", "ans": "C", "sol": "磁路雖然沒有飽和，但鐵心有磁滯現象：激磁電流從 100 mA 降回 80 mA 時，磁通不會完全回到當初上升時的那個值，會比原本的 112 V 稍微高一點點。所以合理的實驗數據是略高於 112 V，也就是 112 V 到 120 V 這個範圍。"}, {"n": 36, "img": "112E2_36.webp", "ans": "A", "sol": "直流電動機的負載特性實驗要觀察「電壓固定時，轉速與轉矩隨負載怎麼變」，所以電源要加額定電壓；而制動器(電力制動控制器)要設在定轉矩模式，才能一段一段地把轉矩設定上去、逐點記錄轉速。設成定轉速模式就量不到轉速的變化了。"}, {"n": 37, "img": "112E2_37.webp", "ans": "D", "sol": "電氣火災(C 類)要用不導電的滅火劑。二氧化碳不導電、滅火後不留殘渣，不會損壞電氣設備，是最合適的。水和泡沫都會導電，噴上去會造成觸電與短路；潤滑液更不是滅火器材。"}, {"n": 38, "img": "112E2_38.webp", "ans": "C", "sol": "開路實驗量到的 1000 W 是鐵損(固定損)。短路實驗的電流 8 A 正好等於高壓側額定電流(80000/10000 = 8 A)，所以 1600 W 就是滿載銅損。最高效率發生在「銅損 = 鐵損」：設負載率 k，k 的平方 × 1600 = 1000，k = 根號(1000/1600) = 根號10/4 ≈ 0.79。負載 = 0.79 × 80 ≈ 63 kVA。"}, {"n": 39, "img": "112E2_39.webp", "ans": "C", "sol": "輸入 200 V、100 A，總容量 = 20 kVA；輸出 250 V，所以輸出電流 = 20000/250 = 80 A。自耦變壓器的「直接傳導(電導)容量」是輸入電壓乘以輸出電流 = 200 × 80 = 16 kVA(剩下的 4 kVA 才是靠電磁感應傳遞的)。共用(並聯)繞組只流兩邊電流的差：100 - 80 = 20 A。"}, {"n": 40, "img": "112E2_40.webp", "ans": "C", "stem": "112E2_s40-41.webp", "sol": "由銘牌的接線圖可知一次側是 Δ 接、二次側是 Y 接。額定容量用一次側算：S = √3 × 線電壓 × 線電流 = √3 × 220 × 131 ≈ 49900 VA，約 50 kVA。"}, {"n": 41, "img": "112E2_41.webp", "ans": "B", "stem": "112E2_s40-41.webp", "sol": "二次側是 Y 接，相電壓 220 V、線電壓 380 V。容量兩側相同，所以二次側線電流 = 50000/(√3 × 380) ≈ 76 A。(若誤用相電壓 220 V 去除就會算成 131 A，那是一次側的值。)"}, {"n": 42, "img": "112E2_42.webp", "ans": "A", "sol": "電池只接在 A 相繞組(U1-U2)上，電壓表跨接在 B 相與 C 相的上端(V1 與 W1)，而 B、C 兩繞組的下端 V2、W2 連在一起，等於 B 與 C 串聯後兩端接電壓表。開關閉合瞬間 A 相磁通變化會同時在 B、C 兩繞組感應出大小相等的電勢，但在這個串聯迴路中兩者方向相反互相抵消，所以電壓表的指針不會偏轉。"}, {"n": 43, "img": "112E2_43.webp", "ans": "D", "sol": "永久電容式兩繞組相同時，轉向由「哪一個繞組串電容(電流超前)」以及「兩繞組的電流方向」決定。乙：電容側繞組的兩端由 S2/S1 改成 S1/S2，等於把該繞組反接，轉向相反。丙：電容側沒變，但主繞組由 M1/M2 改成 M2/M1，一樣是把繞組反接，所以反轉。丁：電容仍然串在圖上同一個(垂直的)繞組，兩個繞組接到電路的端點順序也和甲一樣，只是把 M 和 S 的名稱互換而已，實際電流方向沒變，所以仍是正轉。合起來就是丙反轉、丁正轉。"}, {"n": 44, "img": "112E2_44.webp", "ans": "D", "sol": "雙電壓馬達用 220 V 時，兩個主繞組必須「串聯」(把 2 與 3 接在一起)，而起動(輔助)繞組仍然只能承受 110 V，所以要接在串聯點和其中一條線之間，也就是 5 要併到 2、3 的接點上。(A)(C) 把 5 接到線端，輔助繞組會吃到 220 V 燒掉。(D) 的接法：電流由 L2 進 1 出 2，經接點進 3 出 4 回 L1，輔助繞組則由接點經 5 到 6 回 L1，三個繞組的電流方向都和 110 V 時一樣，所以仍是正轉。(B) 接法其實和 (D) 等效(只是線名對調)，但它說會反轉，是錯的。"}, {"n": 45, "img": "112E2_45.webp", "ans": "A", "sol": "36 槽 4 極，極距 = 36/4 = 9 槽，每槽 = 180 × 4/36 = 20 電機角。由接線面板可看出線尾 10m 落在第 (m + 7) 槽，所以第 1 號線圈由第 1 槽跨到第 8 槽，跨 7 槽，線圈節距是 7/9(短節距)。U 相第一個線圈是 1(到 103)，V 相要落後 120 電機角 = 120/20 = 6 槽，所以 V 相由第 7 號線圈開始，a = 7；一組是 3 個線圈串聯(7、8、9)，組的末端是第 9 號線圈的線尾 109，所以 b = 109。(同理 W 相由 13 開始，c = 13、d = 115，但節距是 7/9 不是 8/9，所以 (C)(D) 都不對。)"}, {"n": 46, "img": "112E2_46.webp", "ans": "C", "sol": "先看燈的接法：L1 接在兩機的同一相之間(同相直接接)，L2、L3 則是交叉接在不同相之間，這是「旋轉燈光法」。它的判斷準則是「同相接的那一盞(L1)熄滅、另外兩盞(L2、L3)一樣亮」時才可以閉合開關。(C) 說 L1、L2 亮而 L3 滅就合閘，弄錯了該熄的那一盞，所以錯誤。(A) 調 DC4 控制 SG2 轉速、調小 R2 使激磁變大讓電壓略高，正確。(B) 原動機的輸入決定有效功率的分配，正確。(D) 激磁的強弱決定無效功率的分配，正確。"}, {"n": 47, "img": "112E2_47.webp", "ans": "C", "sol": "感應電動機的負載特性：轉速從同步轉速附近隨負載慢慢下降，所以一開始最高、往右微降的曲線 1 是轉速。效率在無載時是 0，隨負載上升後趨於平坦，所以從原點附近出發往上爬再轉平的曲線 3 是效率。功率因數在無載時就有一個不為零的低值(因為有激磁電流)，隨負載上升，所以起點不在原點的曲線 2 是功率因數。定子電流無載時也不為零、隨負載愈來愈陡，是曲線 4。因此 (C) 正確。"}, {"n": 48, "img": "112E2_48.webp", "ans": "A", "sol": "(A) 激磁固定(DC 電壓固定)時加大負載轉矩，工作點會沿著 V 形曲線族往電樞電流變大的方向走，原本的 PF = 1 會變成小於 1 而且落後，正確。(B) 降低激磁是往「欠激磁」方向走，原本就落後的功率因數只會更落後，不會變成 1 再變超前(要變超前得「提高」激磁)。(C) 固定激磁、改變負載記錄的是負載特性曲線。(D) 固定負載、改變激磁記錄電樞電流與功率因數，那才是 V 形曲線實驗。(C)(D) 剛好把兩個實驗的名稱對調了。"}, {"n": 49, "img": "112E2_49.webp", "ans": "B", "sol": "(B) 電動機轉速超過同步轉速時進入再生制動，能量回灌使直流鏈電壓升高，這時煞車斬波器動作：串在直流鏈上的開關截止、與電阻 R 串聯的開關導通，多餘的能量由 R 以熱的形式消耗掉，正確。(A) 變頻器是電壓與頻率一起變(定 V/f)，才能維持磁通固定。(C) 前端是二極體整流器，電流不能逆向流動，能量送不回電源，所以才需要煞車電阻。(D) 變頻器只要在控制上改變三相輸出的相序就能反轉，不必外加鼓形開關。"}, {"n": 50, "img": "112E2_50.webp", "ans": "C", "sol": "兩相雙繞組 PM 型步進電動機的正確激磁順序是 A → B → A反 → B反(每一步換到另一相)，這樣磁場才會一步一步轉過去。A 之後直接接 A反 是同一相反向，轉子只會來回擺不會連續旋轉，所以 (A)(D) 的順序不對。圖上的轉子是一對磁極(N、S 各一)，一個電氣循環就等於機械上轉一圈，A、B、A反、B反 四步走完剛好轉一圈(每步 90 度)，所以 (C) 正確。"}]});
EXAM.push({"code": "111E2", "y": 111, "p": "E2", "sub": "電工機械、電工機械實習", "items": [{"n": 1, "img": "111E2_1.webp", "ans": "B"}, {"n": 2, "img": "111E2_2.webp", "ans": "B"}, {"n": 3, "img": "111E2_3.webp", "ans": "D"}, {"n": 4, "img": "111E2_4.webp", "ans": "C"}, {"n": 5, "img": "111E2_5.webp", "ans": "C"}, {"n": 6, "img": "111E2_6.webp", "ans": "D"}, {"n": 7, "img": "111E2_7.webp", "ans": "B"}, {"n": 8, "img": "111E2_8.webp", "ans": "D"}, {"n": 9, "img": "111E2_9.webp", "ans": "B"}, {"n": 10, "img": "111E2_10.webp", "ans": "B"}, {"n": 11, "img": "111E2_11.webp", "ans": "C"}, {"n": 12, "img": "111E2_12.webp", "ans": "C"}, {"n": 13, "img": "111E2_13.webp", "ans": "A"}, {"n": 14, "img": "111E2_14.webp", "ans": "B"}, {"n": 15, "img": "111E2_15.webp", "ans": "B"}, {"n": 16, "img": "111E2_16.webp", "ans": "C"}, {"n": 17, "img": "111E2_17.webp", "ans": "A"}, {"n": 18, "img": "111E2_18.webp", "ans": "D"}, {"n": 19, "img": "111E2_19.webp", "ans": "C"}, {"n": 20, "img": "111E2_20.webp", "ans": "B"}, {"n": 21, "img": "111E2_21.webp", "ans": "D"}, {"n": 22, "img": "111E2_22.webp", "ans": "B"}, {"n": 23, "img": "111E2_23.webp", "ans": "D"}, {"n": 24, "img": "111E2_24.webp", "ans": "B"}, {"n": 25, "img": "111E2_25.webp", "ans": "A"}, {"n": 26, "img": "111E2_26.webp", "ans": "D"}, {"n": 27, "img": "111E2_27.webp", "ans": "C"}, {"n": 28, "img": "111E2_28.webp", "ans": "D"}, {"n": 29, "img": "111E2_29.webp", "ans": "C"}, {"n": 30, "img": "111E2_30.webp", "ans": "B"}, {"n": 31, "img": "111E2_31.webp", "ans": "C"}, {"n": 32, "img": "111E2_32.webp", "ans": "A"}, {"n": 33, "img": "111E2_33.webp", "ans": "A"}, {"n": 34, "img": "111E2_34.webp", "ans": "D"}, {"n": 35, "img": "111E2_35.webp", "ans": "D"}, {"n": 36, "img": "111E2_36.webp", "ans": "D"}, {"n": 37, "img": "111E2_37.webp", "ans": "D"}, {"n": 38, "img": "111E2_38.webp", "ans": "C"}, {"n": 39, "img": "111E2_39.webp", "ans": "D"}, {"n": 40, "img": "111E2_40.webp", "ans": "A"}, {"n": 41, "img": "111E2_41.webp", "ans": "A"}, {"n": 42, "img": "111E2_42.webp", "ans": "C"}, {"n": 43, "img": "111E2_43.webp", "ans": "C"}, {"n": 44, "img": "111E2_44.webp", "ans": "B"}, {"n": 45, "img": "111E2_45.webp", "ans": "B"}, {"n": 46, "img": "111E2_46.webp", "ans": "B"}, {"n": 47, "img": "111E2_47.webp", "ans": "C"}, {"n": 48, "img": "111E2_48.webp", "ans": "B"}, {"n": 49, "img": "111E2_49.webp", "ans": "D", "stem": "111E2_s49-50.webp"}, {"n": 50, "img": "111E2_50.webp", "ans": "D", "stem": "111E2_s49-50.webp"}]});
EXAM.push({"code": "115I2", "y": 115, "p": "I2", "sub": "微處理機、數位邏輯設計、程式設計實習", "items": [{"n": 1, "img": "115I2_1.webp", "ans": "A", "sol": "ALU（算術邏輯單元）負責加減與 AND、OR、NOT 等邏輯運算。程式計數器 PC、對外存取的控制、程式碼的儲存都是別的單元在做。"}, {"n": 2, "img": "115I2_2.webp", "ans": "B", "sol": "三級管線在同一個時脈裡會有三行指令各自停在不同階段：第 n 行在執行、第 n+1 行在解碼、第 n+2 行在提取。數值運算發生在執行階段不是解碼階段。"}, {"n": 3, "img": "115I2_3.webp", "ans": "D", "sol": "共陽七段顯示器要「低電位」才會亮。顯示 3 需要 a、b、c、d、g 亮，e、f 與小數點不亮。PA0～PA7 依序對應 a、b、c、d、e、f、g、dp，所以位元為 dp,g,f,e,d,c,b,a = 1,0,1,1,0,0,0,0 = 0xB0。"}, {"n": 4, "img": "115I2_4.webp", "ans": "D", "sol": "IDE 提供程式碼編輯、編譯與除錯。印刷電路板佈線是 EDA／PCB 設計軟體（如 Altium、KiCad）的工作，不屬於 IDE。"}, {"n": 5, "img": "115I2_5.webp", "ans": "C", "sol": "中斷點是給人用的除錯工具：程式停在那一行，讓你觀察暫存器與變數內容，再決定要單步或繼續。它和硬體中斷無關，也不會跳到中斷服務程式。"}, {"n": 6, "img": "115I2_6.webp", "ans": "D", "stem": "115I2_s6-7.webp", "sol": "SPI 的方向看名稱就知道：MOSI 是 Master Out Slave In，由主機送到從機；MISO 是 Master In Slave Out，由從機送回主機；SS 由主機送出來選擇從機。所以 ① MISO 向左、② MOSI 向右、③ SS 向右。"}, {"n": 7, "img": "115I2_7.webp", "ans": "A", "stem": "115I2_s6-7.webp", "sol": "SPI 是同步傳輸，時脈 SCLK 一律由主機產生，從機只是跟著這個時脈收送資料。SS 是晶片選擇不能取代 SCLK，MOSI 與 MISO 方向固定不能互換，RX 是 UART 的說法。"}, {"n": 8, "img": "115I2_8.webp", "ans": "AD", "note": "官方公告答案更正為 (A) 或 (D) 皆可。", "sol": "每一格是 1/9600 秒，所以速率是 9600 bps（位元/秒）不是位元組/秒，(C) 錯。T0 的低電位是起始位元，接著 T1～T8 共 8 個資料位元；但 T9 仍是低電位，不符合停止位元必須為高電位的規定。因為可以讀成「沒有停止位元」也可以讀成「資料長度 8 位元」，官方公告 (A) 與 (D) 皆可。"}, {"n": 9, "img": "115I2_9.webp", "ans": "A", "sol": "PressureError 直接接到 INT0，同時經反相器去關掉 INT1 的及閘；INT1 再去關掉 INT2 的及閘。這是用硬體做出的優先權：INT0 最高、其次 INT1、最低 INT2。T1 時 PressureError 為高，INT1 被封鎖所以三個中斷並非同時成立，但 INT0 一定會先被服務。"}, {"n": 10, "img": "115I2_10.webp", "ans": "D", "sol": "DMA 的四條控制線中，資料由記憶體搬到周邊時，要「讀記憶體」加「寫周邊」，所以記憶體讀取線與周邊寫入線同時為低準位。這四條線在 DMA 期間是由 DMA 控制器送出，不是 CPU。"}, {"n": 11, "img": "115I2_11.webp", "ans": "C", "sol": "行號 9 的 while(Count==0) 會一直卡住，而 Count 只有在 Int3 的中斷服務程式裡才會加一。所以必須真的觸發 Int3 中斷，程式才會離開迴圈往下執行。"}, {"n": 12, "img": "115I2_12.webp", "ans": "C", "sol": "可以重複讀寫的是 EEPROM、NAND FLASH、EPROM（紫外線擦除後可再寫）、NOR FLASH、SRAM；PROM 只能燒錄一次、Mask ROM 出廠就固定。選項中四個全部可重複讀寫的是 ②NAND FLASH、④EPROM、⑥NOR FLASH、⑦SRAM。"}, {"n": 13, "img": "115I2_13.webp", "ans": "C", "stem": "115I2_s13-14.webp", "sol": "DRAM 最常見的是 RAS-only 刷新：只把 RAS 拉低並送出列位址，CAS 與 WE 都維持高電位，不做實際的資料存取。若 CAS 或 WE 也跟著動作，那就變成讀取或寫入週期了。"}, {"n": 14, "img": "115I2_14.webp", "ans": "C", "stem": "115I2_s13-14.webp", "sol": "41256 是 256K×1 位元，8 顆並起來才有 8 個位元。位址線 A0～A8 與 RAS、CAS、WE 都要並接在一起讓 8 顆同步動作，只有 Din 與 Dout 必須各自獨立，分別對應資料匯流排的一個位元。"}, {"n": 15, "img": "115I2_15.webp", "ans": "A", "sol": "GPU 走大量平行運算路線，內部的 ALU 數量遠多於 CPU，適合同時處理大量像素或矩陣資料；CPU 強在複雜流程控制與單執行緒效能。兩者是分工不是取代。"}, {"n": 16, "img": "115I2_16.webp", "ans": "B", "sol": "MCU 是把 CPU 核心（含 ALU）、記憶體與周邊介面做在同一顆晶片上的單晶片系統。PC 的 USB 由南橋負責；MCU 可以透過 UART、USB 等介面與 PC 交換資料；MCU 不需要 BIOS。"}, {"n": 17, "img": "115I2_17.webp", "ans": "B", "sol": "程式有致能看門狗，但行號 7 的 ResetWatchDogTimer() 被註解掉，主迴圈裡一直沒有去餵狗，計時器逾時後就會把 MCU 重置。看門狗一定要在主迴圈內週期性清除。"}, {"n": 18, "img": "115I2_18.webp", "ans": "A", "sol": "類比信號在時間與振幅上都是連續變化；數位信號只用高、低兩種準位表示。數位的抗雜訊能力比類比好，兩者也都能傳聲音或文字。"}, {"n": 19, "img": "115I2_19.webp", "ans": "D", "sol": "2 對 1 多工器的輸出 Y = S'·I0 + S·I1。代入 S = B'、I0 = 0、I1 = A'，得 Y = B·0 + B'·A' = A'B'，也就是 (A+B) 的補數。"}, {"n": 20, "img": "115I2_20.webp", "ans": "B", "sol": "四個和項分別是 M0、M1、M2、M3，也就是 A = 0 的四個位置都被設為 0。所以 F 在 A = 1 時才為 1，最簡 SOP 就是 F = A，只含 1 個變數。"}, {"n": 21, "img": "115I2_21.webp", "ans": "B", "sol": "把 1 與隨意項一起畫上卡諾圖：C = 1 的八格中，m2、m3、m6、m10、m11、m15 是 1，m7、m14 是隨意項可以當成 1，剛好湊成完整的八格圈。所以 F = C。"}, {"n": 22, "img": "115I2_22.webp", "ans": "C", "sol": "由真值表看，Y1 與 Y2 每一列都相同（不是互補）。輸出為 0 的三列是 011、101、111，共同條件是 C = 1 且 A 與 B 至少一個為 1，所以 Y = ((A+B)·C)' = A'B' + C'。"}, {"n": 23, "img": "115I2_23.webp", "ans": "B", "stem": "115I2_s23-24.webp", "sol": "F1 的最小項是 Σ(1,3,5,6,7)：1、3、5、7 都是 Z = 1，再加上 110，化簡得 F1 = Z + XY。F2 的最小項是 Σ(1,5,7)，化簡得 F2 = Y'Z + XZ = Z(X + Y')。"}, {"n": 24, "img": "115I2_24.webp", "ans": "A", "stem": "115I2_s23-24.webp", "sol": "兩個輸出就需要兩個多工器。以 X、Y 當選擇線、Z 與 Z' 與 0、1 當資料輸入，一個 4 對 1 多工器就能做出一個三變數函數，所以兩個 4 對 1 多工器即可。8 對 1 只有一個輸出；解碼器還要外加 OR 閘才能湊出函數。"}, {"n": 25, "img": "115I2_25.webp", "ans": "A", "sol": "整數 21 = 10101。小數 0.4 不斷乘 2 會得到 0110 0110… 無限循環，所以二進制是 10101.0110（0110 循環）。八進制 21 應為 25 不是 26；十六進制 0.4 會變成 0.666… 也是無限循環，不是有限小數。"}, {"n": 26, "img": "115I2_26.webp", "ans": "A", "sol": "異號相加不可能溢位。-45 + 28 = -17，8 位元 2 的補數表示法下結果正確且沒有溢位。溢位只會發生在同號相加而結果變號的時候。"}, {"n": 27, "img": "115I2_27.webp", "ans": "B", "sol": "要算三個輸入裡有幾個 1，就是一個全加器：和 = A⊕B⊕C 需要兩個 XOR（7486 一顆有四組）；進位 = AB + BC + AC，用 NAND 的通用性可寫成 ((AB)'(BC)'(AC)')'，四個 NAND 剛好一顆 7400。所以 7486 與 7400 各一顆。"}, {"n": 28, "img": "115I2_28.webp", "ans": "D", "sol": "把 ABC 當解碼器輸入、D 另外處理。F 的最小項中，ABC = 000、001、100、101 這四組搭配 D = 0；ABC = 010、011、110、111 這四組搭配 D = 1。所以 F = (Y0+Y1+Y4+Y5)·D' + (Y2+Y3+Y6+Y7)·D。"}, {"n": 29, "img": "115I2_29.webp", "ans": "C", "sol": "先算 Ik = Ak ⊕ Bk，B = 0110。要 Z = Y1 ⊕ Y0 = 1，表示編碼器輸出必須是 (1,0) 或 (0,1)。代入 A = 0011 得 I3I2I1I0 = 0101，最高優先的是 I2，輸出 (1,0)，Z = 1。其餘選項的 I3 為 1 或全部為 0，都得不到 Z = 1。"}, {"n": 30, "img": "115I2_30.webp", "ans": "A", "sol": "JK 正反器在 J = K = 1 時輸出反轉，即 Qn+1 = Qn'。把 J 與 K 接在一起是 T 型正反器；J 接輸入、K 接反相後的輸入才是 D 型正反器，(C)(D) 剛好說反了。"}, {"n": 31, "img": "115I2_31.webp", "ans": "B", "sol": "4 個正反器的漣波計數器最大模數是 2⁴ = 16，所以模-10 做得出來、模-20 做不出來（要 5 個）。環形計數器 n 個正反器的模數是 n（模-4），強森計數器是 2n（模-8），都不是 9。"}, {"n": 32, "img": "115I2_32.webp", "ans": "B", "sol": "D 型正反器把 Q' 接回 D 是除 2，所以 Q0 = 20 kHz / 2 = 10 kHz；JK 的 J = K = 1 也是除 2，由 Q0 觸發，所以 Q1 = 5 kHz。CLR 是高電位清除，Reset = 1 時兩級都被清為 0 不會計數，Reset = 0 才正常工作。兩級合起來是模-4 不是模-2。"}, {"n": 33, "img": "115I2_33.webp", "ans": "C", "sol": "狀態等效要「輸出相同」而且「次態也等效」。S7 與 S0 的輸出都是 0/0，次態分別是 (S0,S3) 與 (S0,S5)，只要 S3 與 S5 等效即可；而 S3 與 S5 的輸出都是 1/0、次態都是 (S4,S3)，完全相同。所以 S7 可被 S0 取代。"}, {"n": 34, "img": "115I2_34.webp", "ans": "D", "sol": "串列加法器每個週期把兩個暫存器的最低位元相加，和回存到 A 的最高位元，進位存進 D 型正反器。T1：1+1+0 → 和 0 進位 1，A = 0101、B = 0011；T2：1+1+1 → 和 1 進位 1，A = 1010、B = 0001；T3：0+1+1 → 和 0 進位 1，A = 0101、B = 0000、Q = 1。"}, {"n": 35, "img": "115I2_35.webp", "ans": "C", "sol": "燒燙傷急救的順序是沖、脫、泡、蓋、送，對應陣列索引 0、2、4、6、8，所以迴圈要從 0 開始每次加 2 跑到小於 9。"}, {"n": 36, "img": "115I2_36.webp", "ans": "C", "sol": "#define PI 3.14 是前置處理器的巨集，編譯前會把程式裡的 PI 全部換成 3.14。行號 6 展開後變成「3.14 = 3.14159…」，等號左邊是常數不是變數，編譯就會錯在行號 6。"}, {"n": 37, "img": "115I2_37.webp", "ans": "D", "stem": "115I2_s37-38.webp", "sol": "X 由 x[] 組成 = 11111110 = 254，Y 由 y[] 組成 = 01111111 = 127。迴圈從 i = 7 遞減，結束時 i 已經變成 -1。所以只有 Y = 127 正確。"}, {"n": 38, "img": "115I2_38.webp", "ans": "C", "stem": "115I2_s37-38.webp", "sol": "x 與 y 只有第 0 個和第 7 個位元不同，count = 2。(float)2/8 = 0.25，用 %.3f 印出會補到小數第三位，輸出 0.250。"}, {"n": 39, "img": "115I2_39.webp", "ans": "A", "sol": "b|c = 0x7F | 0x80 = 0xFF，不等於 0，所以三元運算子取冒號後面那一項：y = b & c = 0x7F & 0x80 = 0。"}, {"n": 40, "img": "115I2_40.webp", "ans": "C", "sol": "逐一比對兩字串：相同的位置是索引 1、3、8、10。但在索引 8 讓 c 變成 3 時遇到 continue，i 沒有加一，下一輪又比到同一個位置而再加一次，所以 c 多算一次變成 5。continue 跳過 i++ 是這題的陷阱。"}, {"n": 41, "img": "115I2_41.webp", "ans": "D", "sol": "i 宣告成 unsigned short，unsigned 永遠大於等於 0，所以 for(i = 9; i >= 0; i--) 的條件永遠成立，i 減到 0 之後會繞回 65535 變成無窮迴圈。把 unsigned 拿掉改用有號整數即可。"}, {"n": 42, "img": "115I2_42.webp", "ans": "B", "sol": "字串為 A1(2ABC*.BAA3CB：A 出現 4 次、B 出現 3 次、數字 1 2 3 共 3 個，其餘的 ( C * . C 共 5 個都落在 default。switch 裡沒有 case 'C'，所以 c_C 一直是 0，輸出 4,3,0,3,5。"}, {"n": 43, "img": "115I2_43.webp", "ans": "C", "sol": "i = 0：sum = 0 + 0，再加 j = 0～5 共 15，sum = 15；i = 2：sum = 15 + 2 = 17，再加 j = 2～5 共 14，sum = 31；i = 4：sum = 31 + 4 = 35，再加 j = 4～5 共 9，sum = 44。"}, {"n": 44, "img": "115I2_44.webp", "ans": "B", "sol": "由輸出可知輸入是 2 3 g n。total = 3 × 30 + 2 × 20 = 130。s_flag 是 g（自取）不乘 1.1，buy 是 n 不加 2，所以 total 維持 130。"}, {"n": 45, "img": "115I2_45.webp", "ans": "B", "sol": "used 在迴圈後變成 {1,3,4,5,0,0}，name 變成 A m f y。字元加一就是 ASCII 碼加一：l→m、e→f、x→y，所以 name[3] = 'y'。name[0] 沒有進迴圈所以還是 'A'。"}, {"n": 46, "img": "115I2_46.webp", "ans": "A", "sol": "p1 指向 i2、p2 指向 i1。先執行 *p1 = i1 + 1，把 i2 改成 2；再執行 *p2 = i2 + 2，此時 i2 已經是 2，所以 i1 = 4。注意第二行用到的是「更新後」的 i2。"}, {"n": 47, "img": "115I2_47.webp", "ans": "A", "sol": "建構子的名稱必須和類別名稱完全相同，而且不能寫回傳型態（連 void 都不行），參數則可有可無。所以只有 Student(int wh){ … } 是合法的建構子。"}, {"n": 48, "img": "115I2_48.webp", "ans": "B", "sol": "pow(10,3) = 1000、sqrt(10000) = 100、exp(3) ≈ 20.09。fmin(1000, 100) = 100，用 %6.2f 印出就是 100.00。其餘組合會得到 20.09 或 1000.00。"}, {"n": 49, "img": "115I2_49.webp", "ans": "A", "sol": "foo(3) 進入後 count 加到 1 再呼叫 foo(2)，count 加到 2 再呼叫 foo(1)，n == 1 就直接返回。回到 main 時 count = 2，printf 裡的 ++count 先加再印，所以輸出 3。"}, {"n": 50, "img": "115I2_50.webp", "ans": "C", "sol": "一隻毛小孩有四種不同型態的資料，要用結構包成一筆，再開成 100 筆的結構陣列。(A)(B) 的 name 只能存一個名字；(D) 的 struct pet[100]{…} 不是合法的宣告語法。"}]});
EXAM.push({"code": "114I2", "y": 114, "p": "I2", "sub": "微處理機、數位邏輯設計、程式設計實習", "items": [{"n": 1, "img": "114I2_1.webp", "ans": "D", "sol": "程式計數器 PC 存放下一條要執行的指令在記憶體中的位址。堆疊暫存器管的是副程式與中斷的返回位址；指令暫存器存目前的指令碼；真正控制時序的是控制單元。"}, {"n": 2, "img": "114I2_2.webp", "ans": "B", "sol": "摩爾定律是半導體製程的經驗法則：同樣面積的晶片上電晶體數量約每 18～24 個月增加一倍，不是面積變兩倍，也和工作電壓無關。"}, {"n": 3, "img": "114I2_3.webp", "ans": "D", "sol": "算術邏輯單元負責加減與邏輯運算。資料匯流排的寬度才決定一次能傳的資料量（位址匯流排決定定址範圍）；控制匯流排傳的是讀寫等控制信號不是資料。"}, {"n": 4, "img": "114I2_4.webp", "ans": "B", "sol": "記憶體用來存放指令與資料，這是馮紐曼架構的基本概念。DDR 在晶片外；暫存器比快取還快；區段解碼用的是位址匯流排的高位元不是資料匯流排。"}, {"n": 5, "img": "114I2_5.webp", "ans": "C", "sol": "記憶體映射式 IO 把 IO 裝置的位址併進主記憶體的位址空間，所以可以用一般的記憶體讀寫指令存取，不需要專用 IO 指令；獨立式 IO 則有自己的位址空間，要用 IN、OUT 這類專用指令。"}, {"n": 6, "img": "114I2_6.webp", "ans": "D", "stem": "114I2_s6-7.webp", "sol": "整數除法會直接捨去，要四捨五入就先加上除數的一半。除以 8 相當於右移 3 位，所以先 ADD AX, #4 再 SHR AX, 3：(3388 + 4) / 8 = 424，正是 423.5 四捨五入的結果。"}, {"n": 7, "img": "114I2_7.webp", "ans": "C", "stem": "114I2_s6-7.webp", "sol": "443 的十六進位是 0x01BB。AND AX, #0FH 只留最低 4 位元，得 0x0B = 11；SHR BX, 4 相當於除以 16，443 / 16 = 27（餘數捨去）。所以 AX = 11、BX = 27。"}, {"n": 8, "img": "114I2_8.webp", "ans": "A", "sol": "IIC 只用一條雙向資料線 SDA（加一條時脈 SCL）；UART 要 TX、RX 兩條資料線；SPI 要 MOSI、MISO 兩條加 SCLK 與 SS。所以 IIC 的資料線最少。同時脈下 SPI 比 IIC 快，UART 則是非同步沒有時脈線。"}, {"n": 9, "img": "114I2_9.webp", "ans": "B", "sol": "本題的 NRZI 採「遇到 0 就轉態、遇到 1 維持原電位」。由波形逐格看：第 2、4、5、8 格有轉態其餘沒有，對應的資料就是 1 0 1 0 0 1 1 0。"}, {"n": 10, "img": "114I2_10.webp", "ans": "D", "sol": "SPI 的從機選擇線是低電位動作，拉低才選中該從機，所以「採高電位作動」是錯的。其餘三項（四條信號線、SCLK 同步、全雙工主從架構）都是 SPI 的特徵。"}, {"n": 11, "img": "114I2_11.webp", "ans": "D", "sol": "輪詢就是程式主動、定期去讀取那支接腳的狀態再做反應。由硬體主動通知 CPU 暫停工作去執行另一段程式碼的才是中斷；外部按鈕屬於外部中斷不是例外中斷。"}, {"n": 12, "img": "114I2_12.webp", "ans": "B", "sol": "開機速度主要看儲存裝置。PCIe 介面的 SSD 頻寬遠高於 SATA-III，又比機械式 HDD 快很多；AGP 是早期顯示卡專用匯流排，ATA 更舊。"}, {"n": 13, "img": "114I2_13.webp", "ans": "C", "sol": "中斷的標準流程：②周邊發出中斷請求並被認可 → ③暫停目前程式並把暫存器等資料備份（推入堆疊）→ ①執行中斷服務程式 → ④還原資料並返回原來的位置繼續執行。"}, {"n": 14, "img": "114I2_14.webp", "ans": "D", "sol": "SRAM 是靜態記憶體，讀寫速度比 NOR Flash 快很多。SRAM 屬於揮發性，所以 (A) 把它歸到非揮發性是錯的；NOR Flash 是非揮發性；EPROM 要用紫外線擦除不是電壓。"}, {"n": 15, "img": "114I2_15.webp", "ans": "C", "sol": "雙核心同時工作會有更多電晶體在切換，發熱量與溫度上升速度都比單核心快。耗電不會剛好兩倍，執行時間也不可能小於一半（受限於無法平行的部分），而且要真的用到兩核心必須把程式寫成多執行緒。"}, {"n": 16, "img": "114I2_16.webp", "ans": "D", "sol": "GPU 是多核心架構，用於遊戲圖像與 AI 類神經網路運算。大部分單晶片微控制器用的是單核心的精簡架構，不會採用 GPU 架構。"}, {"n": 17, "img": "114I2_17.webp", "ans": "C", "sol": "訓練 AI 模型吃的是運算能力，所以要高速的 CPU 與 GPU（尤其 GPU 的平行運算）。螢幕大小、藍芽鍵鼠、USB 速度都不會加速訓練。"}, {"n": 18, "img": "114I2_18.webp", "ans": "B", "sol": "V1 是比較低的那條準位線，輸入電壓降到它以下時反相器才判定為邏輯 0，所以 V1 是輸入低準位電壓 VIL。(C)(D) 的符號與說明互相矛盾：VOH 是輸出高準位、VOL 是輸出低準位。"}, {"n": 19, "img": "114I2_19.webp", "ans": "B", "sol": "8 位元有號數的範圍是 -128～127。78 + 60 = 138 超過 127，同號相加卻變號，就是溢位。其餘：-45-60 = -105、104₈-74₈ = 8、145₈+24₈ = 121 都在範圍內。"}, {"n": 20, "img": "114I2_20.webp", "ans": "B", "sol": "BCD 是每一個十進位數字各自用 4 個位元表示：6 → 0110、7 → 0111、小數 5 → 0101，所以 67.5 的 BCD 是 01100111.0101。"}, {"n": 21, "img": "114I2_21.webp", "ans": "A", "sol": "A、B 經 NAND 得 (AB)'，C、D 經 OR 得 (C+D)，E、F 經 AND 得 EF，三者再進 NOR。X = ((AB)' + (C+D) + EF)' = AB · (C+D)' · (EF)' = AB · C'D' · (E'+F')。"}, {"n": 22, "img": "114I2_22.webp", "ans": "B", "stem": "114I2_s22-23.webp", "sol": "加密是逐位元 XOR：C2 = 1⊕1 = 0、C1 = 0⊕0 = 0、C0 = 0⊕1 = 1，所以密文 C2C1C0 = 001。"}, {"n": 23, "img": "114I2_23.webp", "ans": "C", "stem": "114I2_s22-23.webp", "sol": "XOR 的性質是 (A⊕B)⊕B = A，所以解密電路和加密電路一樣，把密文 Ci 與同一把密鑰 Ki 再做一次 XOR 就會還原成 Ai。用 AND、OR 或 XNOR 都無法還原。"}, {"n": 24, "img": "114I2_24.webp", "ans": "A", "sol": "由真值表，Y = 1 只出現在 000、010、110，共同條件是 C = 0；在 C = 0 的四列中只有 A=1,B=0 那一列為 0。所以 Y = C'·(A' + B)：A 經反相器與 B 做 OR，再與 C 的反相做 AND。"}, {"n": 25, "img": "114I2_25.webp", "ans": "B", "sol": "A 每格變一次、B 每兩格、C 每四格，所以八個時間格剛好跑完 CBA 的八種組合。逐格讀出 Y 得到 000→0、001→0、010→1、011→1、100→0、101→1、110→1、111→0，整理起來就是 Y = B ⊕ (C·A)。"}, {"n": 26, "img": "114I2_26.webp", "ans": "B", "sol": "解碼器的每一個輸出對應一個輸入組合：XY=00 時 Q3=1、01 時 Q2=1、10 時 Q1=1、11 時 Q0=1。所以 Q3 = X'Y'、Q2 = X'Y、Q1 = XY'、Q0 = XY。"}, {"n": 27, "img": "114I2_27.webp", "ans": "D", "sol": "葛雷碼每個位元沒有固定的權重，不是加權碼，這是它和 BCD、8421 碼最大的不同。二進制轉葛雷碼是從最高位元開始（MSB 照抄，其餘與左邊一位 XOR），不是從最低位元。"}, {"n": 28, "img": "114I2_28.webp", "ans": "A", "sol": "全減器的差 D 與全加器的和一樣都是三個輸入的 XOR：D = X ⊕ Y ⊕ Bi，展開成最小項就是 XYBi + X'Y'Bi + XY'Bi' + X'YBi'，也就是三個輸入中有奇數個 1 時 D 為 1。"}, {"n": 29, "img": "114I2_29.webp", "ans": "A", "sol": "選擇線 S1 = y、S0 = z，四個輸入依序是 I0 = x、I1 = 1、I2 = x'、I3 = 0。f = y'z'x + y'z + yz'x'，對應的最小項（x 為 MSB）是 m4、m1 與 m5、m2，也就是 Σ(1,2,4,5)。"}, {"n": 30, "img": "114I2_30.webp", "ans": "A", "sol": "左邊是 NOR 閂鎖器（高電位動作）：a=1 使 Qx=0、b=1 使 Qx=1，所以 (C)(D) 都說反了。右邊是 NAND 閂鎖器（低電位動作）：c=0、d=1 時 Qy=1，因此 Qy' = 0。"}, {"n": 31, "img": "114I2_31.webp", "ans": "A", "sol": "這是強森（扭環）計數器：D0 = Q2'、D1 = Q0、D2 = Q1。由 000 開始依序是 001 → 011 → 111 → 110 → 100 → 000，模數為 6。第 3 個時脈後正是 111。"}, {"n": 32, "img": "114I2_32.webp", "ans": "A", "sol": "第一級的 CK 有圓圈是負緣觸發，第二級是正緣觸發。所以 X 要先在 CLK 的下降緣被取樣，再在下一個上升緣送到 Y。判斷時只要檢查 Y 的每一次轉態是不是都落在 CLK 的上升緣，而且數值等於前一個下降緣時的 X。"}, {"n": 33, "img": "114I2_33.webp", "ans": "A", "sol": "2 的補數減法把減數取 2 的補數後相加，最高位的進位直接丟掉就好，不需要端迴進位；1 的補數減法才要把溢出的進位加回最低位。1 的補數只要逐位元反相，加 1 是 2 的補數的做法。"}, {"n": 34, "img": "114I2_34.webp", "ans": "A", "sol": "F 要依 RL 選擇資料來源：RL=0 右移時取 DIR（b），RL=1 左移時取左邊來的 Q（a），也就是 z = a·c + b·c'（c 接 RL）。選項 (A) 用兩個 NAND 做出 ac 與 bc' 再用 NAND 合併，正好等於這個式子；(D) 的多工器選擇腳接法剛好相反。"}, {"n": 35, "img": "114I2_35.webp", "ans": "B", "sol": "原始陣列是 脫蓋送沖泡，目標是 沖脫泡蓋送。swap(0,3) 後變成 沖蓋送脫泡，swap(3,1) 後變成 沖脫送蓋泡，swap(2,4) 後變成 沖脫泡蓋送，剛好是正確的急救順序。"}, {"n": 36, "img": "114I2_36.webp", "ans": "D", "sol": "行號 6 又宣告了一個區域陣列 ptr[20]，它會遮蔽掉行號 2 的全域指標 ptr。所以行號 7 的 *ptr = *str 是把區域 ptr 的第一個字元改成 'T'，Main 變成 Tain。"}, {"n": 37, "img": "114I2_37.webp", "ans": "D", "sol": "32 位元有號整數用 1 個位元表示正負，範圍是 -2³¹ ～ 2³¹-1，最大值 2³¹-1；32 位元無號整數全部位元都表示數值，最大值 2³²-1。"}, {"n": 38, "img": "114I2_38.webp", "ans": "C", "sol": "x + y = 35 已經不小於 32，應該印「Ya!快完成了!」。原程式 flag = (35 < 32) = 0，!flag 成立反而印出「Go!」。把條件改成 x+y >= 32，flag 變 1，!flag 不成立就會走 else 印出正確訊息。"}, {"n": 39, "img": "114I2_39.webp", "ans": "C", "sol": "short 的範圍是 -32768 ～ 32767，足以涵蓋 -20000 ～ 20000。char 只有 -128～127 太小；C 語言沒有 unsigned float；unsigned short int* 是指標不是整數型態。"}, {"n": 40, "img": "114I2_40.webp", "ans": "C", "sol": "C 語言裡 == 的優先順序高於 ^，所以 a^b==x 其實是 a^(b==x)，不是 (a^b)==x。等價的寫法要保留這個結合方式，也就是 x*x%2 && a^(b==x)。"}, {"n": 41, "img": "114I2_41.webp", "ans": "D", "sol": "Z = (X || !Y) && (Y || X)，也就是 (A + B')(A + B)。展開後 = A + B'B = A，四組輸入算出來的 F 依序是 0、0、1、1，只有 (A+B')(A+B) 這個式子相符。"}, {"n": 42, "img": "114I2_42.webp", "ans": "B", "sol": "query 是 is，sizeof 把結束字元也算進去所以 len = 3。字串中 is 出現在索引 2、5、24 共三次，match_count = 3；ans 每比對完一輪就被歸零，最後是 0。所以輸出 3, 0, 3。"}, {"n": 43, "img": "114I2_43.webp", "ans": "C", "sol": "由 (short)X = 8 知 8 ≤ X < 9；(unsigned)(X*4) = 42₈ = 34 推得 8.5 ≤ X < 8.75；(int)(X*16) = 8a₁₆ = 138 推得 8.625 ≤ X < 8.6875。三個條件取交集，X = 8.625，印出 8.6250。"}, {"n": 44, "img": "114I2_44.webp", "ans": "B", "sol": "n[1] = 100 把第二個元素改成 100；*n 等同於 n[0]，所以 n[0] 被設為 1。陣列變成 1,100,3,4,5，用 %d 一個一個印出來沒有分隔符號，就連成 1100345。"}, {"n": 45, "img": "114I2_45.webp", "ans": "D", "sol": "a++ 是後置遞增，先用舊值 1 做除法：1/3 在整數除法下等於 0。++d 是前置遞增，d 先變 8 再使用，c*d = 5×8 = 40。所以 x = 0 + 40 = 40。"}, {"n": 46, "img": "114I2_46.webp", "ans": "A", "sol": "malloc 只配置了結構本身的空間，裡面的 name 仍然是一個沒有指向任何地方的野指標。strcpy 把字串寫進這個無效位址就會出錯，必須先替 name 配置空間或改用字元陣列。"}, {"n": 47, "img": "114I2_47.webp", "ans": "A", "sol": "x 從 6.28 遞減的過程中會經過 sin(x) 為負的區間（例如 x 約 3.2～6.2），對負數開根號在實數範圍沒有定義，會得到 NaN 或定義域錯誤。"}, {"n": 48, "img": "114I2_48.webp", "ans": "B", "sol": "依優先順序先算 ~a：~128 = 0xFFFFFF7F，左移 2 位得 0xFFFFFDFC；再 XOR 255 得 0xFFFFFD03；再 OR 128 得 0xFFFFFD83；最後 & 0xff 只留最低位元組 0x83，以十六進位印出就是 83。"}, {"n": 49, "img": "114I2_49.webp", "ans": "B", "stem": "114I2_s49-50.webp", "sol": "在 64 位元環境下 sizeof(int) = 4、sizeof(char) = 1、sizeof(int*) = 8，所以 m = 4、n = 1、p = 8。四個選項中只有 m ≥ n（4 ≥ 1）成立。"}, {"n": 50, "img": "114I2_50.webp", "ans": "A", "stem": "114I2_s49-50.webp", "sol": "a 是整個 classA 陣列的大小 = 50 × sizeof(CLASS)，b 和 g 都只是一個 CLASS 的大小，d 是一個 int 的 4 位元組。所以 a 最大。"}]});
EXAM.push({"code": "113I2", "y": 113, "p": "I2", "sub": "微處理機、數位邏輯設計、程式設計實習", "items": [{"n": 1, "img": "113I2_1.webp", "ans": "A", "sol": "指令週期分成提取、解碼、執行三階段。提取週期做的是把 PC 指到的那一道指令讀進指令暫存器，也就是「指令提取」。運算元提取、有效位址計算、存放結果都要等到解碼或執行階段。官方確認說明也特別點出：整個指令週期只有運算元提取，沒有「運算子提取」這件事。"}, {"n": 2, "img": "113I2_2.webp", "ans": "D", "sol": "(A) VGA 送的是類比訊號，只有 DVI(數位型)、HDMI 是數位。(B) DDR SDRAM 只影響記憶體頻寬，不會改變 CPU 時脈。(C) 微處理機系統一定包含 CPU。(D) 單晶片微處理機(微控制器 MCU)把微處理器、記憶體、輸出入介面做在同一顆晶片上，正確。"}, {"n": 3, "img": "113I2_3.webp", "ans": "B", "sol": "程式計數器 PC 存的是「下一道要執行的指令位址」，負責控制執行次序；跳到副程式就是把起始位址寫進 PC。要寫入資料的記憶體位址是放在 MAR，不是 PC，所以 (B) 錯誤。"}, {"n": 4, "img": "113I2_4.webp", "ans": "C", "sol": "MAR(記憶體位址暫存器)裡放的是要存取的「主記憶體」位址，不是 CPU 內部暫存器的位址，所以 (C) 錯誤。其餘三項都對：內部暫存器就是 CPU 內的高速記憶體、IR 放待解碼執行的指令、MDR 是讀寫記憶體資料的緩衝。"}, {"n": 5, "img": "113I2_5.webp", "ans": "C", "sol": "運算元直接就在 CPU 內部暫存器裡，不必再跑一次記憶體存取，速度最快。直接定址要讀一次記憶體、間接定址要讀兩次、堆疊定址還要動堆疊指標，都比暫存器定址慢。"}, {"n": 6, "img": "113I2_6.webp", "ans": "B", "sol": "堆疊是後進先出。PUSH A、PUSH C、PUSH B 之後由頂端往下是 B、C、A。接著 POP A 取到的是 B 的值、POP C 取到的是 C 的值(不變)、POP B 取到的是 A 的值。結果 A 與 B 的內容對調，C 維持不變。"}, {"n": 7, "img": "113I2_7.webp", "ans": "D", "sol": "MIPS 是 Million Instructions Per Second，每秒百萬指令數，用來衡量 CPU 的執行速度，不是網路傳輸速率(網路用 bps)，所以 (D) 錯誤。"}, {"n": 8, "img": "113I2_8.webp", "ans": "B", "sol": "32 位元中央處理單元指的是一次能處理的資料寬度(資料匯流排／字組長度)是 32 位元，和位址匯流排幾條沒有直接關係，所以 (B) 錯誤。(A) 2 的 8 次方 = 256 個位址，正確；(C)(D) 也都正確。"}, {"n": 9, "img": "113I2_9.webp", "ans": "B", "sol": "中斷的標準流程是：周邊發出中斷請求(IRQ) → CPU 回應中斷認可(INTA) → 跳到中斷服務程式做中斷處理 → 執行 RETI 中斷返回原程式。所以是 (B)。"}, {"n": 10, "img": "113I2_10.webp", "ans": "D", "sol": "(A) RS-422 是全雙工、RS-485 可半雙工或全雙工，敘述寫反。(B) USB、SPI、I2C 都是主從(Master-Slave)架構。(C) SPI 是四線(SCLK、MOSI、MISO、SS)、I2C 是兩線(SCL、SDA)，敘述寫反。(D) IEEE-488(GPIB)與 PCI 都是並列傳輸，正確。"}, {"n": 11, "img": "113I2_11.webp", "ans": "C", "sol": "重置(RESET)是最高優先權，一來就無條件重新開機；其次是不可遮罩中斷(NMI)，不能被程式關掉；最低的是可遮罩中斷(INTR)，可以用指令遮蔽。所以 重置 > 不可遮罩 > 可遮罩。"}, {"n": 12, "img": "113I2_12.webp", "ans": "A", "sol": "(A) L1 快取是 SRAM 做的，存取速度遠快於快閃記憶體，正確。(B) 容量大小應該是 磁碟機 > 主記憶體 > 快取，順序寫反。(C) 快閃記憶體斷電資料還在，是非揮發式。(D) EPROM 要用紫外線照射抹除，用電氣抹除的是 EEPROM 與 Flash，隨身碟用的是 Flash。"}, {"n": 13, "img": "113I2_13.webp", "ans": "A", "sol": "DMA 的用意就是讓周邊和記憶體直接互傳，不必每一筆都經過 CPU，所以 (A) 正確。(B) 外部儲存裝置之間也可以用 DMA。(C) 除了來源與目的起始位址，還必須給資料長度(計數值)。(D) 8255 是可程式週邊介面 PPI，常見的 DMA 控制器是 8237。"}, {"n": 14, "img": "113I2_14.webp", "ans": "B", "sol": "(B) 固態硬碟用快閃記憶體晶片儲存，完全沒有磁片與機械讀寫頭，正確。(A) 5400 rpm 是每分鐘 5400 轉，等於每秒 90 轉。(C) NAND Flash 單位面積容量大、成本低，才適合做大容量儲存，NOR 適合放程式碼。(D) AGP 是早期顯示卡介面，不是硬碟介面。"}, {"n": 15, "img": "113I2_15.webp", "ans": "D", "sol": "8 M bytes = 8 × 1024 × 1024 × 8 位元 = 64 M 位元。一顆是 1 M × 1 bit = 1 M 位元，所以需要 64 M / 1 M = 64 顆。另一個算法：資料寬度要 8 位元所以橫向排 8 顆，容量要 8 M 所以縱向疊 8 組，8 × 8 = 64 顆。"}, {"n": 16, "img": "113I2_16.webp", "ans": "C", "sol": "費林(Flynn)分類法用 Single/Multiple 兩個字，分成 SISD、SIMD、MISD、MIMD 四類。選項裡的 Poly 都不是 Flynn 用的字，只有 (C) Single Instruction Single Data(SISD)是正確的分類名稱。"}, {"n": 17, "img": "113I2_17.webp", "ans": "B", "sol": "平行處理是指同時對不同指令一起解碼、一起執行，像多核心處理器、多處理機、管線處理都算。資料並列傳輸講的是「一次送好幾條線的資料」，屬於傳輸方式而不是處理架構，所以 (B) 不屬於平行處理。"}, {"n": 18, "img": "113I2_18.webp", "ans": "B", "sol": "扇出數是一個輸出端最多能驅動幾個同類型的輸入端，判斷依據是輸出端能吸收／供應的電流 IOH、IOL，要能大於下一級所有輸入端所需的 IIH、IIL 總和，所以 (B) 正確。不是看電壓，也不是算 LED 數量。"}, {"n": 19, "img": "113I2_19.webp", "ans": "D", "sol": "2 對 1 多工器 Y = A·S反 + B·S。全用二輸入 NAND 的話：第 1 顆 NAND(S, S) 產生 S反，第 2 顆 NAND(A, S反)，第 3 顆 NAND(B, S)，第 4 顆 NAND 把前兩顆的輸出再反及一次就得到 Y，共 4 顆。"}, {"n": 20, "img": "113I2_20.webp", "ans": "B", "sol": "格雷碼最大的特色就是相鄰兩個碼只有一個位元不同，用在開關上就是相鄰兩刻度只要撥一個開關，可以避免切換瞬間出現錯誤的中間值，所以 (B) 正確。(A) 格雷碼是非權重碼。(C) 74138 是 3 對 8 解碼器，不是格雷碼轉換器。(D) 011 與 100 在格雷碼序列裡根本不相鄰。"}, {"n": 21, "img": "113I2_21.webp", "ans": "D", "sol": "上半部那顆 OR 閘的兩個輸入是 B 和 B反，輸出恆為 1；下半部那顆 AND 閘的兩個輸入是 A 和 A反，輸出恆為 0。最後一顆 OR 把 1 和 0 相或，Q = 1 + 0 = 1，不管 A、B 怎麼變都一樣。"}, {"n": 22, "img": "113I2_22.webp", "ans": "D", "sol": "圖上的 1 落在 (AB,CD) = (00,00)、(00,10)、(10,00)、(10,10)，也就是最小項 0、2、8、10。(A) Σ(0,2,8,10) 正確。(B) 其餘 12 格都是 0，寫成最大項 Π 也正確。(C) 這四格的共同點是 B = 0 且 D = 0，化簡後就是 B反D反，正確。(D) BD 代表 B = 1 且 D = 1，也就是第 5、7、13、15 格，那四格全是 0，和圖完全對不上，所以無法表示。"}, {"n": 23, "img": "113I2_23.webp", "ans": "D", "sol": "兩顆 NAND 的輸出再送進 NOR：X = ((AB)反 + (CD)反)反 = AB · CD。只有 A = B = C = D = 1 時 X 才會是 1。四個輸入共 16 種組合，扣掉這 1 種，其餘 15 種都讓 X = 0。"}, {"n": 24, "img": "113I2_24.webp", "ans": "D", "sol": "整數部分 685 除 2 取餘數：685 = 1010101101(2)。小數部分 0.59375 連續乘 2 取整數位：0.59375×2 = 1.1875 取 1；0.1875×2 = 0.375 取 0；0.375×2 = 0.75 取 0；0.75×2 = 1.5 取 1；0.5×2 = 1.0 取 1，得 .10011。合起來 1010101101.10011(2)。"}, {"n": 25, "img": "113I2_25.webp", "ans": "A", "sol": "11101011 - 10001001，直接做二進位減法或先把減數取 2 補數再相加都可以。10001001 的 2 補數是 01110111，11101011 + 01110111 = 101100010，捨去最高位的進位得 01100010(2)，也就是 235 - 137 = 98。"}, {"n": 26, "img": "113I2_26.webp", "ans": "B", "sol": "表中 X 都出現在編號較小的輸入上，代表只要編號大的那一條是 1 就不管小的，所以這是一個「Y7 優先權最高」的優先權編碼器，(B) 正確。(A) 最高優先權是 Y7 不是 Y0。(C) Y3、Y5、Y6 同時為 1 時由 Y6 勝出，CBA = 110。(D) 優先權編碼器就是為了解決多個輸入同時為 1 的問題，輸出是確定的。"}, {"n": 27, "img": "113I2_27.webp", "ans": "A", "sol": "這是加法／減法器，但每顆全加器的和還要再和最後的進位 C4 做 AND 才輸出。(A) M = 0 時 B 原樣進去、C0 = 0，1100 + 1100 = 1 1000，C4 = 1、和 = 1000，再 AND 1 仍是 1000，正確。(B) 0001 + 0001 = 0010 但 C4 = 0，四個 AND 全被關掉，輸出是 0000 不是 0010。(C)(D) M = 1 時雖然做的是 A - B，輸出仍要乘上 C4，不會恆等於 A - B 或 B。"}, {"n": 28, "img": "113I2_28.webp", "ans": "A", "sol": "2 對 1 多工器的選擇線是 B：B = 0 選 0 號輸入，而 0 號輸入是從輸出 X 繞回來的，也就是 Xn；B = 1 選 1 號輸入 A。寫成布林式就是 Xn+1 = B反·Xn + B·A，和 (A) 完全一樣。"}, {"n": 29, "img": "113I2_29.webp", "ans": "B", "sol": "奇數個反閘首尾相接就會自激振盪，週期是訊號繞兩圈的時間：f = 1/(2 n t) = 1/(2 × 3 × 100 ns) ≈ 1.67 MHz。後面兩級 JK 正反器的 J、K 都接 1 屬除頻器，每一級除 2，兩級共除 4。Y 的頻率 = 1.67 MHz / 4 ≈ 416 kHz。"}, {"n": 30, "img": "113I2_30.webp", "ans": "C", "sol": "要讓輸出由 0 變 1。(A) RS 正反器 S = R = 1 是禁止狀態。(B) S = R = 0 是保持，仍是 0。(C) JK 正反器 J = 1、K = 0 是設定(SET)，輸出變 1，正確。(D) J = K = 0 是保持，仍是 0。"}, {"n": 31, "img": "113I2_31.webp", "ans": "D", "sol": "S0 = S1 = 1 時這組多工器把 Z 的輸出繞回最前面，整個暫存器做的是「循環右移」：W 接收 Z、X 接收 W、Y 接收 X、Z 接收 Y。從 1011 開始：第 1 個時脈變 1101、第 2 個變 1110、第 3 個變 0111。選項 (B)(C)(D) 剛好就是一、二、三個時脈後的值，答案是 0111。"}, {"n": 32, "img": "113I2_32.webp", "ans": "A", "sol": "兩個輸入綁在一起的 NAND 就等於一顆反相器，Y = 輸入的反。一開始電容放完電，輸入是 0，所以 Y = 1。壓下 S 之後 VCC 經 10 kΩ 對 0.01 μF 充電，輸入電壓慢慢往上爬，爬過史密特的上臨界電壓那一瞬間輸出翻成 0，之後一直維持 0。所以波形是先 1 後跳到 0 並維持，選 (A)。"}, {"n": 33, "img": "113I2_33.webp", "ans": "A", "stem": "113I2_s33-34.webp", "sol": "三顆 JK 都接成 T 型，S 是上數／下數的方向控制：S = 1 時下一級在「前面各位元都是 1」才翻轉，就是上數計數器。現態 011 是 3，上數一次變 4，也就是 100。"}, {"n": 34, "img": "113I2_34.webp", "ans": "D", "stem": "113I2_s33-34.webp", "sol": "S = 0 時各級改成「前面各位元都是 0」才翻轉，就是下數計數器。現態 110 是 6，往下數一次就是 5，二進位 101，所以只要 1 次時脈觸發。"}, {"n": 35, "img": "113I2_35.webp", "ans": "C", "sol": "燒燙傷急救口訣是「沖、脫、泡、蓋、送」。陣列的索引依序是 0 拖、1 脫、2 送、3 沖、4 蓋、5 泡、6 送，所以要照 3(沖)、1(脫)、5(泡)、4(蓋)、6(送) 取用。(D) 的 3,1,4,5,2 會變成「沖脫蓋泡送」，把泡和蓋顛倒了。"}, {"n": 36, "img": "113I2_36.webp", "ans": "C", "sol": "a、b、c 是宣告在 main() 裡面的區域變數，函式 f() 看不到它們，編譯時會出現 undeclared 的錯誤。把 a、b、c 移到行號 2 也就是所有函式之外宣告成全域變數，f() 就看得到了。和 float 或 double、初始值是不是整數都沒有關係。"}, {"n": 37, "img": "113I2_37.webp", "ans": "C", "sol": "問題出在行號 8 的 score[i]/10：score[i] 和 10 都是 int，做的是整數除法，每個元素都小於 10 所以每次都得到 0，累加起來 sum 永遠是 0。正確做法是先把整數全部加起來，最後再除：行號 8 改成 sum = sum + score[i];、行號 10 改成 average = (int)(sum/10);。只改資料型態或輸出格式都救不了整數除法。"}, {"n": 38, "img": "113I2_38.webp", "ans": "B", "sol": "陣列初值只給 8 個，後兩個自動補 0，所以 Data = {1,2,3,4,11,12,13,15,0,0}；pData 指到 Data[2]。(A) pData[1] 就是 Data[3] = 4，不等於 1，為假。(B) *(pData+3) 就是 Data[5] = 12，和 Data[5] 當然相等，為真，正確。(C) Data[9] 是補上的 0，判斷式為真，敘述說為假，錯。(D) pData[5] = Data[7] = 15、*(pData+2) = Data[4] = 11，相減得 4 = Data[3]，判斷式為真，敘述說為假，錯。"}, {"n": 39, "img": "113I2_39.webp", "ans": "A", "sol": "i = 3，i & 0x0e = 3 & 1110(2) = 2，2 % 5 = 2，所以跳進 case 2。case 2 印出字元 '0' + 3×3 = '0' + 9 = '9'，而且沒有 break，會一路往下掉：case 3 印出 'a' + 9 = 'j'，default 再印出 'z'。輸出是 9jz。"}, {"n": 40, "img": "113I2_40.webp", "ans": "A", "sol": "列舉值依序是 Run = 1、Stop = 2、Pause = 3、Exit = 4，初值 StateMachine = Pause。Command = 1 時：行 5 先把狀態改成 Stop，行 6 不成立，行 8 因為 StateMachine == Stop 成立，最後變成 Exit，(A) 正確。Command = 2 會變 Run 不是 Pause；Command = 3 會變 Exit 不是 Stop；Command = 4 三個 if 都不成立，維持 Pause 不是 Run。"}, {"n": 41, "img": "113I2_41.webp", "ans": "D", "sol": "(A) 減號比 >> 優先，算成 (A-5)>>2 再 OR 4，只改到位元 2，最低位還是跟著 A 變，A = 9 時結果 5 是奇數。(B) 和 0x1B 做 AND，0x1B 最低位是 1，所以結果的奇偶跟著前面的算式跑，A 為偶數時 (A+8)×A 是偶數、再減 13 變奇數。(C) 整數除法後加 6，A = 18 時得 7 是奇數。(D) (A+124) & 2 只會是 0 或 2，而 2 % 5 = 2(% 比 + 優先)，所以結果只會是 2 或 4，恆為偶數。"}, {"n": 42, "img": "113I2_42.webp", "ans": "A", "sol": "一次函數在 [m, n] 內有根，等價於兩端點的函數值異號(或其中一端剛好為 0)，也就是 f(m) × f(n) <= 0。相加、相減都看不出正負號是否相反；而且 % 只能用在整數，float 不能取餘數，(D) 連編譯都不會過。"}, {"n": 43, "img": "113I2_43.webp", "ans": "A", "stem": "113I2_s43-44.webp", "sol": "student 是結構陣列不是指標，要用小數點存取成員。題目說第 i 個學生放在 student[i-1]，所以學號 28 的學生是 student[27]，成員寫法是 student[27].score。(B) 把型態名稱 SCORE 當陣列用；(C)(D) 把成員和索引的位置寫反，而且 student 不是指標不能用箭號。"}, {"n": 44, "img": "113I2_44.webp", "ans": "B", "stem": "113I2_s43-44.webp", "sol": "泡沫排序不管資料長什麼樣子，比較次數都是固定的：第一輪比 N-1 次、第二輪 N-2 次，一直到最後一輪比 1 次，總共 N(N-1)/2 次。這裡 N = 50，50 × 49 / 2 = 1225 次。"}, {"n": 45, "img": "113I2_45.webp", "ans": "D", "stem": "113I2_s45-46.webp", "sol": "T1、T2 是物件不是指標，要用小數點不能用箭號，所以 (A)(B) 的 -> 寫法錯。(C) FlowRate 宣告在 private 區段，main 裡面碰不到。(D) SetOffset() 是 public 成員函式，用 T2.SetOffset(-3.2) 呼叫是合法的。"}, {"n": 46, "img": "113I2_46.webp", "ans": "A", "stem": "113I2_s45-46.webp", "sol": "Offset 宣告成 static，整個類別只有一份、所有物件共用，所以用 T2 去改 Offset，T1 看到的 Offset 也跟著變成 0.5，(A) 正確。(B) T1 是用 T1(1.0, 2.3) 建立的，FlowRate 是 1.0 不是 0.0。(C) ToatlFlow() 在 protected 區段，main 不能直接呼叫。(D) (Item)1 轉出來是 _Time，三元運算子會回傳 Time 而不是 FlowRate。"}, {"n": 47, "img": "113I2_47.webp", "ans": "C", "stem": "113I2_s47-48.webp", "sol": "'a' 的 ASCII 碼是 97，所以陣列實際是 {1,3,5,7,9,2,4,6,8,0,97}。注意內層迴圈 i 是從 0 跑到 N-1，連 i < min 的位置也會比，等於每次都把目前 numbers[min] 和整列比一輪並交換，結果不是由小到大而是把最大值換到最前面、整列變成由大到小。實際跑完輸出 97 9 8 7 6 5 4 3 2 1 0。官方確認說明也列出同樣的結果。"}, {"n": 48, "img": "113I2_48.webp", "ans": "A", "stem": "113I2_s47-48.webp", "sol": "swap() 的參數宣告是 int a, int b，收的是整數值；但行號 16 傳進去的 numbers+i、numbers+min 是指標 int *，型態對不上，編譯器才會說 expected int but argument is of type int *。要改成 void swap(int *a, int *b) 並在函式內用 *a、*b 交換才行(順便說，原來那種傳值寫法本來就換不動呼叫端的值)。"}, {"n": 49, "img": "113I2_49.webp", "ans": "C", "stem": "113I2_s49-50.webp", "sol": "流程圖那一段的意思是：只要「字數大於等於陣列長度」就一直要求重新輸入，直到小於陣列長度才往下走，所以要用迴圈不是 if，而且判斷條件是大於等於。(C) while(StringLength >= ArrayLength) 正確。原本的 if(StringLength <= ArrayLength) 只會問一次，條件也不對。"}, {"n": 50, "img": "113I2_50.webp", "ans": "C", "stem": "113I2_s49-50.webp", "sol": "原本寫 StringIn[StringLength--]，輸入 6 個字會依序填進索引 6、5、4、3、2、1，索引 0 一直是初值 0，printf 時第一個字元就是字串結束符號，什麼都印不出來。改成 StringIn[--StringLength] 會先減再用，依序填進索引 5、4、3、2、1、0，最先輸入的字排到最後面，印出來正好是倒序字串。(A)(B) 只動迴圈條件救不了索引 0；(D) 的 ++ 會讓迴圈停不下來並且寫爆陣列。"}]});
EXAM.push({"code": "112I2", "y": 112, "p": "I2", "sub": "微處理機、數位邏輯設計、程式設計實習", "items": [{"n": 1, "img": "112I2_1.webp", "ans": "A", "sol": "管線是把一道指令拆成提取、解碼、執行等階段，讓不同的指令同時佔用不同階段，像生產線一樣重疊進行，所以 (A) 正確。(B) 那是沒有管線的做法。(C) 同時對多個指令做「相同」步驟是 SIMD 不是管線。(D) 3 階管線指的是分成 3 個階段，和有幾個算術邏輯單元無關。"}, {"n": 2, "img": "112I2_2.webp", "ans": "C", "sol": "(C) 資料匯流排要能讀也能寫，所以是雙向，正確。(A) 位址匯流排由 CPU 單向發出。(B) 控制匯流排傳的是讀寫、中斷這類控制信號，位址是位址匯流排的事。(D) 16 條位址線可定址 2 的 16 次方 = 65536 個位址，不是 10 的 6 次方。"}, {"n": 3, "img": "112I2_3.webp", "ans": "AC", "note": "官方公告答案更正為 (A) 或 (C) 皆可。", "sol": "位址匯流排 16 條，可以編出 2 的 16 次方 = 64 K 個位址，所以答 64 K；但因為資料匯流排有 16 條(一次存取 2 個位元組)，若把題目的「多少位元組」理解成實際能存取的總量，就是 64 K × 2 = 128 K 位元組。官方認為題幹敘述不夠清楚，公告 (A) 或 (C) 皆可。"}, {"n": 4, "img": "112I2_4.webp", "ans": "B", "stem": "112I2_s4-5.webp", "sol": "113 的二進位是 01110001。SHR 右移 2 次並從最高位補 0，得到 00011100 = 28。也可以直接用 113 除以 2 的 2 次方取商 = 28(右移 n 位就是除以 2 的 n 次方取整數)。"}, {"n": 5, "img": "112I2_5.webp", "ans": "C", "stem": "112I2_s4-5.webp", "sol": "7 的二進位是 00000111，和 AL 做 AND 等於只留下最低 3 個位元、其餘清成 0。最低 3 個位元代表的正是 AL 除以 8 的餘數，所以答案是 (C)。(同理 AND 15 就是除以 16 取餘數。)"}, {"n": 6, "img": "112I2_6.webp", "ans": "D", "sol": "串列傳輸的資料線「較少」、適合距離「較遠」、一次送「1 位元」、用於 UART；並列傳輸線「較多」、距離「較近」、一次送多位元、用於印表機埠 LPT。對照表格，正確的格子是串列列的 ②(較遠)、④(UART) 和並列列的 ⑥(較近)、⑧(LPT)。"}, {"n": 7, "img": "112I2_7.webp", "ans": "D", "sol": "SPI 的訊號命名是以「訊號本身的方向」為準：MOSI 是 Master Out Slave In，兩端都叫 MOSI，所以主機的 MOSI 要接從機的 MOSI，(D) 正確。(A) 從機選擇線 SS 由主機發出。(B) SCLK 也由主機發出。(C) MOSI 要對 MOSI、MISO 對 MISO，不是交叉接。"}, {"n": 8, "img": "112I2_8.webp", "ans": "A", "sol": "0x87 = 10000111，低位元先送所以資料順序是 1,1,1,0,0,0,0,1。資料中 1 的個數是 4(偶數)，偶同位的同位元要補 0。完整資料框由閒置的高電位開始：起始位元 0 → 資料 11100001 → 同位 0 → 兩個停止位元 11 → 回到閒置，也就是 0 11100001 0 11，對應的是 (A)。"}, {"n": 9, "img": "112I2_9.webp", "ans": "C", "sol": "電流過大屬於會燒毀硬體的緊急狀況，必須立刻處理、不能等。輪詢(主程式或副程式)要等到程式跑到那一行才知道，定時中斷也要等到下一個時間點，都可能來不及。用硬體不可遮罩中斷 NMI 可以在事件發生當下立即搶進處理，而且不能被程式遮蔽掉。"}, {"n": 10, "img": "112I2_10.webp", "ans": "D", "sol": "HDMI、VGA、DP 都是顯示輸出介面。SCSI 是早期用來連接硬碟、磁帶機等儲存裝置的介面，不能拿來接螢幕。"}, {"n": 11, "img": "112I2_11.webp", "ans": "B", "sol": "「恆溫」的意思是要把水溫維持在設定值，系統必須知道現在的水溫才能決定要不要加熱，所以一定要有量測水溫的感測器。電流感測器、藍牙、WiFi 都只是加分功能，不是恆溫的必要條件。"}, {"n": 12, "img": "112I2_12.webp", "ans": "C", "sol": "(C) 比較效能時除了核心數，時脈快慢與耗電量都是重要指標，正確。(A) 大小核(big.LITTLE)架構的核心就不完全相同。(B) 核心數變四倍不代表效能變三倍以上，而且一定要作業系統與應用程式支援多執行緒才用得到。(D) 單核心也可以用時間分割的方式跑多執行緒。"}, {"n": 13, "img": "112I2_13.webp", "ans": "B", "sol": "(B) SRAM 可以直接覆寫，快閃記憶體要先抹除再寫入，所以 SRAM 的寫入速度快得多，正確。(A) SRAM 是揮發性的，斷電資料就沒了。(C) UART、I2C、SPI 全都是串列介面。(D) 規格裡沒有提到 ADC，不能假設它有類比轉數位功能。"}, {"n": 14, "img": "112I2_14.webp", "ans": "B", "sol": "(B) 可遮罩中斷要先把對應的中斷致能位元打開，中斷服務程式才會被執行，正確。(A) 只要允許巢狀中斷，更高優先權的中斷可以打斷目前的中斷服務程式。(C) 中斷服務程式和主程式要靠全域變數溝通，區域變數離開就不見了。(D) 外部中斷可以設定上升緣、下降緣或準位觸發。"}, {"n": 15, "img": "112I2_15.webp", "ans": "C", "sol": "ADC 連續取樣會產生大量資料，如果每一筆都要 CPU 搬一次會把核心吃光。DMA 讓 ADC 的結果直接寫進記憶體，不必經過 CPU，可以大幅減輕核心負擔並提高效率。快閃記憶體、ROM、SCSI 都不是處理這件事的技術。"}, {"n": 16, "img": "112I2_16.webp", "ans": "B", "sol": "規格寫的是 4 GB LPDDR4 SDRAM，SDRAM 是同步「動態」隨機存取記憶體，不是靜態的 SRAM，所以 (B) 錯誤。(A) 1.5 GHz 就是規格上的工作頻率。(C) L1 標了「每核」而 L2 沒有，表示 L2 的 1 MB 是四核共用。(D) 兩個 micro-HDMI、USB 3.0 兩個加 USB 2.0 兩個共四個。"}, {"n": 17, "img": "112I2_17.webp", "ans": "C", "sol": "非揮發性(Non-volatile)的定義就是斷電之後資料還在，所以 (C) 正確。(A) DRAM 是揮發性的，正好相反。(B) 傳輸方式(串列或並列)和揮發與否無關，USB 隨身碟就是串列。(D) 接頭形式也和非揮發性無關。"}, {"n": 18, "img": "112I2_18.webp", "ans": "D", "sol": "CMOS 的靜態功率消耗極低(只有切換時才耗電)，而且元件面積小、容易做高密度整合，所以超大型積體電路幾乎都用 CMOS。TTL、ECL 的靜態耗電大，BJT 是元件不是製程技術。"}, {"n": 19, "img": "112I2_19.webp", "ans": "D", "sol": "X 和 X反 送進 AND 閘，理想上恆為 0，但反閘有 td 的延遲，X 上升後 X反 還會「慢一拍」才變低，這段 td 內兩個輸入同時為 1，於是 Y 冒出一個寬度 td 的毛刺。再加上 AND 閘本身也有 td，這個毛刺要比 X 的上升緣再晚 td 才出現。只有 (D) 同時畫出「延後 td 出現」和「寬度 td」；(B) 把毛刺畫在上升緣當下，漏掉 AND 閘的延遲；(C) 連下降緣也畫出毛刺，但 X 下降時兩輸入不會同時為 1。"}, {"n": 20, "img": "112I2_20.webp", "ans": "A", "sol": "Vcc 代表邏輯 1。上面的 XOR 兩個輸入是 A 和 1，XOR 一端接 1 等於反相器，輸出 = A反。下面的 NAND 兩個輸入是 1 和 B，NAND 一端接 1 也等於反相器，輸出 = B反。最後的 NOR 把兩者合起來：(A反 + B反)反 = A·B，整個電路等效於一個 AND 閘。"}, {"n": 21, "img": "112I2_21.webp", "ans": "D", "sol": "第摩根定理有兩式：和的反 = 反的積、積的反 = 反的和，而且可以推廣到三個以上變數。(D) (A+B+C)反 = A反·B反·C反 正是第摩根定理，正確。(A) 左邊應該等於 A反B反，不是 (AB)反。(B)(C) 都把雙重否定或變數個數弄錯了。"}, {"n": 22, "img": "112I2_22.webp", "ans": "D", "sol": "f1 = B反 + C反 = (BC)反、f2 = B + C。把 B、C 四種組合列出來：BC = 00 時 f1=1、f2=0，XOR = 1；BC = 01 和 10 時 f1=1、f2=1，XOR = 0；BC = 11 時 f1=0、f2=1，XOR = 1。可見 Y 只在 B 與 C 相同時為 1，和 A 無關。對應的最小項是 000(0)、011(3)、100(4)、111(7)，Y = Σ(0,3,4,7)。"}, {"n": 23, "img": "112I2_23.webp", "ans": "D", "sol": "表中 Y = 1 的是 000、010、100、101、110、111，也就是 Σ(0,2,4,5,6,7)，(A) 對；Y = 0 的是 001、011，寫成最大項 Π(1,3)，(B) 對。化簡：A = 1 時四格全為 1 得 A，A = 0 時只有 C = 0 的兩格為 1 得 C反，所以 Y = A + C反，(C) 對。(D) 的電路是 ABC反 + AB反C反 = AC反，少了 A = 0 而 C = 0 的那兩格，和真值表不符，所以 (D) 錯誤。"}, {"n": 24, "img": "112I2_24.webp", "ans": "B", "sol": "8 位元 2 補數可表示的範圍是 -128 到 +127。-128 的做法：先寫 128 = 10000000，取補數再加 1 仍得 10000000，所以 -128 = 10000000(2)，剛好是範圍的最小值，可以表示。(注意 +128 才是這個範圍表示不出來的。)"}, {"n": 25, "img": "112I2_25.webp", "ans": "C", "sol": "每 3 個二進位位元能表示 2 的 3 次方 = 8 種值(000 到 111，也就是 0 到 7)，所以用這種分組方式建構出來的就是八進制。(同理每 4 個位元一組就是十六進制。)"}, {"n": 26, "img": "112I2_26.webp", "ans": "A", "sol": "選擇線 S1 = B、S0 = C，四個資料輸入由上到下是 I0 = A反、I1 = 0、I2 = A、I3 = 1。所以 Y = B反C反·A反 + B反C·0 + BC反·A + BC·1 = A反B反C反 + ABC反 + BC。再把 ABC反 + BC 併成 AB + BC(兩者涵蓋的最小項完全相同)，得到 Y = A反B反C反 + BC + AB，也就是 (A)。"}, {"n": 27, "img": "112I2_27.webp", "ans": "A", "stem": "112I2_s27-28.webp", "sol": "BCD 加法器的校正規則是：當和超過 9 或產生進位時要再加 6。6 的二進位是 0110，所以校正加法器 U3 的 B3B2B1B0 要送進 0、1、1、0。也就是 B3 與 B0 固定接邏輯 0，B2 與 B1 接到進位偵測電路 U2 的 Cout(需要校正時才變成 1，等於加 6；不需要時全是 0，等於加 0)。"}, {"n": 28, "img": "112I2_28.webp", "ans": "B", "stem": "112I2_s27-28.webp", "sol": "進位偵測的條件是：U1 本身有進位，或是和落在 1010 到 1111 之間。寫成布林式就是 Cout = Ico + I3·I2 + I3·I1。(B) 的接法是先用兩顆 NAND 算 (I1I3)反 和 (I2I3)反，再和 Ico反 一起送進第三顆 NAND，結果 = ((Ico反)(I1I3)反(I2I3)反)反 = Ico + I1I3 + I2I3，正好相符。(A) 下面兩顆是沒有小圓圈的 AND，算出來不對。"}, {"n": 29, "img": "112I2_29.webp", "ans": "A", "sol": "LED 的接法是 Vcc 經 R 再到 LED，LED 的另一端接閘的輸出，所以輸出為「低電位」時 LED 才會亮。要亮的是 CBA = 011、101、110、111，74138 的輸出是低態動作，這四種輸入分別讓 Y3、Y5、Y6、Y7 變低。把這四支接到 AND 閘，只要其中一支變低 AND 的輸出就是低，LED 就亮，所以 (A) 正確。(B) 用 NAND 剛好相反；(C)(D) 選到的輸出腳位也不對。"}, {"n": 30, "img": "112I2_30.webp", "ans": "B", "sol": "兩個 10 kΩ 都是接到地的「下拉」電阻，所以按鈕沒接到的那一邊是低電位、接到 +5 V 的那一邊是高電位，也就是兩個輸入是「高態動作」。高態動作的交叉耦合閂鎖器要用 NOR 閘(NAND 閂鎖器是低態動作，要搭配接到 Vcc 的上拉電阻)。所以 A 和 B 都是 NOR 閘。"}, {"n": 31, "img": "112I2_31.webp", "ans": "A", "sol": "先看觸發方式：三顆正反器的時脈端只有三角形沒有小圓圈，是「正緣」觸發；而且下一級的時脈接的是前一級的 Q(不是 Q反)。正緣觸發再接 Q，得到的是「下數」漣波計數器，所以 (A) 把它說成上數型是錯的。(B) QB 與 QC 經 NAND 接到 CLR，計到 QB、QC 同時為 1 就被清除，可用狀態共 6 個，確實是模數 6。(C)(D) 模數 6 表示整個計數循環 6 個時脈走完一輪，QB 與 QC 都是一輪才變化一個完整週期，頻率 = 12 kHz ÷ 6 = 2 kHz，兩個都對。"}, {"n": 32, "img": "112I2_32.webp", "ans": "B", "sol": "(A) 史密特反閘配 R、C 是最典型的張弛振盪器，會持續振盪。(C) 兩個反相器加 RP、R、C 也是標準的 CMOS 無穩態振盪電路。(D) 是 555 的無穩態接法(RA、RB、C，放電腳接在 RA 與 RB 之間，門檻與觸發腳一起接到電容)，會持續輸出方波。(B) 的第一組 C 接 Vcc、R 接地是「電源啟動時觸發一次」的微分觸發網路，第二組 RC 決定脈波寬度，這是單穩態(一擊式)電路，通電後只輸出一個脈波就穩定下來，所以 (B) 不是無穩態振盪。"}, {"n": 33, "img": "112I2_33.webp", "ans": "A", "stem": "112I2_s33-34.webp", "sol": "由狀態圖可知循環是 00 → 10 → 11 → 01 → 00。現態 QBQA = 01 的下一個狀態是 00。D 型正反器的特性是「次態等於 D 的輸入值」，所以 DB DA 就等於次態 00。答案是次態 00、輸入 00。"}, {"n": 34, "img": "112I2_34.webp", "ans": "D", "stem": "112I2_s33-34.webp", "sol": "把四個狀態的次態列出來：00→10、10→11、11→01、01→00。因為 D 型正反器的 D 就是次態，所以 DB 的真值是 1,1,0,0 對應現態 (QB,QA) = (0,0),(1,0),(1,1),(0,1)。觀察可得 DB 在 QA = 0 時為 1、QA = 1 時為 0，也就是 DB = QA反；DA 的真值是 0,1,1,0，剛好等於 QB，所以 DA = QB。四個狀態代回去都符合。"}, {"n": 35, "img": "112I2_35.webp", "ans": "C", "sol": "(C) 叫叫 CABD 的 D 是 Defibrillation，就是使用 AED 自動體外心臟電擊去顫器電擊，正確。(A) 發生火災一定要通報。(B) 看到同學觸電倒地要先切斷電源或用絕緣物把人移開，直接碰觸會連自己一起觸電。(D) 可燃性塗料引起的火災不能用水，水會讓火勢擴散。"}, {"n": 36, "img": "112I2_36.webp", "ans": "B", "sol": "C 語言規定函式要先宣告(或先定義)才能呼叫。sub() 定義在行號 9，卻在行號 5 就被呼叫，編譯器到行號 5 時還不認識它。行號 3 本來就有一行函式原型但被 // 註解掉了，把註解拿掉讓原型生效就能編譯成功。其餘選項都和這個錯誤無關。"}, {"n": 37, "img": "112I2_37.webp", "ans": "A", "sol": "(A) 語法錯誤是程式寫法不合文法，編譯器在編譯階段就會抓出來，正確。(B) 除以 0 編譯得過，是執行時才出問題。(C) 指標沒初始化就寫入屬於執行期錯誤(通常是當掉)，語法上沒問題。(D) 敘述結尾少分號是標準的語法錯誤，編譯就過不了。"}, {"n": 38, "img": "112I2_38.webp", "ans": "C", "stem": "112I2_s38-39.webp", "sol": "C 語言規定宣告成 const 的變數必須在宣告時就給初始值，而且之後不能再被指定。行號 3 的 const int Value3; 沒給初值、行號 5 又想指定給它，兩項都違規。把 const 刪掉之後 Value3 就是普通整數變數，程式即可編譯成功。"}, {"n": 39, "img": "112I2_39.webp", "ans": "B", "stem": "112I2_s38-39.webp", "sol": "刪掉 const 之後：Value2 被前處理器展開成 (Value1 - 1) = (100 - 1) = 99，所以 Value3 = 99。CheckValue = Value1 + Value3 = 100 + 99 = 199。"}, {"n": 40, "img": "112I2_40.webp", "ans": "D", "stem": "112I2_s40-42.webp", "sol": "呼叫 inc(x) 時傳的是 x 的「值」10。函式裡面另外宣告了一個區域變數 sum = 2，會把外面的全域 sum 遮蔽掉，sum = 2 + 10 = 12；xin++ 只改到參數的複本，不影響主程式的 x。回傳 12 給 main 的區域變數 sum。所以印出 12, 10。"}, {"n": 41, "img": "112I2_41.webp", "ans": "A", "stem": "112I2_s40-42.webp", "sol": "要讓函式裡的修改反映到主程式的 x，必須改成「傳址呼叫」：呼叫端傳位址 &x，函式端用指標接收並以 *xin 存取內容。(B)(D) 把呼叫端寫成 *x 是對一個非指標變數取值，語法就錯；(C) 函式裡用 &xin 拿到的是參數本身的位址，改它一樣不會影響主程式。"}, {"n": 42, "img": "112I2_42.webp", "ans": "A", "stem": "112I2_s40-42.webp", "sol": "行號 2 的 sum 宣告在所有函式之外，是全域變數；行號 4 的 sum 宣告在 inc() 裡面，是區域變數；行號 10 的 sum 宣告在 main() 裡面，也是區域變數。區域變數會在自己的範圍內遮蔽同名的全域變數，這也正是這支程式輸出 12 而不是 11 的原因。"}, {"n": 43, "img": "112I2_43.webp", "ans": "C", "sol": "sizeof(s) 量的是指標本身的大小，64 位元電腦是 8；sizeof(*s) 量的是指標指到的東西，也就是一個 char，固定是 1。printf 印的是 CharSize 和 *(s+2)，CharSize = 1，*(s+2) 是字串 \"ABC\" 的第 3 個字元 'C'。所以輸出 1, C。(CharPtrSize 算了但沒印出來，是陷阱。)"}, {"n": 44, "img": "112I2_44.webp", "ans": "D", "sol": "關鍵在運算子優先順序：算術運算比位移高。行號 3 的 Num1 << Num3-1 要先算 3-1 = 2，再 10 左移 2 位 = 40。行號 4 的 Num2 * Num1 >> 1 要先算 5 × 40 = 200，再右移 1 位 = 100。所以 Num1 = 40、Num2 = 100。"}, {"n": 45, "img": "112I2_45.webp", "ans": "A", "sol": "& 是位元 AND，a = 0x0a = 1010、b = 0x05 = 0101，兩者沒有任何一個位元同時為 1，a & b = 0，所以 if 的條件不成立，走 else。else 印的是 a&&b，&& 是邏輯 AND，只看兩邊是不是非零，a、b 都非零所以結果是 1。輸出 a&&b = 1。"}, {"n": 46, "img": "112I2_46.webp", "ans": "B", "sol": "原程式第一圈 x = 0、y = 10sin(0) = 0，接著 ++x 先把 x 變成 1 再比較 1 <= 0，條件不成立就結束，所以只跑一次。改成 x++ 是「先比較再加一」：第一圈比較 0 <= 0 成立，之後 x 才變 1；第二圈 y = 10sin(1) ≈ 8.4，比較 1 <= 8.4 成立；第三圈 y = 10sin(2) ≈ 9.1，比較 2 <= 9.1 成立；第四圈 y = 10sin(3) ≈ 1.4，比較 3 <= 1.4 不成立才結束，總共跑 4 次。(A)(D) 改的是被遮蔽掉的全域 x，完全沒作用；(C) 改 y 的初值也沒用，因為迴圈一進去就把 y 重新算過。"}, {"n": 47, "img": "112I2_47.webp", "ans": "D", "sol": "程式從 P[0] 開始，每次把索引加 Count，共取 11 個字元。把字典 \"IWhLoaorevYTeouTW5aM7iynwyuaTYn?\" 編號後，取第 0、3、6、9、12、15、18、21、24、27、30 個字元正好是 I、L、o、v、e、T、a、i、w、a、n，拼起來就是 ILoveTaiwan，所以 Count = 3。"}, {"n": 48, "img": "112I2_48.webp", "ans": "D", "sol": "p 宣告成 int *，只能指到整數。(A) MyName 是 char 陣列，陣列名稱會退化成 char*，型態不符。(B) &MyName[0] 同樣是 char*。(C) MyWeight 是 double 變數不是位址，連型態都不對。(D) &MyAge 是 int 變數的位址，型態正好是 int*，編譯不會有錯誤或警告。"}, {"n": 49, "img": "112I2_49.webp", "ans": "A", "sol": "(A) 在類別外面定義成員函式要寫「回傳型態 類別名稱::函式名稱」，而且因為是成員函式所以看得到私有的 Length、Width，寫法完全正確。(B) 少了 CalculateArea:: 就變成普通的全域函式，碰不到私有成員。(C) 少寫回傳型態 double。(D) 宣告要回傳 double 卻沒有 return 敘述。"}, {"n": 50, "img": "112I2_50.webp", "ans": "C", "sol": "(C) struct 的成員預設是 public，所以在函式內宣告的 struct 變數，其成員在該函式範圍內都可以直接存取，正確。(A) class 的成員預設是 private，main 碰不到。(B) struct 宣告出來的物件當然可以當作 class 的成員變數。(D) 同一個 class 內的成員函式本來就可以存取自己的成員變數。"}]});
EXAM.push({"code": "111I2", "y": 111, "p": "I2", "sub": "微處理機、數位邏輯設計、程式設計實習", "items": [{"n": 1, "img": "111I2_1.webp", "ans": "D", "sol": "每一道指令都一定要先解碼，微處理機才知道這串二進位到底要做什麼、運算元在哪裡，不可能跳過解碼就直接執行，所以 (D) 錯誤。(A) 提取後 PC 自動遞增、(B) 解碼時拆成運算碼與運算元、(C) 執行前先取運算元，都是正確的描述。"}, {"n": 2, "img": "111I2_2.webp", "ans": "D", "sol": "PWM 是用固定頻率、改變「導通時間比例」的方式，讓負載接收到的平均電壓隨工作週期改變，等於用數位輸出模擬出可調的類比準位，而且開關元件只有全開全關、效率高，最適合驅動馬達這類大電流負載。TWI(就是 I2C)、UART 是通訊介面，JTAG 是測試除錯介面。"}, {"n": 3, "img": "111I2_3.webp", "ans": "C", "sol": "隨身碟和固態硬碟都是靠快閃記憶體(Flash Memory)儲存資料，斷電後資料仍在。SRAM 是揮發性的，斷電就消失，只能拿來做快取或暫存，不可能用來做儲存裝置。"}, {"n": 4, "img": "111I2_4.webp", "ans": "B", "sol": "作業系統本來就包含一大堆基本輸出入的驅動程式(鍵盤、滑鼠、磁碟、顯示等)，否則根本沒辦法和硬體溝通，所以 (B) 錯誤。(A)(C)(D) 分別描述作業系統的介面、圖形使用者介面與資源管理功能，都正確。"}, {"n": 5, "img": "111I2_5.webp", "ans": "C", "sol": "照著程式追一遍：INC E 讓 E = 6、DEC D 讓 D = 2、MOV F,E 讓 F = 6、MOV G,D 讓 G = 2、DEC G 讓 G = 1、INC F 讓 F = 7。接著是指令 X，最後 ADD F,D 再 SUB F,E。若 X 什麼都不做，F = 7 + 2 - 6 = 3，差 1 才到 4。試四個選項：(A) E 變 7 得 2、(B) D 變 1 得 2、(D) D 變 1 得 2，只有 (C) ADD F,G 讓 F = 7 + 1 = 8，最後 8 + 2 - 6 = 4。"}, {"n": 6, "img": "111I2_6.webp", "ans": "B", "sol": "USB 1.1/2.0 採用 NRZI 編碼：遇到資料 0 就讓訊號準位反轉、遇到 1 就維持不變，再配合位元填塞(bit stuffing)讓接收端能夠從資料流中還原時脈，不必另外拉一條時脈線。"}, {"n": 7, "img": "111I2_7.webp", "ans": "D", "sol": "SPI 有 MOSI 與 MISO 兩條獨立資料線，可以同時送與收，是全雙工；I2C 只有一條 SDA，同一時間只能單向傳，是半雙工。所以 (D) 說兩者都是半雙工是錯的。(A)(B)(C) 都正確：兩者都是串列、都靠時脈線同步、都能做一主多從。"}, {"n": 8, "img": "111I2_8.webp", "ans": "D", "sol": "SPI 的共用線有三條：SCLK、MOSI、MISO。星狀(各自獨立選擇)的一對三架構，主裝置必須對每一個從裝置各拉一條從機選擇線 SS，所以要 3 條。合計 3 + 3 = 6 支接腳。"}, {"n": 9, "img": "111I2_9.webp", "ans": "B", "sol": "NMI 的全名就是「不可遮罩中斷」，顧名思義不能被中斷遮罩暫存器關掉，一來就一定要處理(通常是嚴重錯誤或斷電警告)，所以 (B) 錯誤。能用 IMR 遮罩的是可遮罩中斷 MI。"}, {"n": 10, "img": "111I2_10.webp", "ans": "A", "sol": "SP/EN 當輸入腳用時：SP = 1 代表這顆是主控制器、SP = 0 代表是僕控制器，(A) 把它說反了所以錯誤。(B) IR0 到 IR7 共 8 支中斷請求腳、(C) D0 到 D7 共 8 支資料腳、(D) CAS0 到 CAS2 共 3 支可串接 8 顆、1 主 8 僕最多 64 個中斷請求，都正確。"}, {"n": 11, "img": "111I2_11.webp", "ans": "B", "sol": "SRAM 的每一個位元是用正反器(通常 6 顆電晶體)保存，只要有電就不會跑掉，所以不用更新、速度快但面積大；DRAM 是用一顆電晶體加一個電容存電荷，電荷會漏掉所以必須定期更新(refresh)，但密度高、便宜。"}, {"n": 12, "img": "111I2_12.webp", "ans": "C", "sol": "名字裡有 Serial 的才是串列：SAS(Serial Attached SCSI)與 SATA(Serial ATA)都是串列介面；而 ATA(也就是 IDE/PATA)與傳統 SCSI 都是並列介面。所以只有 (C) 正確。"}, {"n": 13, "img": "111I2_13.webp", "ans": "B", "sol": "硬碟採用 CHS 定址，容量 = 讀寫頭數(面數) × 每面磁軌數 × 每個磁軌的磁區數 × 每個磁區的大小。磁叢(cluster)是作業系統檔案系統的配置單位，不是硬碟硬體容量公式的一部分，所以 (A) 多算了。"}, {"n": 14, "img": "111I2_14.webp", "ans": "A", "sol": "n 道指令：沒有管線要 4n 個時序；有管線則第一道要 4 個時序填滿，之後每個時序出一道，共 4 + (n-1) = n + 3 個時序。要快 3 倍就是 4n/(n+3) = 3，解得 4n = 3n + 9，n = 9。(代 n = 8 進去只有 32/11 ≈ 2.9 倍，不夠。)"}, {"n": 15, "img": "111I2_15.webp", "ans": "D", "sol": "兩顆單核心微處理機要兩套封裝、兩套外部匯流排與快取，成本高、耗電多，核心之間溝通還要走外部匯流排所以慢；雙核心把兩個核心做在同一顆晶片裡，成本低、耗能少、核心間溝通快。所以 (D) 完全說反了。"}, {"n": 16, "img": "111I2_16.webp", "ans": "B", "sol": "VGA 是類比介面，只能傳類比影像訊號，不能傳數位訊號，所以 (B) 錯誤。(A) DP 可同時傳影音、(C) DVI 傳未壓縮數位影像、(D) HDMI 傳未壓縮的影音，都正確。"}, {"n": 17, "img": "111I2_17.webp", "ans": "D", "sol": "Flash Memory 是「非揮發性」記憶體，斷電資料還在，這正是它能做隨身碟的原因，所以 (D) 把它和 RAM 歸在一起說成揮發性是錯的。(A)(B)(C) 描述記憶體階層的速度與容量關係，都正確。"}, {"n": 18, "img": "111I2_18.webp", "ans": "B", "sol": "週期 T = 1/f = 1/25000 = 40 μs = 0.04 ms。工作週期 = 脈波寬度/週期 = 0.025 ms/0.04 ms = 0.625 = 62.5%。"}, {"n": 19, "img": "111I2_19.webp", "ans": "A", "sol": "電路是 AND 之後接一個 OR，而且 OR 的輸出有小圓圈、另一個輸入接 0，所以 C = (AB + 0)反 = (AB)反。A = 0110、B = 1100，逐位相乘得 AB = 0100，再全部取反得 C = 1011。"}, {"n": 20, "img": "111I2_20.webp", "ans": "C", "sol": "這是一個全加器：P 是和、Q 是進位。(A) P = A ⊕ B ⊕ C 正確。(B) Q = AB + BC + AC 正確。(D) 真值表逐列代入也都對。(C) 把 Q 畫成一個三輸入 AND 閘，那代表 Q = ABC，只有三個輸入全為 1 時才是 1；但真值表裡 011、101、110 的 Q 也都是 1，和 ABC 不符，所以 (C) 的化簡圖是錯的。"}, {"n": 21, "img": "111I2_21.webp", "ans": "C", "sol": "三輸入反及閘 Y = (ABC)反，依第摩根定理等於 A反 + B反 + C反。(C) 的 A反 + (AB)反 + C反 + (BC)反 展開後 = A反 + (A反+B反) + C反 + (B反+C反) = A反 + B反 + C反，和 NAND 完全相同。(A) 是 A反B反C反(三輸入 NOR)、(B)(D) 展開後也都不等於 NAND。"}, {"n": 22, "img": "111I2_22.webp", "ans": "A", "sol": "把電路化簡後得到的函數是最小項 1、2、3、7、10、11、15。(A) CD + B反C + A反B反D 正是它的最簡積項和，正確。(B) 寫成 CD + B反(C + A反D)，函數值雖然一樣，但那是提出公因式的因式分解式，不是積項和的形式。(C) 的中間那一項 (B反 + CD) 裡面含有乘積 CD，不是純粹的「和項」，所以也不能算標準的和項積。(D) 展開後只有最小項 2、3、7、11、15，少了 1 和 10，函數根本不對。"}, {"n": 23, "img": "111I2_23.webp", "ans": "C", "sol": "1 的位置是 1、3、7、11、15，隨意項 0、2、5 可以自由當 1 或 0。畫卡諾圖後用和項積化簡：D 這一項涵蓋 D = 1 的整欄，再用 (A反 + C) 把 A = 1 且 C = 0 的 9 與 13 這兩個 0 排除掉，得到 F = D(A反 + C)，涵蓋 1、3、5、7、11、15，所有該是 1 的都包到、所有 0 都沒碰到。(D) 雖然函數一樣但用了三個和項共 6 個文字，不是最簡。"}, {"n": 24, "img": "111I2_24.webp", "ans": "A", "sol": "254 = 256 - 2，256 是 100000000，減 2 得 11111110。也可以直接除 2 取餘數：254 → 11111110(2)。"}, {"n": 25, "img": "111I2_25.webp", "ans": "A", "sol": "16 - 32 = -16。-16 的 8 位元 2 補數：先寫 16 = 00010000，取 1 補數得 11101111，再加 1 得 11110000。(選項 (D) 的 11101111 是忘了加 1 的 1 補數，是最常見的錯誤。)"}, {"n": 26, "img": "111I2_26.webp", "ans": "A", "sol": "上面那顆 AND 的輸入是 A 和 C反(C 經反閘)，下面那顆 AND 的輸入是 B 和 C，兩者再 OR：D = A·C反 + B·C。意思就是 C = 0 時輸出 A、C = 1 時輸出 B，這正是以 C 為選擇線的 2 對 1 多工器。"}, {"n": 27, "img": "111I2_27.webp", "ans": "A", "sol": "共陽極顯示器的共同腳接 VCC，所以某一段的接腳要給「低電位」那一段才會亮。數字 3 要亮的是 a、b、c、d、g 五段，e、f 不亮。依 ABCDEFG 的順序：亮的給 0、不亮的給 1，得到 0、0、0、0、1、1、0 = 0000110。"}, {"n": 28, "img": "111I2_28.webp", "ans": "C", "sol": "X 的每一位都先和 C0 做 XOR 再送進加法器的 B 端。C0 = 1 時 XOR 等於取反，所以 B = (0101)反 = 1010。加法器算 A + B + Cin = 1010 + 1010 + 1 = 10101，進位輸出 C1 = 1、和 S3S2S1S0 = 0101。(這個電路其實就是加減法器：C0 = 1 時做 A 減 X。)"}, {"n": 29, "img": "111I2_29.webp", "ans": "A", "sol": "半加器只有 A、B 兩個輸入，根本沒有 Cin 這支腳，所以 (A) 說「Cin 的功能與半加器相同」是錯的。(B) S = A ⊕ B ⊕ Cin、(C) Cout = AB + BCin + ACin、(D) 多個全加器可串接成漣波進位加法器，都正確。"}, {"n": 30, "img": "111I2_30.webp", "ans": "B", "sol": "JK 正反器的 J = K = 1 是「翻轉(Toggle)」模式，每來一個時脈 Q 就反相一次，所以 Q 要兩個時脈才完成一個完整週期，頻率剛好是時脈的一半：100 MHz / 2 = 50 MHz。這也是為什麼 JK 接成 T 型可以當除頻器。"}, {"n": 31, "img": "111I2_31.webp", "ans": "D", "sol": "圖上時脈端畫了小圓圈，代表「負緣觸發」：只有在 clk 由 1 變 0 的那一瞬間才把當時的 D 值抄到 Q，其餘時間 Q 一律保持不變。四個選項裡只有 (D) 的 Q 每一次變化都發生在 clk 的下降邊，而且抄到的值和當下的 D 一致；(B) 是在上升邊變化(正緣觸發)，(A)(C) 的取樣值與 D 對不上。"}, {"n": 32, "img": "111I2_32.webp", "ans": "C", "sol": "由圖可看出每顆多工器的第 0 號輸入接回自己正反器的輸出(保持不變)、第 3 號輸入接 I(平行載入)，中間兩個分別接左移與右移的來源。選擇線的編碼就是輸入編號：S1S0 = 00 不變、01 向左移位、10 向右移位、11 平行載入。所以只有 (C) 正確，(A)(B)(D) 都把功能對錯了。"}, {"n": 33, "img": "111I2_33.webp", "ans": "A", "sol": "D 型正反器把 Q反 接回 D，是除 2 電路，所以 T 的頻率是 555 輸出的一半。要讓 T 為 1 kHz，555 本身就要輸出 2 kHz。無穩態 555 的 f = 1.44/((R1 + 2R2)C1)。代 (A)：R1 + 2R2 = 10k + 60k = 70 kΩ，f = 1.44/(70k × 0.01μ) ≈ 2057 Hz，除 2 後約 1029 Hz，最接近 1 kHz。(B)(C)(D) 的電阻愈大頻率愈低，除 2 後分別只剩約 686、514、343 Hz，差太多。"}, {"n": 34, "img": "111I2_34.webp", "ans": "A", "sol": "照狀態圖逐條抄：X = 0 時 S0、S1、S2、S3 全部回到 S0(00)；X = 1 時 S0 到 S1(01)、S1 到 S2(10)、S2 到 S3(11)、S3 回到 S0(00)。把它填成表就是 X=0 那四列次態全是 00，X=1 那四列依序是 01、10、11、00，完全符合 (A)。"}, {"n": 35, "img": "111I2_35.webp", "ans": "D", "sol": "心肺復甦術的順序是「叫、叫、C、A、B、D」，也就是先胸部按壓(Compression)再暢通呼吸道(Airway)、人工呼吸(Breathing)、電擊(Defibrillation)，(D) 把 C 放到 A、B 後面是錯的。(A) 電氣火災用二氧化碳、(B) 酒精屬 B 類(可燃液體)火災、(C) 燒燙傷是沖脫泡蓋送，都正確。"}, {"n": 36, "img": "111I2_36.webp", "ans": "B", "sol": "#include、#define 這類前置處理命令是給前置處理器看的，不是 C 的敘述，結尾「不要」加分號，加了反而會出錯，所以 (B) 錯誤。(A) 要編譯連結才有執行檔、(C) 從 main() 開始執行、(D) // 是單行註解，都正確。"}, {"n": 37, "img": "111I2_37.webp", "ans": "D", "sol": "正確寫法是 #define 常數名稱 常數值，井字號不能少、名稱與值之間用空白隔開、不加等號也不加分號。(A)(B) 少了井字號；(C) 多了等號(那樣 PI 會被展開成「= 3.14」)；只有 (D) 正確。"}, {"n": 38, "img": "111I2_38.webp", "ans": "A", "sol": "float 通常佔 4 位元組、有效位數約 7 位；double 佔 8 位元組、有效位數約 15 位，精確度明顯比 float 高，所以 (A) 說兩者相同是錯的。(B)(C)(D) 分別描述 int、double、char 的用途，都正確。"}, {"n": 39, "img": "111I2_39.webp", "ans": "B", "sol": "x = a/b 兩邊都是 int，做的是整數除法，7/2 得到 3(小數被截掉)，再存進 int 的 x 還是 3。y = (float)a/b 先把 a 轉成浮點數，整個算式就變成浮點除法 7.0/2 = 3.5，存進 float 的 y 是 3.5。"}, {"n": 40, "img": "111I2_40.webp", "ans": "C", "sol": "^ 在 C 裡是位元互斥或不是次方。9 = 1001、7 = 0111，逐位 XOR 得 1110 = 14。"}, {"n": 41, "img": "111I2_41.webp", "ans": "D", "sol": "(A) !(1!=3) 是 !true = false，1==3 也是 false，false || false = false。(B) !!(1==3) 是 !!false = false，true && false = false。(C) !(1<3) = false，1>=3 = false，false || false = false。(D) 1<3 是 true，!(1>=3) 是 !false = true，true && true = true，只有 (D) 為真。"}, {"n": 42, "img": "111I2_42.webp", "ans": "D", "sol": "a = 45。第一個條件 45 >= 60 不成立，第二個 45 >= 50 也不成立，所以走最後的 else：y = 45 + 3 = 48。(if-else if-else 只會執行其中一條，別把三條都算一遍。)"}, {"n": 43, "img": "111I2_43.webp", "ans": "C", "sol": "i 從 1 開始，每次加 2，條件是 i < 8，所以 i 依序是 1、3、5、7(到 9 就停)。total = 1 + 3 + 5 + 7 = 16。"}, {"n": 44, "img": "111I2_44.webp", "ans": "D", "sol": "這是輾轉相除法(求最大公因數)。a=30、b=42，r = 30%42 = 30(小數除大數餘數就是自己)。進迴圈：a=42、b=30、r=12；a=30、b=12、r=6；a=12、b=6、r=0 結束。y = b = 6，正是 30 與 42 的最大公因數。"}, {"n": 45, "img": "111I2_45.webp", "ans": "C", "sol": "陣列宣告 int Array[4] = {1, 2, 3} 只給了三個初值，第四個會自動補 0，所以內容是 {1, 2, 3, 0}。迴圈 i 從 1 跑到 3，加的是 Array[1] + Array[2] + Array[3] = 2 + 3 + 0 = 5。(沒有加到 Array[0] 的 1，這是陷阱。)"}, {"n": 46, "img": "111I2_46.webp", "ans": "D", "sol": "ptr 原本指向字串的第一個字元 'a'，++ptr 先把指標往後移一格再使用，所以傳給 printf 的位址是 'b' 的位置。%s 會從那個位址一路印到字串結束符號，輸出 bcde。"}, {"n": 47, "img": "111I2_47.webp", "ans": "C", "sol": "Func(5, 3) 裡 A = w*h/2.0 = 5*3/2.0 = 15/2.0 = 7.5。雖然 w、h 都是 int，但除數寫成 2.0 是浮點數，整個算式會自動提升成浮點除法，所以不會被截成 7。回傳型態是 double，result 也是 double，結果就是 7.5。"}, {"n": 48, "img": "111I2_48.webp", "ans": "D", "sol": "函式要接收兩個整數，所以參數寫 (int, int)；回傳值要有小數點後兩位以上的精確度，就不能用 int，必須用浮點型態。(A) 沒有宣告參數、(B) void 不回傳值、(C) int 會把小數截掉，只有 (D) float BMI(int, int) 同時滿足兩個條件。"}, {"n": 49, "img": "111I2_49.webp", "ans": "B", "sol": "達到資訊隱藏目的的是「封裝(Encapsulation)」，把資料設成私有、只開放方法存取；「多型(Polymorphism)」講的是同一個介面依物件不同而有不同行為。所以 (B) 張冠李戴。(A)(C)(D) 都是物件導向的正確描述。"}, {"n": 50, "img": "111I2_50.webp", "ans": "C", "sol": "結構的成員可以是相同資料型態，例如 struct Point { int x; int y; }; 兩個成員都是 int 完全合法，所以 (C) 說「只能使用不同資料型態」是錯的。(A) 結構確實是自訂資料型態、(B) 宣告變數要用已定義的結構名稱、(D) 定義結構要用 struct 關鍵字，都正確。"}]});
EXAM.push({"code": "115P1", "y": 115, "p": "P1", "sub": "基本電學、基本電學實習、電子學、電子學實習", "items": [{"n": 1, "img": "115P1_1.webp", "ans": "B", "sol": "價電子就是原子最外層軌道上的電子，決定導電性。(A) 電子數等於質子數；(C) 失去電子變成正離子；(D) 原子整體電中性。"}, {"n": 2, "img": "115P1_2.webp", "ans": "C", "sol": "電阻與溫度成線性，斜率 = (12-10)/(66-16) = 0.04 Ω/℃。20 ℃ 時 R = 10 + 0.04×4 = 10.16 Ω，α20 = 0.04 / 10.16 ≈ 0.00393 /℃。"}, {"n": 3, "img": "115P1_3.webp", "ans": "A", "sol": "以底線為 0 V。右邊 4 V 電源使該節點為 4 V，10 V 電源使上方節點為 14 V。6 V 電源讓 5 Ω 上端為 4 + 6 = 10 V。4 Ω 流下 (14-10)/4 = 1 A，5 Ω 流下 10/5 = 2 A，由 KCL 得 I = 2 - 1 = 1 A。"}, {"n": 4, "img": "115P1_4.webp", "ans": "D", "sol": "先把 12 Ω、8 Ω、4 Ω 組成的 Δ 轉成 Y，再合併可得電流源兩端看進去的等效電阻為 4 Ω ∥ 4 Ω = 2 Ω。V1 = 12 A × 2 Ω = 24 V。"}, {"n": 5, "img": "115P1_5.webp", "ans": "B", "sol": "設下方為 0 V，用節點電壓法：4 V 源固定左節點，兩個電流源分別注入中、右節點，解得中、右兩節點電壓都是 8 V。兩端等電位，所以 4 Ω 上的 I = 0 A。"}, {"n": 6, "img": "115P1_6.webp", "ans": "C", "sol": "用含電壓源的超節點配合 KCL 解出中間與右邊節點電壓都是 1 V。2 Ω 兩端沒有電位差，所以 I = 0 A。這種題先找「等電位」比硬解快很多。"}, {"n": 7, "img": "115P1_7.webp", "ans": "B", "sol": "互感定義 M = NB·ΦB / IA，所以與 B 線圈交鏈的磁通 ΦB = M·IA / NB = (6×10⁻³ × 0.5) / 300 = 1×10⁻⁵ 韋伯。NA 是用不到的誘餌。"}, {"n": 8, "img": "115P1_8.webp", "ans": "B", "sol": "穩態下沒有電流，R 無壓降，100 V 直接加在串聯的電容串上。各串聯電容帶相同電荷 Q = 500 μF × 16 V = 8000 μC。100 μF 分到 8000/100 = 80 V，剩下 100 - 16 - 80 = 4 V 落在 1200 μF 與 Cx 的並聯上，故 1200 + Cx = 8000/4 = 2000 μF，Cx = 800 μF。"}, {"n": 9, "img": "115P1_9.webp", "ans": "A", "sol": "兩平行載流導線的作用力 F = μ0·I1·I2·L / (2πd) = (4π×10⁻⁷ × 50 × 100 × 50) / (2π × 0.2) = 0.25 牛頓。電流方向相反者相斥。"}, {"n": 10, "img": "115P1_10.webp", "ans": "B", "sol": "電感看到的戴維寧電阻 = 3 + (2 ∥ 3) = 4.2 Ω，τ = L/R = 8.4 mH / 4.2 Ω = 2 ms。20 ms 等於 10τ，已達穩態，電感視為短路：2 + (3 ∥ 3) = 3.5 Ω，I = 7 / 3.5 = 2 A。"}, {"n": 11, "img": "115P1_11.webp", "ans": "A", "sol": "f = 100 Hz → ω = 2πf = 200π rad/s；有效值 10 A → 峰值 10√2 A；落後 30° → 相角為 -30°。所以 i(t) = 10√2 sin(200πt - 30°) A。"}, {"n": 12, "img": "115P1_12.webp", "ans": "B", "sol": "週期為 3 秒：第 1 秒為 0 V，第 2 秒由 0 線性升到 20 V（面積 10），第 3 秒為 -5 V（面積 -5）。平均值 = (0 + 10 - 5) / 3 = 5/3 V。"}, {"n": 13, "img": "115P1_13.webp", "ans": "B", "sol": "ω = 100：XC = 1/(ωC) = 1/(100×10⁻³) = 10 Ω → -j10；XL = ωL = 100×0.1 = 10 Ω → j10。j10 與 10 Ω 並聯得 5 + j5，再與 -j10 串聯，總阻抗 = 5 - j5 Ω。"}, {"n": 14, "img": "115P1_14.webp", "ans": "D", "sol": "Z = 3 + j7 - j3 = 3 + j4，|Z| = 5 Ω。PF = R/|Z| = 3/5 = 0.6，電感性所以落後。Vrms = 110 V，I = 110/5 = 22 A，P = I²R = 22² × 3 = 1452 W。"}, {"n": 15, "img": "115P1_15.webp", "ans": "A", "stem": "115P1_s15-16.webp", "sol": "並聯 RLC：f0 = 1/(2π√(LC)) = 1/(2π√(0.1 × 10⁻³)) ≈ 15.9 Hz。並聯諧振的 Q = R√(C/L) = 100 × √(1000μ/0.1) = 100 × 0.1 = 10。"}, {"n": 16, "img": "115P1_16.webp", "ans": "A", "stem": "115P1_s15-16.webp", "sol": "並聯諧振時 L 與 C 互相抵消等於開路，電路只剩 R。is 有效值 = 100 V / 100 Ω = 1 A。這也是並聯諧振「幹線電流最小」的意思。"}, {"n": 17, "img": "115P1_17.webp", "ans": "B", "sol": "平衡的單相三線式，中性線電流為 0，只有兩條外線有損失。每相迴路阻抗 = (1 + j1) + (7 + j5) = 8 + j6，|Z| = 10 Ω，I = 110/10 = 11 A。總損失 = 2 × 11² × 1 = 242 W。"}, {"n": 18, "img": "115P1_18.webp", "ans": "C", "sol": "總視在功率 S = P/PF = 3600/0.8 = 4500 VA，每相 1500 VA。Δ 接時相電壓等於線電壓 300 V，|Zp| = V²/S相 = 300²/1500 = 60 Ω。R = 60×0.8 = 48，X = 60×0.6 = 36，落後取正號，Zp = 48 + j36 Ω。"}, {"n": 19, "img": "115P1_19.webp", "ans": "D", "sol": "心跳停止要立刻施行心肺復甦術（CPR），有 AED 要盡快使用。擦酒精、等家屬都會錯過黃金急救時間；口對口吹氣只是 CPR 的一部分，不能取代胸外按壓。"}, {"n": 20, "img": "115P1_20.webp", "ans": "A", "sol": "兩個相同電阻並聯為 110 Ω，表示每個都是 220 Ω。五環電阻前三環是有效數字、第四環是倍數：紅紅黑 = 220，黑 = ×1，所以是 220 Ω。"}, {"n": 21, "img": "115P1_21.webp", "ans": "C", "sol": "最右邊那條是一條沒有電阻的導線，直接把上下兩條匯流排短路，所有電阻兩端都沒有電位差。電流源的 6 A 全部由這條短路線流回，I = 6 A。"}, {"n": 22, "img": "115P1_22.webp", "ans": "C", "stem": "115P1_s22-23.webp", "sol": "求 Rth 要把電源歸零：電壓源短路、電流源開路。左邊剩 10 Ω、右邊剩 30 Ω，兩者串聯，Rth = 10 + 30 = 40 Ω。最大功率轉移時 RL = Rth = 40 Ω。"}, {"n": 23, "img": "115P1_23.webp", "ans": "B", "stem": "115P1_s22-23.webp", "sol": "拿掉 RL 求開路電壓：2 A 全部由 10 Ω 流過，左節點 = -60 - 2×10 = -80 V；右節點流入 2 + 1 = 3 A 經 30 Ω，為 90 V。|Vth| = 170 V。Pmax = Vth²/(4Rth) = 170²/160 ≈ 180.6 W。"}, {"n": 24, "img": "115P1_24.webp", "ans": "D", "sol": "j30 與 -j12 並聯 = (j30 × -j12)/(j30 - j12) = -j20。A2 讀值 = 120/20 = 6 A；15 Ω 分路電流 8 A。兩者相位差 90°，A1 = √(8² + 6²) = 10 A。"}, {"n": 25, "img": "115P1_25.webp", "ans": "C", "sol": "① 與整台串聯，是過熱時切斷電源的溫度保險絲。② 與氖燈並聯、③ 與 ④ 並聯：煮飯時彈跳開關 ③ 導通，把保溫片 ④ 短路，煮飯加熱片 ② 吃到全電壓；飯熟後 ③ 跳開，② 與 ④ 串聯降低功率變成保溫。"}, {"n": 26, "img": "115P1_26.webp", "ans": "A", "sol": "直流成分 4 V、交流有效值 3 V。總有效值 = √(4² + 3²) = 5 V，平均值就是直流成分 4 V。波形因數 = 有效值/平均值 = 5/4 = 1.25。"}, {"n": 27, "img": "115P1_27.webp", "ans": "C", "sol": "ω = 377 → f = 60 Hz。全波整流每個輸入週期輸出兩個脈波，所以輸出頻率 120 Hz。注意 110 是峰值不是有效值，全波平均值應為 2×110/π。"}, {"n": 28, "img": "115P1_28.webp", "ans": "A", "sol": "PNP 偏壓迴路：15.3 = IB×(RB + (β+1)RE) = IB×(690k + 100×0.75k) = IB×765k，IB = 20 μA。IC = 99 × 20μ = 1.98 mA，VC = -16 + 1.98 mA × 5 kΩ = -6.1 V。"}, {"n": 29, "img": "115P1_29.webp", "ans": "B", "stem": "115P1_s29-30.webp", "sol": "集極回授偏壓：20 - 0.7 = IB×(100×3k + 390k + 100×0.82k) = IB×772k，IB = 25 μA，IC = 2.475 mA。rπ = β·VT/IC = VT/IB = 26 mV / 25 μA ≈ 1.04 kΩ。"}, {"n": 30, "img": "115P1_30.webp", "ans": "C", "stem": "115P1_s29-30.webp", "sol": "射極接地，ib = vi/rπ。在集極節點列 KCL：(vi - vo)/RF = vo/RC + β·ib，整理後得 (1/RF + 1/RC)·vo = (1/RF - β/rπ)·vi。"}, {"n": 31, "img": "115P1_31.webp", "ans": "D", "sol": "dB = 20log(vo/vi)，只反映振幅比，不帶相位資訊。dB < 0 代表比值小於 1，也就是輸出振幅比輸入小（衰減）。dB = 0 是增益為 1，不是輸出為零。"}, {"n": 32, "img": "115P1_32.webp", "ans": "B", "sol": "增強型 MOSFET 沒有預置通道，VGS = 0 時不導通，必須讓 VGS 超過臨界電壓才會感應出通道；空乏型則相反，VGS = 0 就已經有通道。"}, {"n": 33, "img": "115P1_33.webp", "ans": "D", "sol": "VGS 由 VGG 決定為 -2 V。ID = IDSS(1 - VGS/VP)² = 10m × (1 - 0.5)² = 2.5 mA；gm = (2·IDSS/|VP|)(1 - VGS/VP) = 5m × 0.5 = 2.5 mA/V。共源極 Av = -gm·RD = -2.5m × 3k = -7.5。"}, {"n": 34, "img": "115P1_34.webp", "ans": "D", "sol": "MOSFET 閘極幾乎不取電流，輸入阻抗就由偏壓電阻決定：Ri = 240 kΩ ∥ 120 kΩ = 80 kΩ。"}, {"n": 35, "img": "115P1_35.webp", "ans": "A", "stem": "115P1_s35-36.webp", "sol": "飽和區 ID = K(VGS - Vt)²，微分後 gm = 2√(K·ID) = 2√(0.25 mA/V² × 1 mA) = 1 mA/V。"}, {"n": 36, "img": "115P1_36.webp", "ans": "C", "stem": "115P1_s35-36.webp", "sol": "由 1 mA = 0.25m(VGS - 1.5)² 得 VGS = 3.5 V；VS = 1 mA × 1.2 kΩ = 1.2 V，所以 VG = 4.7 V。由分壓 4.7 = 12 × 100k/(RG1 + 100k) 解得 RG1 ≈ 155.32 kΩ。"}, {"n": 37, "img": "115P1_37.webp", "ans": "D", "sol": "gm = 2√(K·ID)：gm1 = 2√(0.5m×2m) = 2 mA/V，gm2 = 2√(4m×4m) = 8 mA/V。第一級負載只有 3.3 kΩ（MOSFET 閘極不取電流），Av1 = -6.6；第二級 Av2 = -8m×1k = -8。總增益 = (-6.6)(-8) = 52.8。"}, {"n": 38, "img": "115P1_38.webp", "ans": "B", "sol": "下拉的 NMOS：A 與 B 串聯、C 單獨、D 與 E 串聯，三者並聯，所以 AB + C + DE 為 1 時輸出被拉低。Y = (AB + C + DE)' = (A' + B')·C'·(D' + E')。"}, {"n": 39, "img": "115P1_39.webp", "ans": "C", "stem": "115P1_s39-40.webp", "sol": "非反相施密特：切換時 V+ = 0，即 vi×(200k/300k) + vo×(100k/300k) = 0 → vi = -vo/2。vo = ∓15 V 對應臨界點 ±7.5 V，遲滯電壓 VH = 7.5 - (-7.5) = 15 V。"}, {"n": 40, "img": "115P1_40.webp", "ans": "D", "stem": "115P1_s39-40.webp", "sol": "沒有負回授的比較器，輸出只會在 ±15 V 之間跳，所以是方波。輸入 ω = 314 → f = 314/(2π) ≈ 50 Hz，輸出頻率與輸入相同。"}, {"n": 41, "img": "115P1_41.webp", "ans": "C", "sol": "CMRR = 20 log(Ad/Ac) = 20 log(2×10⁴ / 20) = 20 log(1000) = 60 dB。"}, {"n": 42, "img": "115P1_42.webp", "ans": "D", "sol": "DC 耦合會把直流與交流一起送進示波器，看到的是完整的信號（含直流準位）；AC 耦合才會擋掉直流。示波器量的是電壓，不是串聯量電流。"}, {"n": 43, "img": "115P1_43.webp", "ans": "C", "sol": "(a) 輸出與輸入反相且振幅放大 → 共射極；(b) 輸出與輸入同相且振幅放大 → 共基極。共集極（射極隨耦器）同相但增益約等於 1，不會放大。"}, {"n": 44, "img": "115P1_44.webp", "ans": "B", "sol": "負載電流 IL = 60 mW / 6 V = 10 mA；稽納最大電流 IZmax = 60 mW / 6 V = 10 mA。RS 最小時總電流最大 = 20 mA，RS(min) = (16 - 6) / 20 mA = 500 Ω。"}, {"n": 45, "img": "115P1_45.webp", "ans": "D", "sol": "VAB 是 100 kΩ 兩端電壓，IB = 2.5 V / 100 kΩ = 25 μA。IC = (12 - 6) / 3 kΩ = 2 mA。β = IC/IB = 2 mA / 25 μA = 80。"}, {"n": 46, "img": "115P1_46.webp", "ans": "C", "sol": "信號由源極進、汲極出，閘極用電容交流接地，是共閘極放大器，輸出與輸入同相。輸出又經耦合電容接 10 kΩ，直流被擋掉，所以波形要以 0 V 為中心且與 CH1 同相。"}, {"n": 47, "img": "115P1_47.webp", "ans": "A", "sol": "標準差動放大器：Vo = (Rf/R)(V+ - V-) = (Rf/R)(3 - 1)。由 8 = 2(Rf/R) 得 Rf/R = 4。"}, {"n": 48, "img": "115P1_48.webp", "ans": "A", "sol": "M1、M2 是串接在 VDD 與 Y 之間的 PMOS，M3、M4 是並接在 Y 與地之間的 NMOS，整體是 NOR 閘。A = B = 1 時兩個 PMOS 截止、兩個 NMOS 導通，輸出被拉到低準位。"}, {"n": 49, "img": "115P1_49.webp", "ans": "D", "sol": "韋恩電橋振盪器：f0 = 1/(2πRC) = 1/(2π × 5k × 0.02μ) ≈ 1.59 kHz。RC 網路在 f0 衰減為 1/3，放大器增益要等於 3，即 1 + Rf/Ri = 3，Rf = 2 × 2k = 4 kΩ。"}, {"n": 50, "img": "115P1_50.webp", "ans": "D", "sol": "OPA1 前的 R1、C1 是低通，截止頻率 1/(2πR1C1)；OPA2 前的 C2、R2 是高通，截止頻率 1/(2πR2C2)。低通串高通就是帶通濾波器，高頻截止頻率由 R1C1 決定。"}]});
EXAM.push({"code": "114P1", "y": 114, "p": "P1", "sub": "基本電學、基本電學實習、電子學、電子學實習", "items": [{"n": 1, "img": "114P1_1.webp", "ans": "B", "sol": "電鍋每日 1.2 kW × 4 h = 4.8 度，四個燈泡每日 0.4 kW × 10 h = 4 度，合計 8.8 度。30 天共 264 度，264 × 3 = 792 元。"}, {"n": 2, "img": "114P1_2.webp", "ans": "D", "sol": "原電阻 R = 120/12 = 10 Ω。均勻拉長為 2 倍時體積不變，截面積變成一半，R' = ρ(2L)/(A/2) = 4R = 40 Ω，所以 I = 120/40 = 3 A。拉長後電阻是 4 倍不是 2 倍，是這題的陷阱。"}, {"n": 3, "img": "114P1_3.webp", "ans": "A", "sol": "R1 消耗 36 W，I² × 4 = 36 得 I = 3 A，R1 上壓降 12 V。並聯段分到 117 - 12 = 105 V，等效電阻 105/3 = 35 Ω。由 70 ∥ R2 = 35 解得 R2 = 70 Ω。"}, {"n": 4, "img": "114P1_4.webp", "ans": "C", "sol": "用節點電壓法，設下方為 0 V、上方為 20 V，解得左中節點 7.2 V、右中節點 8.8 V。I 為電源送出的總電流 = (20-7.2)/12 + (20-8.8)/12 = 2 A。"}, {"n": 5, "img": "114P1_5.webp", "ans": "C", "sol": "設底線為 0 V，則 1 V 與 2 V 電源直接固定左、右節點電位。依 KCL 解得上方節點 4 V、中間節點 -3.5 V。再對右節點列 KCL：I + (4-2)/4 = (2+3.5)/2，得 I = 2.25 A。"}, {"n": 6, "img": "114P1_6.webp", "ans": "A", "sol": "對上方節點與左右兩個中間節點列 KCL，並注意 32 A 電流源的方向是由右往左。解聯立後得 2 Ω 上的電流為 30 A，V1 = 2 × 30 = 60 V。"}, {"n": 7, "img": "114P1_7.webp", "ans": "D", "sol": "拿掉 RL：Vth = 12 × R/(R+R) = 6 V，Rth = R ∥ R = R/2。Pmax = Vth²/(4Rth) = 36/(2R) = 18/R。令 18/R = 6 mW 得 R = 3 kΩ。"}, {"n": 8, "img": "114P1_8.webp", "ans": "B", "sol": "定電流充電：Q = I·t = 1 mA × 10 s = 10 mC。由 W = Q²/(2C) 得 C = Q²/(2W) = (0.01)²/(2×10) = 5 μF。"}, {"n": 9, "img": "114P1_9.webp", "ans": "D", "sol": "e2 = M·di/dt，M = 1 H。i 的斜率依序是 +4、-2、0、-2。但兩線圈的「點」在相對的兩端，所以感應電勢要變號，e2 依序為 -4、+2、0、+2 V。畫出來就是選項 (D)。"}, {"n": 10, "img": "114P1_10.webp", "ans": "C", "sol": "SW 打開後電源那一支被切斷，1 kΩ 一端懸空不通電流，放電只走 6 kΩ ∥ 3 kΩ = 2 kΩ。τ = RC = 2 kΩ × 10 μF = 20 ms。"}, {"n": 11, "img": "114P1_11.webp", "ans": "B", "stem": "114P1_s11-12.webp", "sol": "v1 在 ωt = -π/4 向上過零，v2 在 ωt = +π/4 向上過零，v1 比 v2 早了 π/2，也就是 v1 領先 v2 為 90 度。"}, {"n": 12, "img": "114P1_12.webp", "ans": "A", "stem": "114P1_s11-12.webp", "sol": "T = 10 ms 得 f = 100 Hz、ω = 200π。v1 = 10sin(ωt+45°)、v2 = 10sin(ωt-45°)，相加用和差化積得 2 × 10 × cos45° × sin(ωt) = 10√2 sin(200πt) V。"}, {"n": 13, "img": "114P1_13.webp", "ans": "A", "sol": "XL = ωL = 500 × 0.02 = 10 Ω。端電壓 50√2 sin(500t) 的有效值是 50 V，所以電流有效值 = 50/10 = 5 A。"}, {"n": 14, "img": "114P1_14.webp", "ans": "B", "sol": "j6 與 -j12 並聯 = (j6)(-j12)/(j6-j12) = 72/(-j6) = j12。從 a 到 b 依序是 20 Ω、j12 Ω、j8 Ω 串聯，Zab = 20 + j20 Ω。"}, {"n": 15, "img": "114P1_15.webp", "ans": "C", "sol": "兩支並聯：Z1 = 5 + j5，I1 = 100/(5+j5) = 10 - j10，P1 = 200×5 = 1000 W、Q1 = 1000 VAR；Z2 = 8 - j6，I2 = 8 + j6，P2 = 100×8 = 800 W、Q2 = -600 VAR。合計 Ps = 1800 W、Qs = 400 VAR。"}, {"n": 16, "img": "114P1_16.webp", "ans": "D", "stem": "114P1_s16-17.webp", "sol": "並聯諧振 ω0 = 1/√(LC)，所以 C = 1/(ω0²L) = 1/(2000² × 5 mH) = 1/20000 F = 50 μF。"}, {"n": 17, "img": "114P1_17.webp", "ans": "A", "stem": "114P1_s16-17.webp", "sol": "諧振時 L 與 C 互相抵消，電源電流全部流過 RP。is 峰值 5 A 對應有效值 5/√2 A，RP 兩端電壓 = (5/√2)×40 = 100√2 V。XL = ω0L = 2000 × 5 mH = 10 Ω，所以 iL 有效值 = 100√2/10 = 10√2 A。諧振時支路電流可以比總電流大很多。"}, {"n": 18, "img": "114P1_18.webp", "ans": "B", "sol": "Y 接時相電壓 = 線電壓/√3 = 200 V。總視在功率 S = √(15k² + 15k²) = 15√2 kVA，每相 5√2 kVA。|Z| = 200²/(5√2 k) = 4√2 Ω，P 與 Q 相等代表角度 45°，所以 Z = 4 + j4 Ω。"}, {"n": 19, "img": "114P1_19.webp", "ans": "B", "sol": "變壓器、發電機、配電盤帶電，屬於 C 類（電氣）火災，要用二氧化碳或乾粉，不能灑水。A 類是普通可燃物、B 類是油類、D 類是活性金屬。"}, {"n": 20, "img": "114P1_20.webp", "ans": "C", "sol": "R1 的色環橙白黑金 = 390 × 0.1 = 39 Ω。總電阻 90 Ω 時 R2 = 51 Ω。綠棕黑金 = 510 × 0.1 = 51 Ω，所以選綠棕黑金紫。五環電阻第四環是倍數，金色代表 ×0.1。"}, {"n": 21, "img": "114P1_21.webp", "ans": "A", "sol": "設底線為 0 V。對 24 V 電源兩端做超節點配合 KCL，可解出兩個中間節點分別是 48 V 與 24 V，上方節點也是 48 V。4 Ω 兩端等電位，所以 I = 0 A。"}, {"n": 22, "img": "114P1_22.webp", "ans": "C", "sol": "104K 的 104 代表 10 × 10⁴ pF = 100 nF，K 代表誤差 ±10%，合理範圍是 90～110 nF。只有 96 nF 落在範圍內。"}, {"n": 23, "img": "114P1_23.webp", "ans": "A", "sol": "t = 0+ 時電感相當於開路，電流走兩個 R，節點電壓 = E/2，所以 vL(0+) = E/2。τ 時 vL = (E/2)(0.368) = 0.184E，vR = E - 0.184E = 0.816E。另外 iL(τ) = (E/R)(0.632)、i1(τ) = 0.184E/R，都與選項不符。"}, {"n": 24, "img": "114P1_24.webp", "ans": "A", "sol": "串聯總阻抗 Z = 16 + j16 - j4 = 16 + j12，|Z| = 20 Ω。I = 200/20 = 10 A。V2 = 10 × 16 = 160 V，V3 = 10 × |j12| = 120 V。注意交流電壓表讀的是大小，三個讀值不會直接相加。"}, {"n": 25, "img": "114P1_25.webp", "ans": "D", "sol": "③ 與電源串聯，是過熱就切斷全機的溫度開關；② 直接跨在交流電源上，是電熱線；① 接在二極體橋式整流的直流側，是直流風扇馬達。"}, {"n": 26, "img": "114P1_26.webp", "ans": "B", "sol": "N 型半導體是摻五價元素，多數載子為電子，整體仍是電中性。摻砷（五價）得到 N 型、摻三價得到 P 型，P 型整體也是電中性，所以其他三個選項都錯。"}, {"n": 27, "img": "114P1_27.webp", "ans": "C", "sol": "全波整流輸出：有效值 = Vm/√2，平均值 = 2Vm/π。波形因數 = 有效值/平均值 = (Vm/√2)/(2Vm/π) = π/(2√2) ≈ 1.11。"}, {"n": 28, "img": "114P1_28.webp", "ans": "D", "sol": "LED 在順向偏壓下，電子與電洞復合釋出能量而發光。發光顏色由材料能隙決定不是工作電壓；空乏區電位差叫障壁電位；溫度升高時逆向飽和電流會增加。"}, {"n": 29, "img": "114P1_29.webp", "ans": "A", "stem": "114P1_s29-30.webp", "sol": "先求偏壓：12 - 0.7 = IB × (305k + 100 × 2.6k) = IB × 565k，IB = 20 μA，IE = 2 mA，re = 26 mV/2 mA = 13 Ω。射極隨耦器的輸出阻抗 Zo = RE ∥ re = 2.6k ∥ 13 ≈ 12.9 Ω。"}, {"n": 30, "img": "114P1_30.webp", "ans": "C", "stem": "114P1_s29-30.webp", "sol": "輸出取在射極，是共集極（射極隨耦器）。電壓增益 = RE/(re + RE)，略小於 1。分母用的是射極端看到的 re，不是基極端的 rπ。"}, {"n": 31, "img": "114P1_31.webp", "ans": "D", "sol": "N 通道 MOSFET 是在 P 型基體上做出 N 型通道。D-MOSFET 有預置通道，VGS = 0 就會導通；P 通道 E-MOSFET 要加負電壓；E-MOSFET 只要 VGS 回到 0 就關閉，不必加逆偏。"}, {"n": 32, "img": "114P1_32.webp", "ans": "A", "sol": "由 ID/IDSS = 1.44/9 = 0.16 得 (1 - VGS/Vp) = 0.4，VGS = -1.8 V。VS = 1.44 mA × 2 kΩ = 2.88 V，VG = -1.8 + 2.88 = 1.08 V。由分壓 12 × 20k/(RG1+20k) = 1.08 解得 RG1 ≈ 202.2 kΩ。"}, {"n": 33, "img": "114P1_33.webp", "ans": "B", "sol": "gm = (2·IDSS/|Vp|)(1 - VGS/Vp) = (2×10m/4)(1 - (-3)/(-4)) = 5m × 0.25 = 1.25 mA/V。"}, {"n": 34, "img": "114P1_34.webp", "ans": "A", "stem": "114P1_s34-35.webp", "sol": "飽和區 ID = K(VGS - Vt)²，微分得 gm = 2√(K·ID) = 2√(0.3m × 1.2m) = 1.2 mA/V。"}, {"n": 35, "img": "114P1_35.webp", "ans": "C", "stem": "114P1_s34-35.webp", "sol": "由 1.2m = 0.3m(VGS-2)² 得 VGS = 4 V；VS = 1.2 mA × 1 kΩ = 1.2 V，VG = 5.2 V。由 15.6 × 50k/(RG1+50k) = 5.2 得 RG1 = 100 kΩ。Zi = RG1 ∥ 50k = 33.3 kΩ。"}, {"n": 36, "img": "114P1_36.webp", "ans": "C", "sol": "非反相端是多輸入的加權平均：Σ(V/R) = 20/20 + 20/20 + 10/10 + 5/5 = 4，Σ(1/R) = 1/20+1/20+1/10+1/5 = 0.4，V+ = 10 mV。非反相放大倍率 = 1 + 20k/10k = 3，Vo = 30 mV。"}, {"n": 37, "img": "114P1_37.webp", "ans": "D", "sol": "下拉的 NMOS：C 與 D 串聯，再與 A、B 並聯，所以 A + B + CD 為 1 時輸出被拉低。Y = (A + B + CD)' = A'B'(C' + D')。"}, {"n": 38, "img": "114P1_38.webp", "ans": "C", "stem": "114P1_s38-39.webp", "sol": "考畢子（Colpitts）振盪器：C1、C2 分壓的回授比 = C2/C1 = 150/300 = 0.5，放大器增益要等於 1/0.5 = 2，所以 Rf = 2 × Ri = 100 kΩ。"}, {"n": 39, "img": "114P1_39.webp", "ans": "C", "stem": "114P1_s38-39.webp", "sol": "等效電容 Ceq = C1C2/(C1+C2) = 300×150/450 = 100 pF。f0 = 1/(2π√(LC)) = 1/(2π√(100 μH × 100 pF)) ≈ 1.59 MHz。"}, {"n": 40, "img": "114P1_40.webp", "ans": "D", "sol": "峰對峰佔 4 格 × 2 V/格 = 8 V；一個完整週期佔 4 格 × 1 ms/格 = 4 ms，f = 1/4 ms = 250 Hz。衰減比 1:1 所以讀值不必再換算。"}, {"n": 41, "img": "114P1_41.webp", "ans": "D", "sol": "指針式電表的黑測棒接內部電池正極。黑棒固定、紅棒碰另外兩腳都量到低電阻，代表電流由黑棒那一腳流入、另外兩腳流出，共用腳是 P 型基極，元件為 NPN。"}, {"n": 42, "img": "114P1_42.webp", "ans": "A", "sol": "二次側每半邊峰值 = 110√2/11 = 10√2 V。負載平均電壓 = 2Vm/π，平均電流 = 2(10√2)/(10π) = 2√2/π A。全波中每顆二極體只導通一半時間，所以 iD 平均值是負載的一半 = √2/π A。"}, {"n": 43, "img": "114P1_43.webp", "ans": "D", "sol": "固定偏壓：IB = (12 - 0.7)/452k = 25 μA，不隨 β 改變。β = 100 時 IC = 2.5 mA，VC = 12 - 2.5 mA × 3 kΩ = 4.5 V。固定偏壓的工作點會跟著 β 跑，這就是它不穩定的原因。"}, {"n": 44, "img": "114P1_44.webp", "ans": "B", "stem": "114P1_s44-45.webp", "sol": "SW 切在 b 時 vo1 接到 Q2 的基極，直流準位被抬到 VB2 ≈ 6.7 V，示波器又設在 DC 耦合，所以波形會整個浮在 0 V 以上。Q1 是共射極會反相，CH1 先往上時 vo1 要先往下，符合的是 (B)。"}, {"n": 45, "img": "114P1_45.webp", "ans": "B", "stem": "114P1_s44-45.webp", "sol": "Q2 是射極隨耦器：VCE = 6 V 得 VE = 6 V，IE = 6 V/1 kΩ = 6 mA，IB = 6 mA/81 ≈ 74 μA，VB = 6.7 V。20 kΩ 上的電流 = 6.7/20k = 335 μA，所以 RB2 的電流 = 335 + 74 = 409 μA，RB2 = (12-6.7)/409 μA ≈ 12.96 kΩ。"}, {"n": 46, "img": "114P1_46.webp", "ans": "B", "sol": "gm1 = 2√(0.5m×0.5m) = 1 mA/V，第一級共源極 Av1 = -gm1 × 15k = -15。gm2 = 2√(0.5m×2m) = 2 mA/V，第二級輸出取在源極是源極隨耦器，負載 2k ∥ 2k = 1k，Av2 = gm2·R/(1+gm2·R) = 2/3。總增益 = -15 × 2/3 = -10。"}, {"n": 47, "img": "114P1_47.webp", "ans": "A", "sol": "沒有回授，是比較器。反相端 V- = (Vi/8k + 3/4k)/(1/8k + 1/4k) = (Vi+6)/3。輸出為 +15 V 需要 V+ > V-，即 (Vi+6)/3 < 0，Vi < -6 V，只有 -8 V 符合。"}, {"n": 48, "img": "114P1_48.webp", "ans": "B", "sol": "OPA1 是施密特觸發器產生方波，OPA2 是積分器把方波變三角波再回授。這種方波三角波產生器 f = R2/(4·R1·R3·C) = 60k/(4 × 20k × 9k × 0.1μ) ≈ 833 Hz。"}, {"n": 49, "img": "114P1_49.webp", "ans": "D", "sol": "R 串聯、C 對地，再接電壓隨耦器，是一階低通濾波器，截止頻率 f = 1/(2πRC)。高通要把 R 與 C 對調。"}, {"n": 50, "img": "114P1_50.webp", "ans": "B", "sol": "由波形讀真值表：只有 A、B 同時為 0 時 Y 才是 0，其餘都是 1，所以是 OR 閘。CMOS 做 OR 要先做 NOR（PMOS 串聯、NMOS 並聯）再串一級反相器，符合的是 (B)。"}]});
EXAM.push({"code": "113P1", "y": 113, "p": "P1", "sub": "基本電學、基本電學實習、電子學、電子學實習", "items": [{"n": 1, "img": "113P1_1.webp", "ans": "B", "sol": "作功 W = Q × 電位差。由 c 到 b：-20 = Q(Vc - Vb) = Q(20 - 10) = 10Q，得 Q = -2 C。由 a 到 b：64 = Q(Va - Vb) = -2(Va - 10)，得 Va - 10 = -32，Va = -22 V。所以 Vca = Vc - Va = 20 - (-22) = 42 V。"}, {"n": 2, "img": "113P1_2.webp", "ans": "A", "sol": "線性關係，每 1 度的變化量 = (11 - 10)/(40 - 20) = 0.05 Ω/度。從 20 度到 80 度差 60 度，R = 10 + 0.05 × 60 = 13 Ω。"}, {"n": 3, "img": "113P1_3.webp", "ans": "C", "sol": "以最下方的導線為 0 V。左下 2 V 電源下方為正，所以左節點 = -2 V；中下 2 V 電源上方為正，所以中節點 = +2 V。上方 1 V 電源上方為正，上排導線 = -2 + 1 = -1 V。右邊 3 V 電源下方為正，右節點 = -1 + 3 = +2 V。Va 的 - 在左(中節點)、+ 在右(右節點)，Va = 2 - 2 = 0 V。中間那個 3 Ω 其實沒有電流。"}, {"n": 4, "img": "113P1_4.webp", "ans": "C", "sol": "設底線 0 V、節點 A(1 Ω 右端)、B(中間)、D(最右)。列三個節點的 KCL 解得 VA = 8 V、VB = VD = 4 V。因為 B、D 等電位，B-D 間的 4 Ω 沒有電流。I = (10 - 8)/1 = 2 A。"}, {"n": 5, "img": "113P1_5.webp", "ans": "B", "sol": "三個電阻並聯，電壓相同，所以電流和電阻成反比：I1 : I2 : I3 = 1/6 : 1/10 : 1/R。已知 1/6 : 1/10 = 5 : 3 成立，再由 (1/R)/(1/6) = 2/5 得 1/R = 1/15，R = 15 Ω。"}, {"n": 6, "img": "113P1_6.webp", "ans": "C", "sol": "設底線 0 V。4 V 電源上方為正，所以它上端節點 Q = 4 V。對上方節點 T 列 KCL：2 + (4 - VT)/3 = VT/6，得 VT = 20/3 V。對 2 A 電源上端節點 P 列 KCL：(4 - VP)/6 + (0 - VP)/3 = 2，得 VP = -8/3 V。再對 Q 列 KCL，流入電源的電流 = -2/9 A，表示實際上有 2/9 A 由電源的 + 端流出，電源在供給功率：P = 4 × 2/9 = 0.89 W，供給。"}, {"n": 7, "img": "113P1_7.webp", "ans": "B", "sol": "設底線 0 V，三個節點 X(左)、M(中)、Y(右)。上方 4 A 由 Y 流向 X，中間 2 A 由 M 流向地，右支路是 2 Ω 串 4 V。列 KCL 解得 VX = 4 V、VM = -4 V、VY = -4 V。I = (VM - VY)/4 = 0/4 = 0 A。"}, {"n": 8, "img": "113P1_8.webp", "ans": "C", "sol": "開路時 2 A 一定流過 6 Ω 再經上方導線流下 3 Ω，最後經 12 V 回來。由 b 往上：先經 12 V 升 12 V，再經 3 Ω，電流由上往下所以上端高 2 × 3 = 6 V，Vth = 12 + 6 = 18 V。求 Rth 時電流源開路(6 Ω 那支就斷了)、電壓源短路，a、b 間只剩 3 Ω，Rth = 3 Ω。"}, {"n": 9, "img": "113P1_9.webp", "ans": "A", "sol": "電流由 a 流進，L1 由黑點端進(同名端)、L2 由非黑點端進、L3 由黑點端進。所以 M12 相消、M23 相消、M31 相助：Leq = 4 + 6 + 8 + 2(-3 - 5 + 4) = 18 - 8 = 10 H。W = (1/2)L I^2 = 0.5 × 10 × 2^2 = 20 J。"}, {"n": 10, "img": "113P1_10.webp", "ans": "D", "sol": "t < 0 穩態時電感視為短路，右半邊被短路掉沒有電流，電感電流 = 12/2 = 6 A，方向由上往下。t = 0 切離後電感電流不能突變，仍是 6 A 往下，只能由右邊網路補上，也就是 6 A 從 Q 流向 P。右邊 6 Ω 與 (3 + 9 = 12 Ω) 並聯，12 Ω 這支分到 6 × 6/(6 + 12) = 2 A，而且是由下往上流過 9 Ω。VR 的 + 在上，電流卻由下往上，所以 VR = -(2 × 9) = -18 V。"}, {"n": 11, "img": "113P1_11.webp", "ans": "B", "sol": "先把兩式化成同一個 sin。i(t) = -5cos(100t + 30度) = 5sin(100t - 60度)。電壓相角 -30 度、電流相角 -60 度，電壓超前電流 30 度。"}, {"n": 12, "img": "113P1_12.webp", "ans": "A", "sol": "方波平均值 = 面積 / 週期 = E × TON/(TON + TOFF) = 15 × 3/(3 + 2) = 9 V。"}, {"n": 13, "img": "113P1_13.webp", "ans": "D", "sol": "右邊那支是 j5 Ω 串 -j5 Ω，總和為 0，等於把 b、c 短路，所以 Vbc = 0 V，中間 3 - j4 那支被短路掉。電源只看到 4 Ω：I1 = 12/4 = 3∠0度 A，Vab = 3 × 4 = 12∠0度 V。下方 I2 的箭頭朝右，和實際回流方向相反，所以 I2 = 3∠180度 A。(D) 兩個敘述都對。"}, {"n": 14, "img": "113P1_14.webp", "ans": "C", "sol": "XL 和頻率成正比、XC 和頻率成反比。設所求頻率 f：XL = 160 × (f/240)、XC = 40 × (240/f)。串聯諧振時電流最大，令兩者相等：160f/240 = 9600/f，f^2 = 14400，f = 120 Hz。"}, {"n": 15, "img": "113P1_15.webp", "ans": "B", "sol": "並聯 RLC 的 BW = 1/(2πRC)，由 250/π = 1/(2π × 200 × C) 得 C = 10 μF，(D) 錯。f0 = 1/(2π√(LC)) = 1/(2π√(1m × 10μ)) = 5000/π Hz，(A) 錯。Q = f0/BW = (5000/π)/(250/π) = 20，(B) 對。f2 = f0 + BW/2 = 5125/π ≈ 1631 Hz，(C) 錯。"}, {"n": 16, "img": "113P1_16.webp", "ans": "A", "sol": "三角形負載每相阻抗 3 + j4 = 5∠53度 Ω。電流表量的是線電流 8.66 A，三角形接法 I相 = 8.66/√3 = 5 A，相電壓(即線電壓) = 5 × 5 = 25 V。總視在功率 S = 3 × 25 × 5 = 375 VA，P = 375 × 0.6 = 225 W、Q = 375 × 0.8 = 300 VAR。電壓表跨在負載一相兩端，讀 25 V。只有 (A) 正確。"}, {"n": 17, "img": "113P1_17.webp", "ans": "C", "stem": "113P1_s17-18.webp", "sol": "電流表是理想的，視同短路。-j4 與 j8 並聯：(-j4)(j8)/(-j4 + j8) = 32/(j4) = -j8 Ω。總阻抗 Z = 3 + j10 + (-j8) = 3 + j2 Ω。"}, {"n": 18, "img": "113P1_18.webp", "ans": "B", "stem": "113P1_s17-18.webp", "sol": "分流：流過 -j4 的電流 = 總電流 × j8/(-j4 + j8) = 2 倍總電流。電流表讀 4 A，所以總電流 = 2 A。P = 2^2 × 3 = 12 W、Q = 2^2 × 2 = 8 VAR、S = 4 × √13 ≈ 14.4 VA、PF = 3/√13 ≈ 0.83 落後(電路呈電感性)。只有 (B) 正確。"}, {"n": 19, "img": "113P1_19.webp", "ans": "C", "sol": "五環色碼「紅綠黑黑棕」= 2、5、0，乘數 10^0，誤差 ±1%，所以 R = 250 Ω ±1%。功率最大發生在電阻最小時：R = 250 × 0.99 = 247.5 Ω，P = 5^2/247.5 ≈ 0.101 W，約 0.1 W。"}, {"n": 20, "img": "113P1_20.webp", "ans": "D", "sol": "把 4 V 電源和它兩端的節點看成超節點。左節點 Va、右節點 Va + 4。KCL：4(流入 4 A 電源) + Va/4 + (Va + 4)/4 = 10，整理得 2Va + 4 = 24，Va = 10 V。驗算：右節點 14 V，2 Ω 由右流向左 2 A，左節點 KCL 得 I = 4.5 A，與題目相符。"}, {"n": 21, "img": "113P1_21.webp", "ans": "D", "sol": "v(t) = 6sin(157t)，ω = 157，f = 157/(2π) ≈ 25 Hz，T = 40 ms，振幅 6 V。由圖上量：一個完整週期佔 8 格，所以 40 ms / 8 = 5 ms/DIV；峰值離 0 V 線 3 格，所以 6 V / 3 = 2 V/DIV。探棒 1:1 不需換算。"}, {"n": 22, "img": "113P1_22.webp", "ans": "B", "stem": "113P1_s22-23.webp", "sol": "拆開看：a 經 3 μF 到上節點 P；P 到 d 有兩條路，一條是 (4 μF 並 2 μF = 6 μF) 串 6 μF = 3 μF，另一條是 9 μF，兩者並聯 = 12 μF；d 再經 12 μF 到 b。三者串聯：1/C = 1/3 + 1/12 + 1/12 = 1/2，C = 2 μF。"}, {"n": 23, "img": "113P1_23.webp", "ans": "A", "stem": "113P1_s22-23.webp", "sol": "總電容 2 μF，總電荷 Q = 2 μF × 24 V = 48 μC。串聯各段電荷相同：3 μF 分到 48/3 = 16 V，P 到 d 的 12 μF 分到 48/12 = 4 V，12 μF 分到 4 V。再看 P 到 d 的 3 μF 那條支路，兩端也是 4 V，電荷 = 3 μF × 4 V = 12 μC，所以 c、d 間 6 μF 的電壓 = 12/6 = 2 V。"}, {"n": 24, "img": "113P1_24.webp", "ans": "D", "sol": "並聯 RL：iR 與 vs 同相(電阻不移相)，iL 落後 vs 90 度。所以 vs 到峰值時 iL 剛好過零往上，vs 過零往下時 iL 才到峰值。(D) 的 iR 與 vs 同時到峰值、iL 的峰值正好落在 vs 的下降零交越點，符合。(B) 的 iL 峰值出現在 vs 之前(超前 90 度)，那是電容的行為；(A)、(C) 畫的是 is，相位也不對。"}, {"n": 25, "img": "113P1_25.webp", "ans": "A", "sol": "指示燈只是並聯在加熱回路上的指示元件。若只是指示燈接線脫落，加熱線圈照樣通電煮飯，不會造成不加熱，所以 (A) 不是原因。開關接觸不良、電源線斷線、插頭接觸不良都會讓整個回路不通，燈不亮也不加熱。"}, {"n": 26, "img": "113P1_26.webp", "ans": "A", "sol": "二次側 110:12，有效值 12 V，峰值 Vm = 12√2 V。橋式(四顆二極體)是全波整流，平均值 = 2Vm/π = 24√2/π V。橋式整流每顆二極體承受的 PIV = Vm = 12√2 V。"}, {"n": 27, "img": "113P1_27.webp", "ans": "B", "sol": "PNP 在主動區：射極-基極必須順向偏壓，PNP 的射極是 P、基極是 N，所以 VE > VB；集極-基極必須逆向偏壓，所以 VB > VC。合起來 VE > VB > VC。"}, {"n": 28, "img": "113P1_28.webp", "ans": "D", "sol": "若在主動區，IC 應等於 β × IB = 150 × 1 mA = 150 mA。實際 IC 只有 120 mA，比 β IB 小，表示集極電流已被外部電路限制住，電晶體進入飽和區。"}, {"n": 29, "img": "113P1_29.webp", "ans": "A", "sol": "基極戴維寧：Vth = -12 + 24 × 50/(450 + 50) = -9.6 V，Rth = 450k 並 50k = 45 kΩ。列基極迴路：-9.6 = IB × 45k + 0.7 + (β + 1)IB × 1k - 12，即 1.7 = IB × 100k，IB = 17 μA。IC = 54 × 17 μ ≈ 0.918 mA。VC = 12 - 0.918m × 5k ≈ 7.4 V。"}, {"n": 30, "img": "113P1_30.webp", "ans": "D", "sol": "C3 把 RF1 與 RF2 的接點交流接地。所以交流上 RF2 是從地接到集極，等於和 RC 並聯；RF1 只是對訊號源的負載，不影響增益。gm = β/rπ = 100/1k = 100 mA/V。Av = -gm × (RC 並 RF2) = -0.1 × (3k 並 68k) = -0.1 × 2873 ≈ -287。"}, {"n": 31, "img": "113P1_31.webp", "ans": "D", "sol": "(A) dB 為負只代表增益小於 1，和反相與否無關。(B) 電流增益 0 dB 只表示大小為 1，相位不一定相同。(C) 串級時各級 dB 要相加不是相乘。(D) 增益 dB 為負表示增益小於 1，輸出振幅確實小於輸入，正確。"}, {"n": 32, "img": "113P1_32.webp", "ans": "A", "sol": "(A) P 通道 MOSFET 的汲極與源極都是 P 型擴散區，正確。(B) N 通道的源極也應是 N 型。(C) 預置通道、閘極不加電壓就導通的是空乏型，不是增強型。(D) FET 只靠一種載子導電，是單載子元件。"}, {"n": 33, "img": "113P1_33.webp", "ans": "D", "sol": "這是共閘極組態。由源極看進去的輸入電阻 = 1/gm = 1/4m = 250 Ω，和 RS = 1 kΩ 並聯分流：進入源極的電流 is = ii × 1000/(1000 + 250) = 0.8 ii。汲極電流 id = is。到了汲極，電流再被 RD = 2 kΩ 與 10 kΩ 負載分流：io = 0.8 ii × 2/(2 + 10) = 0.133 ii。Ai ≈ 0.13。"}, {"n": 34, "img": "113P1_34.webp", "ans": "A", "sol": "M2 的閘極接到 VDD 也就是自己的汲極，屬二極體接法，交流上等效電阻 = 1/gm2。先求偏壓：M1 的 VGS1 = 5 V(閘極經 RG 接 5 V，無閘流)，ID = K1(5 - 3)^2 = 4m × 4 = 16 mA。M2 流同樣的 16 mA：16m = 1m × (VGS2 - 2.5)^2，得 VGS2 - 2.5 = 4。gm1 = 2K1(5 - 3) = 16 mA/V，gm2 = 2K2 × 4 = 8 mA/V，1/gm2 = 125 Ω。Av = -gm1 × (125 並 10k) = -16m × 123.5 ≈ -1.98。"}, {"n": 35, "img": "113P1_35.webp", "ans": "C", "stem": "113P1_s35-36.webp", "sol": "要 VDS = 7.5 V：7.5 = 15 - ID(2k + 1k)，ID = 2.5 mA。代蕭克萊公式 ID = IDSS(1 - VGS/Vp)^2：2.5 = 10(1 + VGS/3)^2，(1 + VGS/3)^2 = 0.25，取合理根 VGS = -1.5 V。VG = VS + VGS = 2.5m × 1k - 1.5 = 1 V。分壓：15 × RG/(210k + RG) = 1，得 RG = 15 kΩ。"}, {"n": 36, "img": "113P1_36.webp", "ans": "A", "stem": "113P1_s35-36.webp", "sol": "gm0 = 2 IDSS/|Vp| = 20/3 ≈ 6.67 mA/V，gm = gm0(1 - VGS/Vp) = 6.67 × (1 - 0.5) = 3.33 mA/V。源極電阻 1 kΩ 沒有旁路電容，要列入負回授：Av = -gm(RD 並 RL)/(1 + gm RS) = -(3.33m × (2k 並 10k))/(1 + 3.33m × 1k) = -5.56/4.33 ≈ -1.28。"}, {"n": 37, "img": "113P1_37.webp", "ans": "A", "sol": "先看下拉的 NMOS 網路：A 串 B 一組、C 串 D 一組，兩組並聯後再串 E 到地，所以導通條件(Y = 0)是 (AB + CD)E 成立。取補數即得 Y = (A反 + B反)(C反 + D反) + E反。上拉的 PMOS 網路也是這個結果：A 並 B 串 C 並 D，再整組和 E 並聯。"}, {"n": 38, "img": "113P1_38.webp", "ans": "C", "sol": "理想 OPA 虛短，- 端電位 = vi。設 - 端為 N1、中間為 N2、輸出端為 N3。N1 對地 R 的電流 = vi/R，必須由 N2 經 R 供給：(VN2 - vi)/R = vi/R，VN2 = 2vi。再對 N2 列 KCL：(vo - 2vi)/2R = 2vi/R + vi/R = 3vi/R，得 vo - 2vi = 6vi，vo = 8vi，Av = 8。"}, {"n": 39, "img": "113P1_39.webp", "ans": "A", "sol": "先算 + 端。對 + 端列 KCL：(2 - v)/20 + (1 - v)/10 - v/20 = 0，得 v = 1 V，所以 V- 也是 1 V。再對 - 端列 KCL：(-3 - 1)/30 + (-2 - 1)/20 + (2 - 1)/10 + (Vo - 1)/60 = 0，乘 60 得 -8 - 9 + 6 + Vo - 1 = 0，Vo = 12 V。"}, {"n": 40, "img": "113P1_40.webp", "ans": "C", "stem": "113P1_s40-41.webp", "sol": "輸入接在 - 端，屬反相型施密特。+ 端電位 = (VR × 18 + vo × 2)/20 = 0.9VR + 0.1vo。VR = 1 V 時：vo = +15 V 得門檻 0.9 + 1.5 = 2.4 V；vo = -15 V 得門檻 0.9 - 1.5 = -0.6 V。所以 VU = 2.4 V、VL = -0.6 V。"}, {"n": 41, "img": "113P1_41.webp", "ans": "C", "stem": "113P1_s40-41.webp", "sol": "VR = 0 時兩個門檻為 ±1.5 V。輸入振幅 3 V 一定會同時越過上、下兩個門檻，輸出就在 +15 V 與 -15 V 之間來回跳，得到方波。"}, {"n": 42, "img": "113P1_42.webp", "ans": "B", "sol": "叫叫 CABD 中：C 是 Compression 胸部按壓、A 是 Airway 暢通呼吸道、B 是 Breathing 人工呼吸、D 是 Defibrillation，也就是使用 AED 自動體外心臟電擊去顫器電擊。"}, {"n": 43, "img": "113P1_43.webp", "ans": "D", "sol": "(A) 全波整流的漣波頻率是輸入的兩倍。(B) vs 峰值愈大，輸出電壓愈高，漣波電壓也跟著變大。(C) RL 愈大代表負載電流愈小，電容放電愈慢，漣波反而愈小。(D) C 愈大時間常數愈大、放電愈慢，漣波愈小，正確。"}, {"n": 44, "img": "113P1_44.webp", "ans": "D", "sol": "負載電流固定 IL = 10 V/1 kΩ = 10 mA。稽納最大電流 IZmax = 150 mW/10 V = 15 mA。R 上的電壓固定 = 16 - 10 = 6 V。R 最小時電流最大：IR = 15 + 10 = 25 mA，Rmin = 6/25m = 240 Ω。R 最大時稽納只剩膝點電流：IR = 2 + 10 = 12 mA，Rmax = 6/12m = 500 Ω。"}, {"n": 45, "img": "113P1_45.webp", "ans": "D", "sol": "共基極組態。基極接地，所以 VE = -0.7 V。射極支路：IE = (VE - (-VEE))/8k = 1.3 mA，得 VEE - 0.7 = 10.4，VEE = 11.1 V。re = VT/IE = 26m/1.3m = 20 Ω，α = 199/200 = 0.995。共基極的 Av = α(RC 並 RL)/re = 0.995 × (6k 並 6k)/20 = 0.995 × 150 ≈ 149。"}, {"n": 46, "img": "113P1_46.webp", "ans": "C", "sol": "N 通道增強型要在飽和區，必須同時滿足 VGS > Vt 且 VDS ≥ VGS - Vt。(A) 過驅電壓 2.5 V > VDS 1 V，在線性區。(B) 1.5 V > 1.2 V，線性區。(C) 過驅 0.5 V，VDS 1.5 V ≥ 0.5 V，在飽和區，正確。(D) VGS 2 V < Vt 2.5 V，截止。"}, {"n": 47, "img": "113P1_47.webp", "ans": "B", "sol": "由汲極電阻推電流：ID = (VDD - VD)/RD = (12 - 6)/1.2k = 5 mA。VGS = VG = 2.5 V，過驅電壓 = 2.5 - 2 = 0.5 V，VDS = 6 V 遠大於 0.5 V，確實在飽和區。ID = K(VGS - Vt)^2：5m = K × 0.5^2，K = 20 mA/V^2。"}, {"n": 48, "img": "113P1_48.webp", "ans": "C", "sol": "前級 RA、CA 是低通，決定上截止頻率：fH = 1/(2π RA CA) = 1/(2 × 3.14 × 500 × 0.01μ) ≈ 31.85 kHz。後級 CB、RB 是高通，決定下截止頻率：fL = 1/(2π RB CB) = 1/(2 × 3.14 × 1k × 0.05μ) ≈ 3.18 kHz。BW = 31.85 - 3.18 ≈ 28.66 kHz。"}, {"n": 49, "img": "113P1_49.webp", "ans": "B", "sol": "這是方波振盪器(無穩態多諧振盪器)。回授比 β = R2/(R1 + R2) = 8.5/18.5 ≈ 0.46。週期 T = 2RC × ln((1 + β)/(1 - β))，(1 + 0.46)/(1 - 0.46) ≈ 2.7，題目給 ln2.7 ≈ 1。T = 2 × 50k × 0.2μ × 1 = 0.02 s，f = 1/0.02 = 50 Hz。"}, {"n": 50, "img": "113P1_50.webp", "ans": "A", "sol": "三節 RC 相移振盪器。振盪頻率 f = 1/(2πRC√6) = 1/(2 × 3.14 × 10k × 0.01μ × 2.45) = 1/(1.539m) ≈ 650 Hz。要起振，反相放大器的增益必須大於等於 29，也就是 R2 ≥ 29 R1 = 29 × 20k = 580 kΩ，選項中只有 581 kΩ 滿足。"}]});
EXAM.push({"code": "112P1", "y": 112, "p": "P1", "sub": "基本電學、基本電學實習、電子學、電子學實習", "items": [{"n": 1, "img": "112P1_1.webp", "ans": "B", "sol": "把正電荷由 b 移到 a 所作的功 W = q(Va - Vb)。代入 0.1 = 2 × 10^-3 × (60 - Vb)，得 60 - Vb = 50，Vb = 10 V。(作正功表示 a 點電位比 b 點高。)"}, {"n": 2, "img": "112P1_2.webp", "ans": "A", "sol": "R = ρ l / A。a 的長度是 2 倍會讓電阻變 2 倍、截面積是 4 倍會讓電阻變 1/4 倍，合起來 Ra = (2/4) Rb = 0.5 Rb，所以 Ra : Rb = 1 : 2。"}, {"n": 3, "img": "112P1_3.webp", "ans": "D", "sol": "以 n 為 0 V。b 到 n 的 3 V 電源下方為正，所以 Vb = -3 V。再由各電源推：Va = Vb - 1 = -4 V(a-b 間 1 V 電源上方為負)、Vc = Vb + 2 = -1 V、Vd = Vb - 4 = -7 V。於是 Vac = -4 - (-1) = -3 V、Vad = -4 - (-7) = 3 V、Vcn = -1 V、Vdn = -7 V。比較後只有 Vad > Vac 成立。"}, {"n": 4, "img": "112P1_4.webp", "ans": "C", "sol": "V2 = E × R2/(R1 + R2)。由 R2 = 2 時 V2 = 10、R2 = 8 時 V2 = 16 列兩式：2E = 10(R1 + 2)、8E = 16(R1 + 8)，解得 R1 = 2 Ω、E = 20 V。代回 R2 = 18：V2 = 20 × 18/(2 + 18) = 18 V。"}, {"n": 5, "img": "112P1_5.webp", "ans": "C", "sol": "以 4 V 電源右端為 0 V，則左端為 4 V。對上方節點與右節點分別列 KCL，解得上方節點 20/3 V、右節點 22/3 V。最下面那個 2 Ω 兩端是右節點與左節點，I = (22/3 - 4)/2 ≈ 1.67 A。"}, {"n": 6, "img": "112P1_6.webp", "ans": "A", "sol": "設下方導線為 0 V。對左節點：1 = VP/2 + i(流向 4 V 電源那條支路)；4 V 電源左負右正所以中間節點 = VP + 4，再經 1 Ω 到右節點：VR = VP + 4 - i。對右節點：2 + i = VR/3。三式解得 VP = 2 V、i = 0、VR = 6 V。所以 Ia = 2/2 = 1 A、Ib = 6/3 = 2 A。"}, {"n": 7, "img": "112P1_7.webp", "ans": "D", "sol": "設下方導線為 0 V，4 V 電源上方為正所以左節點 = 4 V。對最右節點列 KCL：上方來的 4 A、下方來的 2 A 都流進去，所以經 2 Ω 流出的必須是 6 A，得右節點比中節點高 12 V。再對中節點列 KCL 解得中節點 = 8 V。最後對左節點：I = 4 + (4 - 8)/1 = 0 A。"}, {"n": 8, "img": "112P1_8.webp", "ans": "D", "sol": "C2 與 C3 並聯 = 20 + 30 = 50 μF，再與 C1 = 10 μF 串聯：總電容 = 10 × 50/60 ≈ 8.33 μF。總電荷 Q = 8.33 μ × 120 = 1000 μC，串聯各段電荷相同。V1 = 1000/10 = 100 V、V2 = 1000/50 = 20 V。"}, {"n": 9, "img": "112P1_9.webp", "ans": "C", "sol": "無互感時電感直接相加：L = 12 + 8 = 20 mH。W = (1/2) L I^2 = 0.5 × 0.02 × 20^2 = 4 J。"}, {"n": 10, "img": "112P1_10.webp", "ans": "C", "sol": "RC 電路的時間常數 τ = R × C = 2000 × 25 × 10^-6 = 0.05 秒 = 50 ms。"}, {"n": 11, "img": "112P1_11.webp", "ans": "B", "sol": "先統一成 sin。(B) 的 v1 = 20cos(314t - 60度) = 20sin(314t + 30度)，v2 = 20sin(314t - 30度)，相角差 30 - (-30) = 60 度，v1 確實超前 v2 60 度。(A) 算出來是 v1 落後 60 度、(C) 只差 30 度、(D) 差 120 度。"}, {"n": 12, "img": "112P1_12.webp", "ans": "A", "sol": "ω = 2，所以 2 H 是 j4 Ω、1/8 F 是 -j4 Ω。右邊支路 j4 + (-j4) + 4 = 4 Ω 剛好抵消成純電阻。12 Ω 與 4 Ω 並聯 = 3 Ω，總阻抗 = j4 + 3，大小 5 Ω。v(t) 的有效值 10 V，總電流 = 10/5 = 2 A，並聯段電壓 = 2 × 3 = 6 V，12 Ω 的電流 = 6/12 = 0.5 A。"}, {"n": 13, "img": "112P1_13.webp", "ans": "C", "sol": "Z = 6 + j(20 - 12) = 6 + j8，大小 10 Ω。電源有效值 100 V，所以 I = 10 A。平均功率 P = 10^2 × 6 = 600 W、視在功率 S = 100 × 10 = 1000 VA。瞬時功率 p(t) 在 P 上下擺動，振幅就是 S，所以最大瞬間功率 = P + S = 600 + 1000 = 1600 W。"}, {"n": 14, "img": "112P1_14.webp", "ans": "B", "sol": "右支路阻抗 8 - j6 大小 10 Ω，電流 10 A，所以電源電壓 = 10 × 10 = 100 V。左支路 3 + j4 大小 5 Ω，電流 = 100/5 = 20 A。P = 20^2 × 3 + 10^2 × 8 = 1200 + 800 = 2000 W。Q = 20^2 × 4 + 10^2 × (-6) = 1600 - 600 = 1000 VAR(電容的虛功率要取負)。"}, {"n": 15, "img": "112P1_15.webp", "ans": "A", "sol": "XL = ω L = 1000 × 6 mH = 6 Ω，Z = 6 + j6，大小 6√2 Ω、相角 45 度。電壓振幅 120 V，所以電流振幅 = 120/(6√2) = 10√2 A；電流相角 = 60 度 - 45 度 = 15 度。i(t) = 10√2 sin(1000t + 15度) A。"}, {"n": 16, "img": "112P1_16.webp", "ans": "C", "sol": "電流有效值最大就是串聯諧振，此時 XL = XC。XL = 2000 × 20 mH = 40 Ω，令 1/(ωC) = 40，C = 1/(2000 × 40) = 12.5 μF。"}, {"n": 17, "img": "112P1_17.webp", "ans": "D", "sol": "(A) 並聯諧振時總阻抗最大，總電流最小。(B) Q 愈大頻帶寬度愈窄(BW = f0/Q)。(C) 總導納最小才對。(D) 諧振時電感與電容的虛功率大小相等、方向相反互相抵消，正確。"}, {"n": 18, "img": "112P1_18.webp", "ans": "C", "sol": "五環色碼前三環是有效數字、第四環是乘數、第五環是誤差。R = 12.4/0.02 = 620 Ω。(A) 藍紅黑棕 = 620 × 10 = 6200 Ω。(B) 藍灰黑金 = 680 × 0.1 = 68 Ω。(C) 藍紅黑黑 = 620 × 1 = 620 Ω，正確。(D) 藍紫黑銀 = 670 × 0.01 = 6.7 Ω。"}, {"n": 19, "img": "112P1_19.webp", "ans": "D", "sol": "兩條對角線只是交叉並沒有相接，所以左上和右下是同一點、左下和右上是同一點。設左下(右上)為 0 V、左上(右下)為 V。左支路是 2 Ω 串 8 V(上正)，右支路只有 2 Ω。對左上這個節點列 KCL：流出的 2 A(上方電源) + 左支路電流 + I = 流入的 4 A(下方電源)，而左支路電流 = (V - 8)/2、I = V/2，得 (V-8)/2 + V/2 = 2，V = 6 V。I = 6/2 = 3 A。"}, {"n": 20, "img": "112P1_20.webp", "ans": "A", "sol": "穩態時電感視同短路，iL 的終值 = IS = 10 A，而這個終值就是 ES/RS，所以 ES = 10 × 2 = 20 V。RL 電路的時間常數 τ = L/R，0.02 = LS/2，得 LS = 0.04 H = 40 mH。"}, {"n": 21, "img": "112P1_21.webp", "ans": "D", "sol": "峰對峰 20 V。由圖上量，波形上下各離 0 V 線 2 格，峰對峰共 4 格，所以垂直刻度 = 20/4 = 5 V/DIV。頻率 500 Hz 表示週期 2 ms，圖上一個完整週期佔 4 格，所以水平刻度 = 2 ms/4 = 0.5 ms/DIV。探棒 1:1 不必換算。"}, {"n": 22, "img": "112P1_22.webp", "ans": "D", "stem": "112P1_s22-23.webp", "sol": "Δ 接法的相電壓就是線電壓 100 V，每相阻抗 3 + j4 大小 5 Ω，所以相電流 = 100/5 = 20 A。總消耗功率只算電阻：P = 3 × 20^2 × 3 = 3600 W。"}, {"n": 23, "img": "112P1_23.webp", "ans": "A", "stem": "112P1_s22-23.webp", "sol": "V 相的線斷掉後，U-W 之間那一相仍然直接跨在 100 V 上，電流還是 20 A；另外兩相(U-V 與 V-W)變成串聯後一起跨在這 100 V 上，總阻抗 2 × (3 + j4) 大小 10 Ω，電流 10 A。P = 20^2 × 3 + 2 × (10^2 × 3) = 1200 + 600 = 1800 W，剛好剩一半。"}, {"n": 24, "img": "112P1_24.webp", "ans": "A", "stem": "112P1_s24-25.webp", "sol": "R3 與 RL 串聯 = 4 + 2 = 6 Ω，和 R1 = 6 Ω、R2 = 12 Ω 三者並聯接在電流源上。總電導 = 1/6 + 1/12 + 1/6 = 5/12，端電壓 = 60/(5/12) = 144 V。I1 = 144/6 = 24 A、I2 = 144/12 = 12 A。"}, {"n": 25, "img": "112P1_25.webp", "ans": "B", "stem": "112P1_s24-25.webp", "sol": "把 RL 拿掉求戴維寧等效：電流源 60 A 全部流過 R1 並 R2 = 4 Ω，開路電壓 Vth = 60 × 4 = 240 V(R3 沒有電流所以沒有壓降)；等效電阻 Rth = (R1 並 R2) + R3 = 4 + 4 = 8 Ω。最大功率轉移時 RL = Rth = 8 Ω，Pmax = Vth^2/(4 Rth) = 240^2/32 = 1800 W。"}, {"n": 26, "img": "112P1_26.webp", "ans": "B", "sol": "工作週期 D = 高電位時間 / 週期 = t1/T = 3/5 = 60%(是百分比不是毫秒)。平均值 = Vp × D = 10 × 0.6 = 6 V。"}, {"n": 27, "img": "112P1_27.webp", "ans": "C", "sol": "(A) 因電位差而移動形成的是漂移電流，因濃度差才叫擴散電流。(B) 外質半導體摻雜後多數載子遠多於少數載子，濃度不同。(C) P 型矽是在本質矽中摻入三價元素(如硼)產生電洞，正確。(D) 半導體摻雜後整體仍呈電中性，不會帶負電位。"}, {"n": 28, "img": "112P1_28.webp", "ans": "A", "sol": "負載電流固定 IL = 20/2k = 10 mA。稽納最大電流 IZmax = 320 mW/20 V = 16 mA。串聯 1 kΩ 上的電流 = (VS - 20)/1k。VS 最小時稽納只剩膝點電流 2 mA：IR = 2 + 10 = 12 mA，VS = 20 + 12 × 1 = 32 V。VS 最大時稽納到 16 mA：IR = 26 mA，VS = 20 + 26 = 46 V。"}, {"n": 29, "img": "112P1_29.webp", "ans": "B", "sol": "飽和區時基-射極和基-集極兩個接面都是順向偏壓，集-射極間壓降很小(約 0.2 V)，等效上就像一個閉合的開關，所以 (B) 正確。(A)(C) 描述的是主動區；(D) 描述的是反向主動區。"}, {"n": 30, "img": "112P1_30.webp", "ans": "D", "sol": "基極迴路：0(接地) = IB × RB + VBE + VEE，即 0 = IB × 200k + 0.7 - 12，得 IB = 11.3/200k = 56.5 μA。IC = 100 × 56.5 μ = 5.65 mA。集極電阻接到地，電流由地經 RC 流進集極，所以 VC = 0 - IC × RC = -5.65 V。"}, {"n": 31, "img": "112P1_31.webp", "ans": "C", "sol": "C2 把 RF1 與 RF2 的接點交流接地，所以交流上 RF2 等於從地接到集極、和 RC 並聯；RE 被 C4 旁路，射極交流接地。gm = β/rπ = 100/1k = 100 mA/V。Av = -gm × (RC 並 RF2) = -0.1 × (3k 並 42k) = -0.1 × 2800 = -280。"}, {"n": 32, "img": "112P1_32.webp", "ans": "A", "sol": "(A) BJT 靠基極電流控制集極電流，FET 靠閘源極電壓控制汲極電流，正確。(B) FET 的閘極幾乎不吃電流，輸入阻抗遠比 BJT 高。(C) FET 的熱穩定度較佳，BJT 容易熱跑脫。(D) FET 只靠一種載子導電，是單載子元件。"}, {"n": 33, "img": "112P1_33.webp", "ans": "D", "sol": "gm = (2 IDSS/|Vp|) × (1 - VGS/Vp) = (2 × 10/3) × (1 - (-1)/(-3)) = 6.67 × (1 - 1/3) = 6.67 × 2/3 ≈ 4.44 mA/V。"}, {"n": 34, "img": "112P1_34.webp", "ans": "A", "sol": "閘極分壓：VG = 15 × 1M/(2M + 1M) = 5 V(閘極無電流)。由汲極電阻推電流：ID = (15 - 10.6)/2.2k = 2 mA。代 ID = K(VGS - Vt)^2：2 = 0.5 × (VGS - 2)^2，得 VGS - 2 = 2，VGS = 4 V。VS = VG - VGS = 5 - 4 = 1 V，RS = 1 V/2 mA = 0.5 kΩ。"}, {"n": 35, "img": "112P1_35.webp", "ans": "D", "sol": "RS 被 C3 旁路，所以是標準的共源極組態：Av = -gm × (RD 並 RL) = -2.4m × (2.2k 並 10k) = -2.4m × 1803 ≈ -4.33。(如果 RS 沒有旁路就要除以 1 + gm RS，別搞混。)"}, {"n": 36, "img": "112P1_36.webp", "ans": "B", "sol": "疊接(cascode)的下級 Q1 是共源極、上級 Q2 是共閘極(閘極被 C3 交流接地)，Q1 的汲極電流幾乎原封不動送到 Q2 的汲極。所以總增益只由 gm1 和 RD 決定：Av = -gm1 × RD = -25m × 2.7k = -67.5。gm2 在此不影響增益。"}, {"n": 37, "img": "112P1_37.webp", "ans": "B", "sol": "Q1、Q2 兩顆 PMOS 串聯在 VDD 與 Y 之間，Q3、Q4 兩顆 NMOS 並聯在 Y 與地之間，這是標準的 CMOS NOR 閘：只要 A 或 B 有一個是高電位，下面就有一顆 NMOS 導通把 Y 拉到低電位。所以 (B) 說 A 低 B 高時 Y 為高電位是錯的，應該是低電位。(A)(C)(D) 都正確。"}, {"n": 38, "img": "112P1_38.webp", "ans": "D", "sol": "運算放大器接成隨耦器(輸出經電晶體再回授到負端)，所以 VR = V+ = 10 V。Io = 1 mA 是 OPA 輸出推進基極的電流，射極電流 IE = (β + 1) IB = 100 × 1 mA = 100 mA。R = VR/IE = 10 V/100 mA = 100 Ω。"}, {"n": 39, "img": "112P1_39.webp", "ans": "A", "sol": "電容在輸入、電阻在回授，這是微分器：vo = -RC × dvs/dt。三角波 500 Hz，週期 2 ms，上升段在 1 ms 內由 -4 V 爬到 +4 V，斜率 = 8 V/1 ms = 8000 V/s。vo = -(100k × 0.01μ) × 8000 = -8 V；下降段斜率反號得 +8 V。峰對峰 = 8 - (-8) = 16 V。官方確認說明也是這樣算。"}, {"n": 40, "img": "112P1_40.webp", "ans": "B", "sol": "正端經 1 kΩ 接 4 V，因為 OPA 輸入不吃電流所以沒有壓降，V+ = 4 V，虛短路得 V- = 4 V。2 mA 電流源把 2 mA 灌進負端，這 2 mA 只能往回授路徑走：先經 1 kΩ 掉 2 V，到中間節點變成 4 - 2 = 2 V；再經 4 V 電源(左負右正)升 4 V，Vo = 2 + 4 = 6 V。"}, {"n": 41, "img": "112P1_41.webp", "ans": "B", "sol": "輸入接在負端，是反相型施密特。正端由 vo 經 40 kΩ 與接地的 10 kΩ 分壓：V+ = vo × 10/(10 + 40) = 0.2 vo。vo = +10 V 時門檻 = +2 V，這就是題目要的上臨界電壓；vo = -10 V 時門檻 = -2 V。遲滯電壓 = 2 - (-2) = 4 V。(題目用的 V 下標 TH 是上臨界電壓 threshold，不是戴維寧的 Vth，別混。)(10 kΩ 串在 vs 那一路不吃電流，不影響門檻。)"}, {"n": 42, "img": "112P1_42.webp", "ans": "C", "sol": "用反相放大器做 RC 相移振盪器時，每一節 RC 的相移一定小於 90 度，兩節最多不到 180 度湊不出來，所以最少要三節，(C) 說兩節可以是錯的。(A) 三節同值 RC 時回授衰減 1/29，放大器增益要 -29。(B) 反相放大器本身已經 180 度，回授網路也要再 180 度才能湊成 360 度。(D) 巴克豪森準則就是迴路增益 1 角度 0 度。"}, {"n": 43, "img": "112P1_43.webp", "ans": "C", "stem": "112P1_s43-44.webp", "sol": "三角波產生電路的標準做法是：施密特觸發器產生方波，方波再送進積分器變成三角波，積分器輸出又回去驅動施密特，形成自激，所以 (C) 正確。(A) 施密特觸發器是正回授。(B) 方波產生電路是施密特加 RC 充放電(積分形式)不是微分器。(D) 只有電阻沒有電容無法產生三角波。"}, {"n": 44, "img": "112P1_44.webp", "ans": "C", "stem": "112P1_s43-44.webp", "sol": "哈特萊振盪器是用 2 個電感 1 個電容的 LC 弦波振盪器，產生的是弦波不是方波，所以 (C) 錯誤。(A) 弦波振盪要滿足巴克豪森準則。(B) 晶體振盪器的 Q 值極高，頻率精準穩定。(D) 考畢子振盪器用 2 個電容 1 個電感，和哈特萊剛好相反。"}, {"n": 45, "img": "112P1_45.webp", "ans": "D", "sol": "變壓器一次側 120 V 對應二次側 0-12-24 V，但實際輸入只有 100 V，所以二次側全繞組 = 100 × 24/120 = 20 V，中心抽頭各半 = 10 V(有效值)，峰值 10√2 V。這是中心抽頭全波整流：(A) 平均值 = 2Vm/π = 20√2/π V 不是 20/π。(B) 全波整流輸出有效值 = Vm/√2 = 10 V 不是 12 V。(C) 漣波頻率是電源的兩倍 = 100 Hz。(D) 漣波週期 = 1/100 = 0.01 秒，正確。"}, {"n": 46, "img": "112P1_46.webp", "ans": "C", "sol": "(C) 輸入耦合切到 AC 時會串一個電容把直流成分擋掉，螢幕上只剩交流成分，正確。(A) EXT 是外部觸發輸入端，不能拿來量電流。(B) DC 耦合是直流交流一起顯示，不是只能量直流。(D) 垂直方向量的是電壓振幅，週期要看水平方向。"}, {"n": 47, "img": "112P1_47.webp", "ans": "D", "sol": "先看相位：CH1 一開始往上、CH2 一開始往下，兩者反相，所以增益是負的，只可能是 (C) 或 (D)。再看大小：CH1 上下各 1.5 格，峰對峰 3 格 × 50 mV = 150 mV。若增益是 15，輸出峰對峰應該只有 15 × 0.15 = 2.25 V 也就是 2.25 格；但圖上 CH2 的峰對峰超過 4 格(約 4.35 格 × 1 V ≈ 4.35 V)，4.35/0.15 ≈ 29。所以答案是 -29。"}, {"n": 48, "img": "112P1_48.webp", "ans": "D", "sol": "由射極電阻求 IE = VE/RE = 2.04/1k = 2.04 mA；由集極電阻求 IC = (20 - 16)/2k = 2 mA。IB = IE - IC = 0.04 mA，β = IC/IB = 2/0.04 = 50。也可以用基極驗算：VB = VE + 0.7 = 2.74 V，IB = (20 - 2.74)/431.5k = 0.04 mA，吻合。"}, {"n": 49, "img": "112P1_49.webp", "ans": "C", "stem": "112P1_s49-50.webp", "sol": "第二級分壓：Rth2 = 90k 並 18k = 15 kΩ、Vth2 = 12 × 18/108 = 2 V。基極迴路：IB2 = (2 - 0.7)/(15k + (β+1) RE2) = 1.3/(15k + 100 × 0.663k) = 1.3/81.3k ≈ 0.016 mA，IC2 = 99 × 0.016 ≈ 1.58 mA、IE2 ≈ 1.6 mA。工作點在負載線中點表示 VCE2 = 12/2 = 6 V，由 12 = IC2 RC2 + 6 + IE2 RE2 得 IC2 RC2 = 6 - 1.6 × 0.663 ≈ 4.94 V，RC2 ≈ 4.94/1.58 ≈ 3.12 kΩ。官方確認說明也是用這個精確解法。"}, {"n": 50, "img": "112P1_50.webp", "ans": "B", "stem": "112P1_s49-50.webp", "sol": "第一級的偏壓：Rth1 = 15 kΩ、Vth1 = 2 V，IB1 = 1.3/(15k + 200 × 1.3k) = 1.3/275k ≈ 4.73 μA，IE1 = 200 × 4.73 μ ≈ 0.945 mA。re = VT/IE = 26 mV/0.945 mA ≈ 27.5 Ω，rπ = (β + 1) re = 200 × 27.5 = 5.5 kΩ。RE1 被 10 μF 旁路所以不進輸入阻抗。Zin = 90k 並 18k 並 rπ = 15k 並 5.5k ≈ 4.02 kΩ。"}]});
EXAM.push({"code": "111P1", "y": 111, "p": "P1", "sub": "基本電學、基本電學實習、電子學、電子學實習", "items": [{"n": 1, "img": "111P1_1.webp", "ans": "C", "sol": "b 和 d 之間是一條導線直接相連，所以 Vb = Vd = 0。右邊 3 V 電源上負下正，Va = -3 V；中間 6 V 電源左負右正，Vc = -6 V。(三個電阻只決定電流，不影響這四點電位。)於是 Vab = -3 V、Vbc = 6 V、Vac = 3 V、Vca = -3 V、Vba = 3 V。逐一比較只有 Vbc > Vac 成立。"}, {"n": 2, "img": "111P1_2.webp", "ans": "D", "sol": "由 R1：180 = I 平方 × 20，得主電流 I = 3 A。R2：360 = 3 平方 × R2，R2 = 40 Ω。R3：60 = V 平方/60，得 R3 兩端電壓 60 V、電流 1 A。R4 與 R3 並聯所以也是 60 V，電流 = 3 - 1 = 2 A，R4 = 60/2 = 30 Ω。E = 3 × (20 + 40) + 60 = 240 V。"}, {"n": 3, "img": "111P1_3.webp", "ans": "C", "sol": "整條電熱線的電阻 = 120 的平方/600 = 24 Ω。電阻和長度成正比，剩下 2/3 長度的電阻 = 24 × 2/3 = 16 Ω。接到 48 V：P = 48 的平方/16 = 144 W。(不能直接用原來的 600 W 去乘比例，要先換成電阻再算。)"}, {"n": 4, "img": "111P1_4.webp", "ans": "B", "sol": "設下方節點為 0 V。10 V 電源上正，所以 5 mA 電流源下端那個節點 P = 10 V。5 mA 由 P 流出，只能繞上方的兩個 10 kΩ 流到 Q。設 Q 往下再經兩個 10 kΩ 回去的電流為 i，則 VQ = 20k × i。對 Q 列 KCL：5m + (10 - VQ)/10k = i，代入解得 i = 2 mA、VQ = 40 V。I 的箭頭由 Q 指向 P，I = (40 - 10)/10k = 3 mA。"}, {"n": 5, "img": "111P1_5.webp", "ans": "B", "sol": "左邊三個 6 Ω 構成三角形，轉成 Y 後每臂 6/3 = 2 Ω；右邊三個 12 Ω 轉成 Y 後每臂 12/3 = 4 Ω。於是由 20 V 電源看出去有兩條對稱路徑：上面那條 2 + 2 + 4 = 8 Ω，下面那條(經過底下 2 Ω 的那一路)也是 8 Ω，並聯後 4 Ω。總電阻 = 2 + 4 + 4 = 10 Ω，總電流 = 20/10 = 2 A，兩條路徑平分，所以底下那條的 I = 1 A。"}, {"n": 6, "img": "111P1_6.webp", "ans": "C", "sol": "設最下方導線為 0 V，電源 200 V。3 mA 電流源和 60 kΩ 串聯，所以那一支固定流 3 mA(由下往上)。設 20 kΩ 右端為 Q、下方 10 kΩ 右端為 T。對 T：(VQ - VT)/30k = 3m + VT/10k；對 Q：(200 - VQ)/20k + 3m = (VQ - VT)/30k。解得 VT ≈ 18.3 V、VQ ≈ 163.3 V，I = (200 - 163.3)/20k ≈ 1.8 mA。"}, {"n": 7, "img": "111P1_7.webp", "ans": "A", "sol": "先把 a、b 短路求 In，用重疊定理：只留 2 A 電流源(18 V 短路)時 Iab = 2 A；只留 18 V(2 A 開路)時，18 V 看到的是 18 Ω 與 9 Ω 並聯 = 6 Ω，Iab = 18/6 = 3 A。兩者相加 In = 5 A。求 Rn 時電壓源短路、電流源開路，由 a、b 看入是 6 Ω、9 Ω、18 Ω 三者並聯 = 3 Ω。(注意諾頓的代號是 In、Rn，戴維寧才是 Vth、Rth，別混用。)"}, {"n": 8, "img": "111P1_8.webp", "ans": "D", "sol": "平板電容 C = ε A/d。面積變成 1/2 會讓 C 變 1/2 倍，距離變成 2 倍會再讓 C 變 1/2 倍，合起來 C 變成原來的 1/2 × 1/2 = 0.25 倍。"}, {"n": 9, "img": "111P1_9.webp", "ans": "D", "sol": "原圖兩個線圈的一端互相連接、另外兩端拉出 a 與 b，是「串聯」接法，所以畫成並聯的 (A)(B) 先刪掉。剩下 (C)(D) 都是串聯，差別只在同名端的位置：(C) 兩個黑點都在左側，表示電流同時由兩個同名端流入，是串聯相助 Leq = L1 + L2 + 2M；(D) 黑點一個在 L1 靠 a 側、一個在 L2 靠 b 側，電流由 L1 的同名端進去卻由 L2 的同名端出來，是串聯互消 Leq = L1 + L2 - 2M。依圖(七)的繞製方向，兩個線圈產生的磁通互相抵消，屬於串聯互消，所以選 (D)。"}, {"n": 10, "img": "111P1_10.webp", "ans": "A", "sol": "一個週期 3 秒，三段各 1 秒，數值分別是 4 A、1 A、-2 A。平均值 = (4 + 1 - 2)/3 = 1 A。有效值要先平方再平均再開根號：根號((16 + 1 + 4)/3) = 根號7 A。(注意平均值算術平均會抵消負的部分，有效值不會。)"}, {"n": 11, "img": "111P1_11.webp", "ans": "B", "sol": "先對電容求戴維寧：把電容拿掉，60 V 經 60 kΩ 與 30 kΩ 分壓，Vth = 60 × 30/(60 + 30) = 20 V；Rth = (60k 並 30k) + 20k = 20k + 20k = 40 kΩ。時間常數 τ = 40k × 50μ = 2 秒，1/τ = 0.5。電容初值為零，所以 vc(t) = 20(1 - e 的 -0.5t 次方) V。"}, {"n": 12, "img": "111P1_12.webp", "ans": "D", "sol": "題目說 t = 0 前電感儲存能量為零，所以切換瞬間電感電流仍是 0 A(電感電流不能突變)。切到位置 2 之後迴路是 20 Ω 串 4 mH，時間常數 τ = L/R = 4 mH/20 Ω = 0.2 ms。所以初始電流 0 A、時間常數 0.2 ms。"}, {"n": 13, "img": "111P1_13.webp", "ans": "A", "sol": "電壓振幅 200√2、電流振幅 10，所以 |Z| = 200√2/10 = 20√2 Ω。電流相角 +45 度、電壓相角 0 度，電流超前 45 度表示是電容性，Z 的相角是 -45 度。Z = 20√2∠-45 度 = 20 - j20，所以 R = 20 Ω、Xc = 20 Ω。由 Xc = 1/(ωC)：C = 1/(500 × 20) = 100 μF。"}, {"n": 14, "img": "111P1_14.webp", "ans": "A", "sol": "並聯電路各支路電壓都是 240∠0 V，電流直接相加：流過 16 Ω 的是 240/16 = 15 A(同相)，流過 j12 Ω 的是 240/j12 = -j20 A(落後 90 度)。Is = 15 - j20 A。"}, {"n": 15, "img": "111P1_15.webp", "ans": "C", "sol": "由 a、b 看入是「4 Ω 串 j4 Ω」這一支，和 -j4 Ω 那一支並聯。Zab = (4 + j4)(-j4)/[(4 + j4) + (-j4)] = (16 - j16)/4 = 4 - j4 Ω。"}, {"n": 16, "img": "111P1_16.webp", "ans": "D", "sol": "有效值：V = 400/√2 = 200√2 V、I = 40/√2 = 20√2 A，相角差 60 度(電流落後)。S = 200√2 × 20√2 = 8000 VA = 8 kVA(所以 (A) 錯)。P = 8000 × cos60 度 = 4 kW(所以 (B) 錯)。Q = 8000 × sin60 度 = 4√3 kVAR(所以 (C) 錯)。最大瞬間功率 = P + S = 4 + 8 = 12 kW，(D) 正確。"}, {"n": 17, "img": "111P1_17.webp", "ans": "D", "sol": "S = P/PF = 4800/0.6 = 8000 VA。Y 接負載的線電流 = 8000/(√3 × 400) ≈ 11.55 A，相電壓 = 400/√3 ≈ 230.9 V，所以 |ZL| = 230.9/11.55 = 20 Ω。功率因數 0.6 落後對應相角 +53.1 度：ZL = 20(cos53.1 度 + j sin53.1 度) = 20(0.6 + j0.8) = 12 + j16 Ω。"}, {"n": 18, "img": "111P1_18.webp", "ans": "B", "sol": "負載 S = 5 kVA、P = 3 kW，所以 Q = 根號(5 平方 - 3 平方) = 4 kVAR(電感性)。要讓電源的功率因數變成 1，電容必須剛好供應 4 kVAR。電源有效值 200 V，Qc = V 平方/Xc：4000 = 200 平方/Xc，Xc = 40000/4000 = 10 Ω。"}, {"n": 19, "img": "111P1_19.webp", "ans": "C", "sol": "五色碼前三環是有效數字、第四環乘數、第五環誤差。棕棕黑橙 = 1、1、0 乘以 10 的 3 次方 = 110000 Ω = 110 kΩ(綠是 ±0.5% 誤差)。I = 110 V/110 kΩ = 1 mA。"}, {"n": 20, "img": "111P1_20.webp", "ans": "A", "sol": "檢流計電流為零表示電橋平衡，對臂乘積相等：R1 × Rx = R2 × R3，10k × Rx = 100k × 2k，Rx = 20 kΩ。(C) I1 流過 R1 + R3 = 12 kΩ、I2 流過 R2 + Rx = 120 kΩ，兩者相差十倍不會相等。(D) I2 = I4，而 I1 不等於 I2，所以也不等於 I4。"}, {"n": 21, "img": "111P1_21.webp", "ans": "A", "sol": "陶瓷電容的三位數字標示是「前兩位有效數字 + 第三位乘幾個零」，單位是 pF。203 = 20 × 10 的 3 次方 pF = 20000 pF = 20 nF；K 代表誤差 ±10%，所以量到 20.8 nF 很合理。(C) 的 203 nF 是把數字直接當成讀值，錯了。"}, {"n": 22, "img": "111P1_22.webp", "ans": "B", "sol": "示波器的 LEVEL 鈕是設定「觸發準位」，也就是訊號要跨過哪一個電壓值才開始掃描，用來讓波形停住不跑。亮度是 INTENSITY、水平位置是 HORIZONTAL POSITION、垂直位置是 VERTICAL POSITION，各有各的旋鈕。"}, {"n": 23, "img": "111P1_23.webp", "ans": "D", "sol": "煮飯 800 W 的電熱線電阻 = 110 平方/800 ≈ 15.1 Ω，保溫 40 W 的電阻 = 110 平方/40 = 302.5 Ω，同電壓下功率愈大電阻愈小，所以 (A)(B) 都錯。煮飯電流 = 800/110 ≈ 7.3 A，不是 3.6 A，(C) 錯。保溫電流 = 40/110 ≈ 0.36 A，(D) 正確。"}, {"n": 24, "img": "111P1_24.webp", "ans": "B", "stem": "111P1_s24-25.webp", "sol": "串聯諧振的品質因數 Q = ω0 L/Rs：5 = 2000 × L/4，得 L = 0.01 H = 10 mH。再由 ω0 = 1/根號(LC)：C = 1/(ω0 平方 × L) = 1/(2000 平方 × 0.01) = 25 × 10 的 -6 次方 F = 25 μF。"}, {"n": 25, "img": "111P1_25.webp", "ans": "C", "stem": "111P1_s24-25.webp", "sol": "諧振時電感抗與電容抗互相抵消，電路只剩 Rs，電流有效值 = 50/4 = 12.5 A。電容端電壓 = I × Xc = 12.5 × 1/(2000 × 25μ) = 12.5 × 20 = 250 V。更快的算法：諧振時電容(或電感)電壓 = Q × 電源電壓 = 5 × 50 = 250 V，這也是為什麼要特別注意電容的耐壓。"}, {"n": 26, "img": "111P1_26.webp", "ans": "A", "sol": "這個訊號是「直流 6 V 疊加一個振幅 8√2 的弦波」。平均值只看直流部分 = 6 V(弦波一個週期的平均是 0)。有效值要把直流與交流的有效值平方相加再開根號：根號(6 平方 + 8 平方) = 10 V。比值 = 10/6 ≈ 1.67。"}, {"n": 27, "img": "111P1_27.webp", "ans": "D", "sol": "R 上的電壓固定 = 12 - 6 = 6 V，所以流過 1 kΩ 的電流固定 6 mA，這 6 mA 要分給稽納和負載。負載電阻愈小代表負載電流愈大，而負載電流最大時稽納只能剩下膝點電流 1 mA，所以 IL(max) = 6 - 1 = 5 mA，RL(min) = 6 V/5 mA = 1.2 kΩ。"}, {"n": 28, "img": "111P1_28.webp", "ans": "D", "sol": "基極分壓：Vth = 20 × 10/(40 + 10) = 4 V、Rth = 40k 並 10k = 8 kΩ。IC = 2 mA 所以 IB = 2/100 = 0.02 mA、IE = 2.02 mA。列基極迴路：4 = 0.02m × 8k + 0.7 + 2.02m × RE，4 = 0.16 + 0.7 + 2.02m × RE，RE = 3.14/2.02m ≈ 1.55 kΩ。"}, {"n": 29, "img": "111P1_29.webp", "ans": "A", "sol": "這是射極隨耦器。先看基極看進去的阻抗：rπ + (β+1)(RE 並 RL) = 1k + 100 × (4k 並 4k) = 1k + 200k = 201 kΩ。輸入電流 ii 在 200 kΩ 偏壓電阻和基極之間分流，進入基極的 ib = ii × 200/(200 + 201) ≈ 0.5 ii。射極電流 ie = 100 ib ≈ 50 ii，再由 RE 與負載 4 kΩ 平分，io ≈ 25 ii。所以 io/ii ≈ 25。"}, {"n": 30, "img": "111P1_30.webp", "ans": "C", "sol": "先求偏壓：Vth = 12 × 5.7/(6.3 + 5.7) = 5.7 V、Rth = 6.3k 並 5.7k ≈ 3 kΩ。IB = (5.7 - 0.7)/(3k + 101 × 4k) = 5/407k ≈ 12.3 μA，IE ≈ 1.24 mA。re = VT/IE = 26 mV/1.24 mA ≈ 21 Ω。射極電阻被電容旁路，所以 Av = -RC/re = -2000/21 ≈ -95。"}, {"n": 31, "img": "111P1_31.webp", "ans": "C", "sol": "dB 要用「相加」不是相乘：總增益 = 20 + 40 + 20 = 80 dB。再換回倍數：80 = 20 log A，log A = 4，A = 10 的 4 次方 = 10000。(選項 (A) 的 80 是把 dB 當倍數，(D) 的 16000 是把各級倍數相乘時算錯。)"}, {"n": 32, "img": "111P1_32.webp", "ans": "A", "stem": "111P1_s32-34.webp", "sol": "圖中兩級之間用一顆 10 μF 電容把交流訊號送過去，而各級的直流偏壓則由電阻分壓決定，兩級的直流工作點互不影響，這就是典型的「電阻電容耦合(RC 耦合)」。直接耦合是兩級直接相連沒有電容，電感耦合要用變壓器。"}, {"n": 33, "img": "111P1_33.webp", "ans": "C", "stem": "111P1_s32-34.webp", "sol": "第一級的基極經 10 μF 接地、訊號由射極送入，是「共基極」組態，輸入阻抗很小。先求偏壓：Vth = 12 × 10/(62 + 10) ≈ 1.67 V、Rth = 62k 並 10k ≈ 8.6 kΩ，IB = (1.67 - 0.7)/(8.6k + 201 × 2k) ≈ 2.36 μA，IE ≈ 0.47 mA。re = VT/IE = 25 mV/0.47 mA ≈ 53 Ω。由 vi 看進去是 re 與 RE(2 kΩ)並聯 ≈ 51 Ω。"}, {"n": 34, "img": "111P1_34.webp", "ans": "A", "stem": "111P1_s32-34.webp", "sol": "第二級只有射極電阻 2 kΩ、集極直接接電源(沒有集極電阻)，輸出又是從射極取出，這是「射極隨耦器(共集極)」。射極隨耦器的電壓增益約等於 1(略小於 1)，它的用途是阻抗轉換而不是放大電壓。"}, {"n": 35, "img": "111P1_35.webp", "ans": "B", "sol": "P 通道元件要用絕對值來判斷。VGS = VG - VS = 0 - 3.3 = -3.3 V，|VGS| = 3.3 > |Vt| = 0.5，所以已經導通不是截止。過驅電壓 |VGS| - |Vt| = 2.8 V。VDS = VD - VS = 3.0 - 3.3 = -0.3 V，|VDS| = 0.3 < 2.8，沒有達到夾止，所以工作在歐姆區(線性區)。"}, {"n": 36, "img": "111P1_36.webp", "ans": "B", "sol": "負端只接了 5 kΩ 到地與 10 kΩ 回授，所以 V- = Vo × 5/(5 + 10) = Vo/3，由虛短路得 Vo = 3 V+。正端：V1、V2 各經 10 kΩ 進來，再經 Rs 到地，列 KCL 得 V+ = (V1 + V2)/(2 + 10k/Rs)。要 Vo = V1 + V2 就要 3/(2 + 10k/Rs) = 1，解得 10k/Rs = 1，Rs = 10 kΩ。"}, {"n": 37, "img": "111P1_37.webp", "ans": "C", "sol": "電容在輸入、電阻在回授，這是「微分電路」不是積分電路，所以 (A) 錯。方波微分後是尖脈波不是三角波，(B) 錯；三角波微分後是方波不是弦波，(D) 錯。弦波輸入時 vo = -RC dvi/dt，振幅 = ωRC × Vm，確實和 R、C 有關，(C) 正確。"}, {"n": 38, "img": "111P1_38.webp", "ans": "D", "sol": "前半段是 R1 進、C1 對地，後面接電壓隨耦器，屬低通，決定高頻截止點 fH = 1/(2π R1 C1)；後半段是 C2 串聯、R2 對地，屬高通，決定低頻截止點 fL = 1/(2π R2 C2)。fH/fL = (R2 C2)/(R1 C1) = (4R1 × 5C1)/(R1 C1) = 20。"}, {"n": 39, "img": "111P1_39.webp", "ans": "B", "sol": "左半邊是兩顆 PMOS 並聯在上、兩顆 NMOS 串聯在下，這是標準的 CMOS 反及閘，輸出 = (AB)反。再接右邊那一組 PMOS 加 NMOS 組成的反相器，把它再反一次，所以 Y = AB，是一個及閘。"}, {"n": 40, "img": "111P1_40.webp", "ans": "A", "sol": "逐段比對：兩個輸入同時為高時 Y 是低、同時為低時 Y 也是低，只有兩者不同時 Y 才是高，這就是互斥或(XOR)的特性。及閘在兩者皆高時應該輸出高、或閘在兩者皆高時也是高，都和波形不符；反及閘在兩者皆低時會輸出高，也不符。"}, {"n": 41, "img": "111P1_41.webp", "ans": "A", "sol": "+ 端的回授網路是「R2 串 C2」對「R1 並 C1」，這是韋恩電橋振盪器。回授比 β = 1/(1 + R2/R1 + C1/C2) = 1/(1 + 3 + 3) = 1/7。要起振必須 Aβ ≥ 1，所以放大器增益 A ≥ 7；這裡是非反相放大器 A = 1 + R4/R3，所以 1 + R4/R3 ≥ 7，R4/R3 ≥ 6。"}, {"n": 42, "img": "111P1_42.webp", "ans": "C", "sol": "叫叫 CABD 裡：C 是 Compression 胸部按壓、A 是 Airway 暢通呼吸道、B 是 Breathing 人工呼吸、D 是 Defibrillation 使用 AED 電擊。所以 B 是實施人工呼吸。"}, {"n": 43, "img": "111P1_43.webp", "ans": "B", "sol": "直流平均值 Vdc = (16 + 12)/2 = 14 V，漣波峰對峰值 = 16 - 12 = 4 V。鋸齒波的有效值 = 峰對峰值/(2√3) = 4/3.46 ≈ 1.15 V。漣波百分率 = 1.15/14 × 100% ≈ 8%。(若直接用 4/14 會得到 28%，那是沒有換成有效值的錯誤算法。)"}, {"n": 44, "img": "111P1_44.webp", "ans": "C", "stem": "111P1_s44-45.webp", "sol": "先假設在主動區：IB = (10 - 0.7)/372k = 25 μA，IC = 100 × 25μ = 2.5 mA，VC = 10 - 2.5m × 4.7k = -1.75 V，出現負值表示假設錯誤，電晶體其實已經飽和。飽和時 VBE(sat) = 0.8 V 所以 VB = 0.8 V、VCE(sat) = 0.2 V 所以 VC = 0.2 V。VBC = VB - VC = 0.8 - 0.2 = 0.6 V(基極比集極高，集-基接面順偏，正是飽和的特徵)。"}, {"n": 45, "img": "111P1_45.webp", "ans": "B", "stem": "111P1_s44-45.webp", "sol": "RB 改成 1 MΩ：IB = (10 - 0.7)/1M = 9.3 μA，IC = 100 × 9.3μ = 0.93 mA，VC = 10 - 0.93m × 4.7k ≈ 10 - 4.37 = 5.6 V。VC = 5.6 V 遠大於 VCE(sat) = 0.2 V，確實在主動區，這才是適合做線性放大的工作點。"}, {"n": 46, "img": "111P1_46.webp", "ans": "D", "sol": "疊接(cascode)的最大好處就是：共源極那一級的汲極接到共閘極的射入端，看到的負載阻抗很小(約 1/gm)，所以共源極本身的電壓增益很小，閘-汲極間的米勒電容被放大的倍數也就很小，高頻響應因此大幅改善，(D) 正確。(A) 總增益仍然很大。(B) 整體是反相的。(C) 共閘極組態的輸入阻抗很「低」，它不是用來提升輸入阻抗的。"}, {"n": 47, "img": "111P1_47.webp", "ans": "D", "sol": "共汲極就是源極隨耦器，電壓增益 = gm RS/(1 + gm RS)，一定小於 1 但很接近 1，而且輸出與輸入同相。所以輸入 1 V 峰對峰，輸出也約是 1 V 峰對峰(略小一點)。它的用途是做阻抗轉換(高輸入阻抗、低輸出阻抗)，不是放大電壓。"}, {"n": 48, "img": "111P1_48.webp", "ans": "C", "sol": "飽和區的 gm = 2K(VGS - Vt) = 2 × 2 mA/V 平方 × (3 - 1) V = 8 mA/V。(也可以先算 ID = K(VGS - Vt) 平方 = 2 × 4 = 8 mA，再用 gm = 2 根號(K × ID) = 2 根號(2 × 8) = 8 mA/V，結果相同。)"}, {"n": 49, "img": "111P1_49.webp", "ans": "A", "sol": "第一級是反相放大器：Vx = -(5k/R1) × Vi，-5 = -(5k/R1) × 1，所以 R1 = 1 kΩ。第二級把 Vx 送進 + 端，R2 接地、10 kΩ 回授，是非反相放大器：Vo = Vx × (1 + 10k/R2)，-10 = -5 × (1 + 10k/R2)，得 1 + 10k/R2 = 2，R2 = 10 kΩ。"}, {"n": 50, "img": "111P1_50.webp", "ans": "B", "sol": "vi 接在 - 端，而回授經 2 kΩ 接回 + 端，是正回授的反相型施密特。+ 端電位 = (Vref × 2k + vo × 1k)/(1k + 2k) = (2Vref + vo)/3，切換發生在 vi 等於這個值的時候。vo = -12 V 時得到的是下臨限電壓：(2Vref - 12)/3 = 0，解得 Vref = 6 V。(順便，上臨限電壓 = (12 + 12)/3 = 8 V。)"}]});
